export default "ributes: Mapping[str, Any] | None = None,\\n) -> Token[ModelProviderPolicyContext | None]:\\n    \\\"\\\"\\\"Bind trusted principal attributes to the current request/task context.\\\"\\\"\\\"\\n    return _current_context.set(ModelProviderPolicyContext(user_id=user_id, attributes=attributes or {}))\\n\\n\\ndef reset_current_model_provider_policy_context(token: Token[ModelProviderPolicyContext | None]) -> None:\\n    \\\"\\\"\\\"Restore the context that preceded ``set_current_model_provider_policy_context``.\\\"\\\"\\\"\\n    _current_context.reset(token)\\n\\n\\ndef current_model_provider_policy_context() -> ModelProviderPolicyContext | None:\\n    \\\"\\\"\\\"Return the principal bound to the current request/task, if any.\\\"\\\"\\\"\\n    return _current_context.get()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/model_provider_policy/service.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e262cc917c50568605810f3b28ee1b1a2468876062be2c001a7dce3371c3a884\",\"content\":\"\\\"\\\"\\\"Default OSS model-provider policy (allow all).\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING\\n\\nfrom lfx.log.logger import logger\\nfrom lfx.services import register_service\\nfrom lfx.services.model_provider_policy.base import BaseModelProviderPolicyService\\nfrom lfx.services.schema import ServiceType\\n\\nif TYPE_CHECKING:\\n    from collections.abc import Collection, Iterable\\n\\n    from lfx.services.model_provider_policy.base import ModelProviderPolicyContext, ModelProviderPolicyPurpose\\n    from lfx.services.policy_bundle import BasePolicyBundleService\\n\\n\\n@register_service(ServiceType.MODEL_PROVIDER_POLICY_SERVICE)\\nclass ModelProviderPolicyService(BaseModelProviderPolicyService):\\n    \\\"\\\"\\\"OSS default that preserves the historical allow-all behavior.\\\"\\\"\\\"\\n\\n    def __init__(self, policy_bundle_service: BasePolicyBundleService | None = None) -> None:\\n        super().__init__()\\n        self._policy_bundle_service = policy_bundle_service\\n        self._approved_provider_ids: frozenset[str] = frozenset()\\n        self._policy_version: int | None = None\\n        self._policy_source_available = True\\n        self.set_ready()\\n        logger.debug(\\\"Model provider policy service initialized (allow all)\\\")\\n\\n    @property\\n    def name(self) -> str:\\n        return ServiceType.MODEL_PROVIDER_POLICY_SERVICE.value\\n\\n    def get_allowed_provider_ids(\\n        self,\\n        *,\\n        context: ModelProviderPolicyContext,  # noqa: ARG002\\n        candidate_provider_ids: frozenset[str],\\n        purpose: ModelProviderPolicyPurpose,  # noqa: ARG002\\n    ) -> Collection[str]:\\n        with self._snapshot_cache_lock:\\n            if not self.policy_source_available:\\n                return frozenset()\\n            approved_provider_ids = self.approved_provider_ids\\n        if not approved_provider_ids:\\n            return candidate_provider_ids\\n        return candidate_provider_ids & approved_provider_ids\\n\\n    def get_blocked_model_keys(\\n        self,\\n        *,\\n        context: ModelProviderPolicyContext,  # noqa: ARG002\\n        purpose: ModelProviderPolicyPurpose,  # noqa: ARG002\\n    ) -> Collection[str]:\\n        \\\"\\\"\\\"Surface the deployment-wide blocked-model deny-list from the bundle.\\\"\\\"\\\"\\n        if self._policy_bundle_service is not None:\\n            return self._policy_bundle_service.snapshot.blocked_model_keys\\n        return frozenset()\\n\\n    @property\\n    def approved_provider_ids(self) -> frozenset[str]:\\n        \\\"\\\"\\\"Return the install-wide deployment ceiling; empty means unrestricted.\\\"\\\"\\\"\\n        if self._policy_bundle_service is not None:\\n            return self._policy_bundle_service.snapshot.approved_provider_ids\\n        return self._approved_provider_ids\\n\\n    @property\\n    def policy_version(self) -> int | None:\\n        \\\"\\\"\\\"Return the durable policy version last applied in this process.\\\"\\\"\\\"\\n        if self._policy_bundle_service is not None:\\n            return self._policy_bundle_service.snapshot.revision\\n        return self._policy_version\\n\\n    @property\\n    def policy_source_available(self) -> bool:\\n        \\\"\\\"\\\"Return whether the durable ceiling was available on the last refresh.\\\"\\\"\\\"\\n        if self._policy_bundle_service is not None:\\n            return self._policy_bundle_service.source_available\\n        return self._policy_source_available\\n\\n    @property\\n    def policy_bundle_service(self) -> BasePolicyBundleService | None:\\n        \\\"\\\"\\\"Return the shared bundle coordinator used by this service, if any.\\\"\\\"\\\"\\n        return self._policy_bundle_service\\n\\n    def fail_closed(self, *, deny_all_required: bool = False) -> bool:\\n        \\\"\\\"\\\"Deny providers after a refresh failure only when a ceiling is active.\\n\\n        An empty approved-provider set is the explicit OSS allow-all default. A\\n        transient refresh failure must not turn an unconfigured installation\\n        into deny-all, while an installation with a restrictive ceiling must\\n        keep failing closed until the durable source recovers. A caller sets\\n        ``deny_all_required`` when a newly read restrictive state failed during\\n        application or durable-source corruption makes the ceiling impossible\\n        to evaluate safely.\\n        \\\"\\\"\\\"\\n        if self._policy_bundle_service is not None:\\n            if not self.approved_provider_ids and not deny_all_required:\\n                return False\\n            changed = self._policy_bundle_service.mark_source_unavailable()\\n            if changed:\\n                self.invalidate()\\n            return changed\\n        with self._snapshot_cache_lock:\\n            if not self.approved_provider_ids and not deny_all_required:\\n                return False\\n            if not self._policy_source_available:\\n                return False\\n            self._policy_source_available = False\\n            self._snapshot_cache.clear()\\n            self._snapshot_cache_generation += 1\\n            return True\\n\\n    def set_approved_provider_ids(self, provider_ids: Iterable[str], *, version: int | None = None) -> bool:\\n        \\\"\\\"\\\"Replace the deployment ceiling atomically, rejecting stale versions.\\\"\\\"\\\"\\n        from lfx.base.models.provider_registry import resolve_provider_id\\n\\n        approved_provider_ids = frozenset(resolve_provider_id(provider_id) for provider_id in provider_ids)\\n        if self._policy_bundle_service is not None:\\n            current = self._policy_bundle_service.snapshot\\n            target_revision = current.revision if version is None else version\\n            if approved_provider_ids == current.approved_provider_ids and target_revision == current.revision:\\n                changed = self._policy_bundle_service.publish(current)\\n                if changed:\\n                    self.invalidate()\\n                return changed\\n            msg = \\\"Provider-only mutation is not allowed when a shared policy bundle is configured\\\"\\n            raise RuntimeError(msg)\\n        with self._snapshot_cache_lock:\\n            if version is not None and self._policy_version is not None and version < self._policy_version:\\n                return False\\n            if (\\n                approved_provider_ids == self._approved_provider_ids\\n                and (version is None or version == self._policy_version)\\n                and self._policy_source_available\\n            ):\\n                return False\\n            self._approved_provider_ids = approved_provider_ids\\n            self._policy_source_available = True\\n            if version is not None:\\n                self._policy_version = version\\n            self._snapshot_cache.clear()\\n            self._snapshot_cache_generation += 1\\n            return True\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/model_provider_policy/utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f9d98a5f23fcd5418dea1c89be2c6e1a8f4e2486d2932121461225dda59e70bc\",\"content\":\"\\\"\\\"\\\"Provider-name normalization and policy-service resolution.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING, Any\\n\\nfrom lfx.base.models.provider_registry import resolve_provider_id\\nfrom lfx.services.model_provider_policy.base import ModelProviderPolicyContext, ModelProviderPolicyPurpose\\n\\nif TYPE_CHECKING:\\n    from collections.abc import Iterable, Mapping\\n\\n    from lfx.services.model_provider_policy.base import ModelProviderPolicySnapshot\\n\\n\\ndef _policy_call_arguments(\\n    *,\\n    user_id,\\n    providers: Iterable[str],\\n    purpose: ModelProviderPolicyPurpose,\\n    attributes: Mapping[str, Any] | None,\\n) -> dict[str, Any]:\\n    \\\"\\\"\\\"Prepare the canonical candidates and effective request context.\\\"\\\"\\\"\\n    from lfx.services.model_provider_policy.context import current_model_provider_policy_context\\n\\n    effective_attributes = attributes\\n    if effective_attributes is None:\\n        principal = current_model_provider_policy_context()\\n        if principal is not None and str(principal.user_id) == str(user_id):\\n            effective_attributes = principal.attributes\\n\\n    # Preserve the OSS runtime's historical behavior for legacy or malformed\\n    # saved selections: registered names resolve to stable IDs, while unknown\\n    # names remain candidates that the allow-all default can pass through to\\n    # the existing validation path. Restrictive policies can still omit them.\\n    return {\\n        \\\"context\\\": ModelProviderPolicyContext(user_id=user_id, attributes=effective_attributes or {}),\\n        \\\"candidate_provider_ids\\\": frozenset(resolve_provider_id(provider) for provider in providers),\\n        \\\"purpose\\\": purpose,\\n    }\\n\\n\\ndef resolve_model_provider_policy(\\n    *,\\n    user_id,\\n    providers: Iterable[str],\\n    purpose: ModelProviderPolicyPurpose,\\n    attributes: Mapping[str, Any] | None = None,\\n) -> ModelProviderPolicySnapshot:\\n    \\\"\\\"\\\"Resolve a policy snapshot for provider names from any catalog surface.\\\"\\\"\\\"\\n    from lfx.services.deps import get_model_provider_policy_service\\n\\n    service = get_model_provider_policy_service()\\n    return service.resolve(\\n        **_policy_call_arguments(\\n            user_id=user_id,\\n            providers=providers,\\n            purpose=purpose,\\n            attributes=attributes,\\n        )\\n    )\\n\\n\\nasync def aresolve_model_provider_policy(\\n    *,\\n    user_id,\\n    providers: Iterable[str],\\n    purpose: ModelProviderPolicyPurpose,\\n    attributes: Mapping[str, Any] | None = None,\\n) -> ModelProviderPolicySnapshot:\\n    \\\"\\\"\\\"Resolve an immutable snapshot through an async-capable policy source.\\\"\\\"\\\"\\n    from lfx.services.deps import get_model_provider_policy_service\\n\\n    service = get_model_provider_policy_service()\\n    return await service.aresolve(\\n        **_policy_call_arguments(\\n            user_id=user_id,\\n            providers=providers,\\n            purpose=purpose,\\n            attributes=attributes,\\n        )\\n    )\\n\\n\\ndef require_model_provider(\\n    *,\\n    user_id,\\n    provider: str,\\n    purpose: ModelProviderPolicyPurpose = ModelProviderPolicyPurpose.USE,\\n    attributes: Mapping[str, Any] | None = None,\\n) -> ModelProviderPolicySnapshot:\\n    \\\"\\\"\\\"Require one provider before any secret lookup or network-capable import.\\\"\\\"\\\"\\n    snapshot = resolve_model_provider_policy(\\n        user_id=user_id,\\n        providers=[provider],\\n        purpose=purpose,\\n        attributes=attributes,\\n    )\\n    snapshot.require(provider)\\n    return snapshot\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/policy_bundle/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"05d999f529f54401595ebe77c429d092231504f9f3f26567a41621611c9f2d7b\",\"content\":\"from lfx.services.policy_bundle.base import BasePolicyBundleService, PolicyBundleSnapshot, policy_bundle_content_hash\\nfrom lfx.services.policy_bundle.service import PolicyBundleService\\n\\n__all__ = [\\n    \\\"BasePolicyBundleService\\\",\\n    \\\"PolicyBundleService\\\",\\n    \\\"PolicyBundleSnapshot\\\",\\n    \\\"policy_bundle_content_hash\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/policy_bundle/base.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0042ec0a88b1bfdca575fb9f65133cac75e18355856d3d99abfae36e7b5ca9fa\",\"content\":\"\\\"\\\"\\\"Stable process-local contract for shared deployment policy bundles.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport abc\\nimport hashlib\\nimport json\\nfrom dataclasses import dataclass\\nfrom typing import TYPE_CHECKING\\n\\nfrom lfx.services.base import Service\\nfrom lfx.services.schema import ServiceType\\n\\nif TYPE_CHECKING:\\n    from collections.abc import Collection\\n    from datetime import datetime\\n    from uuid import UUID\\n\\n\\ndef policy_bundle_content_hash(\\n    *,\\n    approved_provider_ids: Collection[str],\\n    blocked_component_keys: Collection[str],\\n    blocked_template_keys: Collection[str],\\n    blocked_model_keys: Collection[str] = (),\\n) -> str:\\n    \\\"\\\"\\\"Return the SHA-256 of the canonical complete decision payload.\\n\\n    ``blocked_model_keys`` joins the canonical payload only when non-empty so\\n    every revision hashed before the field existed keeps its stored hash, and\\n    a bundle without model blocks hashes identically across releases.\\n    \\\"\\\"\\\"\\n    payload = {\\n        \\\"approved_provider_ids\\\": sorted(set(approved_provider_ids)),\\n        \\\"blocked_component_keys\\\": sorted(set(blocked_component_keys)),\\n        \\\"blocked_template_keys\\\": sorted(set(blocked_template_keys)),\\n    }\\n    if blocked_model_keys:\\n        payload[\\\"blocked_model_keys\\\"] = sorted(set(blocked_model_keys))\\n    encoded = json.dumps(payload, sort_keys=True, separators=(\\\",\\\", \\\":\\\")).encode()\\n    return hashlib.sha256(encoded).hexdigest()\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass PolicyBundleSnapshot:\\n    \\\"\\\"\\\"One immutable provider-and-catalog policy revision.\\\"\\\"\\\"\\n\\n    revision: int = 0\\n    initialized: bool = False\\n    source: str = \\\"default\\\"\\n    approved_provider_ids: frozenset[str] = frozenset()\\n    blocked_component_keys: frozenset[str] = frozenset()\\n    blocked_template_keys: frozenset[str] = frozenset()\\n    blocked_model_keys: frozenset[str] = frozenset()\\n    content_hash: str = \\\"\\\"\\n    created_at: datetime | None = None\\n    created_by: UUID | None = None\\n    reason: str | None = None\\n    rollback_of_revision: int | None = None\\n\\n    def __post_init__(self) -> None:\\n        if self.revision < 0:\\n            msg = \\\"Policy bundle revision must not be negative\\\"\\n            raise ValueError(msg)\\n        object.__setattr__(self, \\\"approved_provider_ids\\\", frozenset(self.approved_provider_ids))\\n        object.__setattr__(self, \\\"blocked_component_keys\\\", frozenset(self.blocked_component_keys))\\n        object.__setattr__(self, \\\"blocked_template_keys\\\", frozenset(self.blocked_template_keys))\\n        object.__setattr__(self, \\\"blocked_model_keys\\\", frozenset(self.blocked_model_keys))\\n\\n\\nclass BasePolicyBundleService(Service, abc.ABC):\\n    \\\"\\\"\\\"Publish one immutable policy reference shared by all decision planes.\\\"\\\"\\\"\\n\\n    name = ServiceType.POLICY_BUNDLE_SERVICE.value\\n\\n    @property\\n    @abc.abstractmethod\\n    def snapshot(self) -> PolicyBundleSnapshot:\\n        \\\"\\\"\\\"Return the currently published complete policy revision.\\\"\\\"\\\"\\n\\n    @property\\n    @abc.abstractmethod\\n    def hydrated(self) -> bool:\\n        \\\"\\\"\\\"Return whether a durable revision has been published.\\\"\\\"\\\"\\n\\n    @property\\n    @abc.abstractmethod\\n    def source_available(self) -> bool:\\n        \\\"\\\"\\\"Return whether the last durable refresh succeeded.\\\"\\\"\\\"\\n\\n    @abc.abstractmethod\\n    def publish(self, snapshot: PolicyBundleSnapshot) -> bool:\\n        \\\"\\\"\\\"Atomically publish a non-stale complete revision.\\\"\\\"\\\"\\n\\n    @abc.abstractmethod\\n    def mark_source_unavailable(self) -> bool:\\n        \\\"\\\"\\\"Record a failed refresh without discarding last-known-good content.\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/policy_bundle/service.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7d2d0a0943b6b085d23901f23d466e39efffd31806c5c5cc220893a096793788\",\"content\":\"\\\"\\\"\\\"Default in-process coordinator for deployment policy bundles.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport threading\\n\\nfrom lfx.log.logger import logger\\nfrom lfx.services import register_service\\nfrom lfx.services.policy_bundle.base import BasePolicyBundleService, PolicyBundleSnapshot\\nfrom lfx.services.schema import ServiceType\\n\\n\\n@register_service(ServiceType.POLICY_BUNDLE_SERVICE)\\nclass PolicyBundleService(BasePolicyBundleService):\\n    \\\"\\\"\\\"Thread-safe owner of one immutable provider-and-catalog snapshot.\\\"\\\"\\\"\\n\\n    def __init__(self) -> None:\\n        super().__init__()\\n        self._snapshot = PolicyBundleSnapshot()\\n        self._hydrated = False\\n        self._source_available = True\\n        self._lock = threading.RLock()\\n        self.set_ready()\\n        logger.debug(\\\"Policy bundle service initialized\\\")\\n\\n    @property\\n    def name(self) -> str:\\n        return ServiceType.POLICY_BUNDLE_SERVICE.value\\n\\n    @property\\n    def snapshot(self) -> PolicyBundleSnapshot:\\n        return self._snapshot\\n\\n    @property\\n    def hydrated(self) -> bool:\\n        return self._hydrated\\n\\n    @property\\n    def source_available(self) -> bool:\\n        return self._source_available\\n\\n    def publish(self, snapshot: PolicyBundleSnapshot) -> bool:\\n        with self._lock:\\n            current = self._snapshot\\n            if snapshot.revision < current.revision:\\n                return False\\n            if snapshot.revision == current.revision:\\n                current_identity = (\\n                    current.initialized,\\n                    current.source,\\n                    current.approved_provider_ids,\\n                    current.blocked_component_keys,\\n                    current.blocked_template_keys,\\n                    current.blocked_model_keys,\\n                    current.content_hash,\\n                    current.reason,\\n                    current.rollback_of_revision,\\n                )\\n                snapshot_identity = (\\n                    snapshot.initialized,\\n                    snapshot.source,\\n                    snapshot.approved_provider_ids,\\n                    snapshot.blocked_component_keys,\\n                    snapshot.blocked_template_keys,\\n                    snapshot.blocked_model_keys,\\n                    snapshot.content_hash,\\n                    snapshot.reason,\\n                    snapshot.rollback_of_revision,\\n                )\\n                if snapshot_identity != current_identity:\\n                    msg = f\\\"Policy bundle revision {snapshot.revision} has conflicting content\\\"\\n                    raise ValueError(msg)\\n                changed = not self._source_available or not self._hydrated\\n                self._snapshot = snapshot\\n                self._source_available = True\\n                self._hydrated = snapshot.revision > 0\\n                return changed\\n            self._snapshot = snapshot\\n            self._hydrated = True\\n            self._source_available = True\\n            return True\\n\\n    def mark_source_unavailable(self) -> bool:\\n        with self._lock:\\n            if not self._source_available:\\n                return False\\n            self._source_available = False\\n            return True\\n\\n    async def teardown(self) -> None:\\n        with self._lock:\\n            self._snapshot = PolicyBundleSnapshot()\\n            self._hydrated = False\\n            self._source_available = True\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/registry.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ff02af0efb8367c6d375a89d8c70cdf5be5fc8dadb3ac1fde6b53b311c5a3314\",\"content\":\"\\\"\\\"\\\"Service registration decorator for pluggable services.\\n\\nAllows services to self-register with the service manager using a decorator.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING, TypeVar\\n\\nfrom lfx.log.logger import logger\\n\\nif TYPE_CHECKING:\\n    from lfx.services.base import Service\\n    from lfx.services.schema import ServiceType\\n\\nServiceT = TypeVar(\\\"ServiceT\\\", bound=\\\"Service\\\")\\n\\n\\ndef register_service(service_type: ServiceType, *, override: bool = True):\\n    \\\"\\\"\\\"Decorator to register a service class with the service manager.\\n\\n    Usage:\\n        @register_service(ServiceType.DATABASE_SERVICE)\\n        class DatabaseService(Service):\\n            name = \\\"database_service\\\"\\n            ...\\n\\n    Args:\\n        service_type: The ServiceType enum value for this service\\n        override: Whether to override existing registrations (default: True)\\n\\n    Returns:\\n        Decorator function that registers the service class\\n    \\\"\\\"\\\"\\n\\n    def decorator(service_class: type[ServiceT]) -> type[ServiceT]:\\n        \\\"\\\"\\\"Register the service class and return it unchanged.\\\"\\\"\\\"\\n        try:\\n            from lfx.services.manager import get_service_manager\\n\\n            service_manager = get_service_manager()\\n            service_manager.register_service_class(service_type, service_class, override=override)\\n            logger.debug(f\\\"Registered service via decorator: {service_type.value} -> {service_class.__name__}\\\")\\n        except ValueError:\\n            # Re-raise ValueError (used for settings service protection)\\n            raise\\n        except Exception as exc:  # noqa: BLE001\\n            logger.warning(f\\\"Failed to register service {service_type.value} from decorator: {exc}\\\")\\n\\n        return service_class\\n\\n    return decorator\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/schema.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9f971529cc24e2c8589689e381e9cfda53913afaf75987a551a23e25899c2a82\",\"content\":\"\\\"\\\"\\\"Service schema definitions for lfx package.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom enum import Enum\\n\\n\\nclass ServiceType(str, Enum):\\n    AUTH_SERVICE = \\\"auth_service\\\"\\n    AUTHORIZATION_SERVICE = \\\"authorization_service\\\"\\n    CATALOG_POLICY_SERVICE = \\\"catalog_policy_service\\\"\\n    MODEL_PROVIDER_POLICY_SERVICE = \\\"model_provider_policy_service\\\"\\n    POLICY_BUNDLE_SERVICE = \\\"policy_bundle_service\\\"\\n    DATABASE_SERVICE = \\\"database_service\\\"\\n    STORAGE_SERVICE = \\\"storage_service\\\"\\n    SETTINGS_SERVICE = \\\"settings_service\\\"\\n    VARIABLE_SERVICE = \\\"variable_service\\\"\\n    CACHE_SERVICE = \\\"cache_service\\\"\\n    TELEMETRY_SERVICE = \\\"telemetry_service\\\"\\n    TRACING_SERVICE = \\\"tracing_service\\\"\\n    STATE_SERVICE = \\\"state_service\\\"\\n    SESSION_SERVICE = \\\"session_service\\\"\\n    CHAT_SERVICE = \\\"chat_service\\\"\\n    TASK_SERVICE = \\\"task_service\\\"\\n    STORE_SERVICE = \\\"store_service\\\"\\n    JOB_QUEUE_SERVICE = \\\"job_queue_service\\\"\\n    SHARED_COMPONENT_CACHE_SERVICE = \\\"shared_component_cache_service\\\"\\n    MCP_COMPOSER_SERVICE = \\\"mcp_composer_service\\\"\\n    TRANSACTION_SERVICE = \\\"transaction_service\\\"\\n    FLOW_EVENTS_SERVICE = \\\"flow_events_service\\\"\\n    TELEMETRY_WRITER_SERVICE = \\\"telemetry_writer_service\\\"\\n    EXTENSION_EVENTS_SERVICE = \\\"extension_events_service\\\"\\n    CHECKPOINT_SERVICE = \\\"checkpoint_service\\\"\\n    EXECUTOR_SERVICE = \\\"executor_service\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/session.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3b0dcd23e8dc1a69b614e578e38d65ba20bf996cf16e4cd804ba81d546b4cd91\",\"content\":\"\\\"\\\"\\\"Lightweight session implementations for lfx package.\\\"\\\"\\\"\\n\\n\\nclass NoopSession:\\n    \\\"\\\"\\\"No-operation session that implements the database session interface.\\n\\n    This provides a complete database session API but all operations are no-ops.\\n    Perfect for testing or when no real database is available.\\n    \\\"\\\"\\\"\\n\\n    class NoopBind:\\n        class NoopConnect:\\n            async def __aenter__(self):\\n                return self\\n\\n            async def __aexit__(self, exc_type, exc, tb):\\n                pass\\n\\n            async def run_sync(self, fn, *args, **kwargs):  # noqa: ARG002\\n                return None\\n\\n        def connect(self):\\n            return self.NoopConnect()\\n\\n    bind = NoopBind()\\n\\n    async def connection(self):\\n        \\\"\\\"\\\"Return a no-op async connection for session-level database probes.\\\"\\\"\\\"\\n        return self.NoopBind.NoopConnect()\\n\\n    async def add(self, *args, **kwargs):\\n        pass\\n\\n    async def commit(self):\\n        pass\\n\\n    async def rollback(self):\\n        pass\\n\\n    async def execute(self, *args, **kwargs):  # noqa: ARG002\\n        return None\\n\\n    async def query(self, *args, **kwargs):  # noqa: ARG002\\n        return []\\n\\n    async def close(self):\\n        pass\\n\\n    async def refresh(self, *args, **kwargs):\\n        pass\\n\\n    async def delete(self, *args, **kwargs):\\n        pass\\n\\n    async def __aenter__(self):\\n        return self\\n\\n    async def __aexit__(self, exc_type, exc, tb):\\n        pass\\n\\n    async def get(self, *args, **kwargs):  # noqa: ARG002\\n        return None\\n\\n    async def exec(self, *args, **kwargs):  # noqa: ARG002\\n        class _NoopResult:\\n            def first(self):\\n                return None\\n\\n            def all(self):\\n                return []\\n\\n            def one_or_none(self):\\n                return None\\n\\n            def __iter__(self):\\n                return iter([])\\n\\n        return _NoopResult()\\n\\n    @property\\n    def no_autoflush(self):\\n        \\\"\\\"\\\"Context manager that disables autoflush (no-op implementation).\\\"\\\"\\\"\\n        return self\\n\\n    @property\\n    def is_active(self):\\n        \\\"\\\"\\\"Check if session is active (always True for NoopSession).\\\"\\\"\\\"\\n        return True\\n\\n    def __enter__(self):\\n        return self\\n\\n    def __exit__(self, exc_type, exc, tb):\\n        pass\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/settings/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"508481bce408aa80376bca29c09ad3429e0f493aa945e63a190ffb3ba5aea894\",\"content\":\"from . import factory, service\\n\\n__all__ = [\\\"factory\\\", \\\"service\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/settings/auth.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"afed375afb3c33d691915c41f804ad6b914bf0afc2a1858373783ff24858bcd2\",\"content\":\"import secrets\\nfrom enum import Enum\\nfrom pathlib import Path\\nfrom typing import Literal\\nfrom urllib.parse import urlparse\\n\\nfrom passlib.context import CryptContext\\nfrom pydantic import Field, SecretStr, field_validator, model_validator\\nfrom pydantic_settings import BaseSettings, SettingsConfigDict\\n\\nfrom lfx.log.logger import logger\\nfrom lfx.services.settings.constants import (\\n    DEFAULT_SUPERUSER,\\n    DEFAULT_SUPERUSER_PASSWORD,\\n    MINIMUM_SECRET_KEY_LENGTH,\\n    SHORT_SECRET_KEY_WARNING,\\n)\\nfrom lfx.services.settings.utils import (\\n    derive_public_key_from_private,\\n    generate_rsa_key_pair,\\n    read_secret_from_file,\\n    write_public_key_to_file,\\n    write_secret_to_file,\\n)\\n\\nASCII_CONTROL_CHARACTER_LIMIT = 0x20\\nASCII_DELETE_CHARACTER = 0x7F\\n\\n\\ndef _warn_if_secret_key_is_short(value: str | SecretStr) -> None:\\n    secret_value = value.get_secret_value() if isinstance(value, SecretStr) else value\\n    if len(secret_value) < MINIMUM_SECRET_KEY_LENGTH:\\n        logger.warning(SHORT_SECRET_KEY_WARNING)\\n\\n\\nclass JWTAlgorithm(str, Enum):\\n    \\\"\\\"\\\"JWT signing algorithm options.\\\"\\\"\\\"\\n\\n    HS256 = \\\"HS256\\\"\\n    RS256 = \\\"RS256\\\"\\n    RS512 = \\\"RS512\\\"\\n\\n    def is_asymmetric(self) -> bool:\\n        \\\"\\\"\\\"Return True if this algorithm uses asymmetric (public/private key) cryptography.\\\"\\\"\\\"\\n        return self in (JWTAlgorithm.RS256, JWTAlgorithm.RS512)\\n\\n\\nclass AuthSettings(BaseSettings):\\n    # Login settings\\n    CONFIG_DIR: str\\n    SECRET_KEY: SecretStr = Field(\\n        default=SecretStr(\\\"\\\"),\\n        description=\\\"Secret key for JWT (used with HS256). If not provided, a random one will be generated.\\\",\\n        frozen=False,\\n    )\\n    PRIVATE_KEY: SecretStr = Field(\\n        default=SecretStr(\\\"\\\"),\\n        description=\\\"RSA private key for JWT signing (RS256/RS512). Auto-generated if not provided.\\\",\\n        frozen=False,\\n    )\\n    PUBLIC_KEY: str = Field(\\n        default=\\\"\\\",\\n        description=\\\"RSA public key for JWT verification (RS256/RS512). Derived from private key if not provided.\\\",\\n    )\\n    ALGORITHM: JWTAlgorithm = Field(\\n        default=JWTAlgorithm.HS256,\\n        description=\\\"JWT signing algorithm. Use RS256 or RS512 for asymmetric signing (recommended for production).\\\",\\n    )\\n    ACCESS_TOKEN_EXPIRE_SECONDS: int = 60 * 60  # 1 hour\\n    REFRESH_TOKEN_EXPIRE_SECONDS: int = 60 * 60 * 24 * 7  # 7 days\\n\\n    # API Key to execute /process endpoint\\n    API_KEY_ALGORITHM: str = \\\"HS256\\\"\\n    API_V1_STR: str = \\\"/api/v1\\\"\\n\\n    # API Key Source Configuration\\n    API_KEY_SOURCE: Literal[\\\"db\\\", \\\"env\\\"] = Field(\\n        default=\\\"db\\\",\\n        description=(\\n            \\\"Source for API key validation. \\\"\\n            \\\"'db' validates against database-stored API keys (default behavior). \\\"\\n            \\\"'env' validates against the LANGFLOW_API_KEY environment variable.\\\"\\n        ),\\n    )\\n\\n    AUTO_LOGIN: bool = Field(\\n        default=True,  # TODO: Set to False in v2.0\\n        description=(\\n            \\\"Enable automatic login with a configured or generated bootstrap account. \\\"\\n            \\\"SECURITY WARNING: This bypasses authentication and should only be used in development environments. \\\"\\n            \\\"Set to False in production. This will default to False in v2.0.\\\"\\n        ),\\n    )\\n    \\\"\\\"\\\"If True, the application will attempt to log in automatically as a super user.\\\"\\\"\\\"\\n    skip_auth_auto_login: bool = False\\n    \\\"\\\"\\\"If True, the application will skip authentication when AUTO_LOGIN is enabled.\\n    This will be removed in v2.0\\\"\\\"\\\"\\n\\n    WEBHOOK_AUTH_ENABLE: bool = True\\n    \\\"\\\"\\\"If True, webhook endpoints will require API key authentication.\\n    If False, webhooks run as flow owner without authentication.\\n    Defaults to True for secure-by-default behavior; set to False only in\\n    trusted environments where unauthenticated webhook execution is acceptable.\\\"\\\"\\\"\\n\\n    ENABLE_SUPERUSER_CLI: bool = Field(\\n        default=True,\\n        description=\\\"Allow creation of superusers via CLI. Set to False in production for security.\\\",\\n    )\\n    \\\"\\\"\\\"If True, allows creation of superusers via the CLI 'langflow superuser' command.\\\"\\\"\\\"\\n\\n    NEW_USER_IS_ACTIVE: bool = False\\n\\n    ENABLE_SIGNUP: bool = Field(\\n        default=True,\\n        description=(\\n            \\\"Whether public self-registration via POST /api/v1/users/ is allowed. \\\"\\n            \\\"Always refused when AUTO_LOGIN is enabled (single-user mode has no signup \\\"\\n            \\\"concept); operators running multi-user instances can set this to False to \\\"\\n            \\\"disable public sign up entirely. Authenticated superusers can still create \\\"\\n            \\\"users regardless of this setting.\\\"\\n        ),\\n    )\\n    \\\"\\\"\\\"If True, public self-registration via POST /api/v1/users/ is allowed.\\\"\\\"\\\"\\n\\n    SUPERUSER: str = DEFAULT_SUPERUSER\\n    # Store password as SecretStr to prevent accidental plaintext exposure\\n    SUPERUSER_PASSWORD: SecretStr = Field(default=DEFAULT_SUPERUSER_PASSWORD)\\n\\n    REFRESH_SAME_SITE: Literal[\\\"lax\\\", \\\"strict\\\", \\\"none\\\"] = \\\"lax\\\"\\n    \\\"\\\"\\\"The SameSite attribute of the refresh token cookie.\\\"\\\"\\\"\\n    REFRESH_SECURE: bool = False\\n    \\\"\\\"\\\"The Secure attribute of the refresh token cookie.\\\"\\\"\\\"\\n    REFRESH_HTTPONLY: bool = True\\n    \\\"\\\"\\\"The HttpOnly attribute of the refresh token cookie.\\\"\\\"\\\"\\n    ACCESS_SAME_SITE: Literal[\\\"lax\\\", \\\"strict\\\", \\\"none\\\"] = \\\"lax\\\"\\n    \\\"\\\"\\\"The SameSite attribute of the access token cookie.\\\"\\\"\\\"\\n    ACCESS_SECURE: bool = False\\n    \\\"\\\"\\\"The Secure attribute of the access token cookie.\\\"\\\"\\\"\\n    ACCESS_HTTPONLY: bool = True\\n    \\\"\\\"\\\"The HttpOnly attribute of the access token cookie.\\\"\\\"\\\"\\n\\n    COOKIE_DOMAIN: str | None = None\\n    \\\"\\\"\\\"The domain attribute of the cookies. If None, the domain is not set.\\\"\\\"\\\"\\n\\n    # SSO Feature Flags\\n    SSO_ENABLED: bool = Field(\\n        default=False,\\n        description=\\\"Enable SSO authentication. Disabled by default. Set to true to enable SSO.\\\",\\n    )\\n    \\\"\\\"\\\"If True, SSO authentication is enabled. Configuration must be provided via SSO_CONFIG_FILE.\\\"\\\"\\\"\\n\\n    SSO_PROVIDER: str = Field(\\n        default=\\\"jwt\\\",\\n        description=\\\"SSO provider type: jwt (default), oidc, saml, ldap\\\",\\n    )\\n    \\\"\\\"\\\"The authentication provider to use. Default is 'jwt' for standard authentication.\\\"\\\"\\\"\\n\\n    SSO_CONFIG_FILE: str | None = Field(\\n        default=None,\\n        description=\\\"Path to SSO configuration file (YAML format). Required when SSO_ENABLED=true.\\\",\\n    )\\n    \\\"\\\"\\\"Path to YAML configuration file for SSO settings. Contains provider-specific configuration.\\\"\\\"\\\"\\n\\n    SSO_REDIRECT_URL: str | None = Field(\\n        default=None,\\n        description=\\\"Same-origin relative URL used after SSO authentication. Absolute URLs are rejected.\\\",\\n    )\\n\\n    # External trusted-identity settings.\\n    # Used when an upstream identity layer (proxy, gateway, IdP) issues or\\n    # validates a credential and Langflow needs to accept it and map it to\\n    # a local user via SSOUserProfile (JIT provisioning).\\n    EXTERNAL_AUTH_ENABLED: bool = Field(\\n        default=False,\\n        description=\\\"Enable trusted external request authentication and JIT local user mapping.\\\",\\n    )\\n    EXTERNAL_AUTH_PROVIDER: str = Field(\\n        default=\\\"external\\\",\\n        description=\\\"Stable provider key written to SSOUserProfile.sso_provider for external identities.\\\",\\n    )\\n    EXTERNAL_AUTH_TOKEN_HEADER: str = Field(\\n        default=\\\"Authorization\\\",\\n        description=(\\n            \\\"Header containing the external credential. The native Langflow JWT path is tried first; \\\"\\n            \\\"if it fails, the external path is attempted as a fallback. Bearer-prefixed values are supported.\\\"\\n        ),\\n    )\\n    EXTERNAL_AUTH_TOKEN_COOKIE: str | None = Field(\\n        default=None,\\n        description=\\\"Optional cookie name containing the external credential.\\\",\\n    )\\n    EXTERNAL_AUTH_IDENTITY_RESOLVER: str | None = Field(\\n        default=None,\\n        description=(\\n            \\\"Optional 'module:attribute' import path for a custom resolver that converts the external \\\"\\n            \\\"credential into an identity. Defaults to built-in JWT validation when unset.\\\"\\n        ),\\n    )\\n    EXTERNAL_AUTH_TRUSTED_JWT_DECODE: bool = Field(\\n        default=False,\\n        description=(\\n            \\\"When True, decode the external JWT without verifying its signature. ONLY safe behind a trusted \\\"\\n            \\\"upstream proxy that already validates the token. Off by default.\\\"\\n        ),\\n    )\\n    EXTERNAL_AUTH_JWKS_URL: str | None = Field(\\n        default=None,\\n        description=\\\"JWKS URL used to verify external JWT signatures when trusted decode is disabled.\\\",\\n    )\\n    EXTERNAL_AUTH_ISSUER: str | None = Field(\\n        default=None,\\n        description=\\\"Expected JWT issuer (iss). Leave empty to skip issuer validation.\\\",\\n    )\\n    EXTERNAL_AUTH_AUDIENCE: str | None = Field(\\n        default=None,\\n        description=\\\"Expected JWT audience (aud). Comma-separated audiences are supported.\\\",\\n    )\\n    EXTERNAL_AUTH_ALGORITHMS: str = Field(\\n        default=\\\"RS256\\\",\\n        description=\\\"Comma-separated JWT algorithms accepted for external JWT validation.\\\",\\n    )\\n    EXTERNAL_AUTH_SUBJECT_CLAIM: str = Field(\\n        default=\\\"sub\\\",\\n        description=\\\"JWT claim used as the stable external user id.\\\",\\n    )\\n    EXTERNAL_AUTH_USERNAME_CLAIM: str = Field(\\n        default=\\\"preferred_username\\\",\\n        description=\\\"JWT claim preferred for the local Langflow username on JIT provisioning.\\\",\\n    )\\n    EXTERNAL_AUTH_EMAIL_CLAIM: str = Field(\\n        default=\\\"email\\\",\\n        description=\\\"JWT claim containing the user's email.\\\",\\n    )\\n    EXTERNAL_AUTH_NAME_CLAIM: str = Field(\\n        default=\\\"name\\\",\\n        description=\\\"JWT claim containing the user's display name.\\\",\\n    )\\n    EXTERNAL_AUTH_GROUP_RECONCILE_INTERVAL_SECONDS: int = Field(\\n        default=60,\\n        ge=0,\\n        description=(\\n            \\\"Minimum seconds between external group reconciliations for one unchanged directory state. \\\"\\n            \\\"Bearer tokens arrive on every request, and reconciliation writes rows, takes policy locks and \\\"\\n            \\\"appends an audit entry, so an unchanged (provider, subject, group set) is only reconciled once \\\"\\n            \\\"per interval. A group set that differs from the last reconciled one always reconciles \\\"\\n            \\\"immediately. Set to 0 to reconcile on every request.\\\"\\n        ),\\n    )\\n    EXTERNAL_AUTH_ACCESS_CEILING_ENABLED: bool = Field(\\n        default=False,\\n        description=(\\n            \\\"Enable a coarse deny-only action ceiling for users authenticated by external trusted identity. \\\"\\n            \\\"This is not an RBAC engine; it only caps actions above a mapped access level.\\\"\\n        ),\\n    )\\n    EXTERNAL_AUTH_ACCESS_CLAIM: str | None = Field(\\n        default=None,\\n        description=(\\n            \\\"JWT claim used to derive the external access ceiling. Claim values are mapped through \\\"\\n            \\\"EXTERNAL_AUTH_ACCESS_CLAIM_MAPPING.\\\"\\n        ),\\n    )\\n    EXTERNAL_AUTH_ACCESS_CLAIM_MAPPING: str | None = Field(\\n        default=None,\\n        description=(\\n            \\\"JSON object or comma-separated value map from external claim values to one of: viewer, editor, admin. \\\"\\n            'Example: \\\\'{\\\"view\\\":\\\"viewer\\\",\\\"edit\\\":\\\"editor\\\"}\\\\'. Built-in aliases cover common values.'\\n        ),\\n    )\\n    EXTERNAL_AUTH_DEFAULT_ACCESS_LEVEL: str = Field(\\n        default=\\\"viewer\\\",\\n        description=\\\"Fallback access level used when the access claim is missing or unmapped.\\\",\\n    )\\n    EXTERNAL_AUTH_DISABLE_API_KEYS_FOR_EXTERNAL_USERS: bool = Field(\\n        default=True,\\n        description=(\\n            \\\"When the external access ceiling is enabled, reject Langflow API-key authentication for users mapped \\\"\\n            \\\"through the configured external provider so API keys cannot bypass the JWT claim ceiling.\\\"\\n        ),\\n    )\\n\\n    # Authorization (RBAC) feature flags \u2014 enforcement via authorization_service plugin\\n    AUTHZ_ENABLED: bool = Field(\\n        default=False,\\n        description=\\\"Enable authorization enforcement. Requires an authorization_service plugin.\\\",\\n    )\\n    AUTHZ_SUPERUSER_BYPASS: bool = Field(\\n        default=True,\\n        description=\\\"When True, active superusers bypass authorization checks (audited by the plugin).\\\",\\n    )\\n    AUTHZ_AUDIT_ENABLED: bool = Field(\\n        default=False,\\n        description=(\\n            \\\"Write an AuthzAuditLog row for every authorization decision and share-administration \\\"\\n            \\\"action. Independent of AUTHZ_ENABLED \u2014 set this to True while enforcement is off to \\\"\\n            \\\"observe traffic before flipping the AUTHZ_ENABLED flag. The default pipeline is \\\"\\n            \\\"best effort and may drop rows under sustained database failure or queue saturation.\\\"\\n        ),\\n    )\\n    AUTHZ_AUDIT_DURABLE: bool = Field(\\n        default=False,\\n        description=(\\n            \\\"Require every accepted authorization audit call to wait for its database commit. \\\"\\n            \\\"A full queue applies backpressure and persistence failures fail the triggering request \\\"\\n            \\\"with a sanitized error. Disabled by default to preserve the non-blocking OSS behavior; \\\"\\n            \\\"enable it before using authz_audit_log as a compliance or external-delivery source.\\\"\\n        ),\\n    )\\n    AUTHZ_AUDIT_RETENTION_DAYS: int = Field(\\n        default=90,\\n        ge=0,\\n        description=(\\n            \\\"Number of days to retain rows in ``authz_audit_log``. Older rows are deleted on \\\"\\n            \\\"startup and by the periodic cleanup task. Set to 0 to disable retention pruning \\\"\\n            \\\"(append-only \u2014 the table will grow without bound; pair with an external archival \\\"\\n            \\\"or partitioning job). The default of 90 days bounds steady-state size for typical \\\"\\n            \\\"enterprise deployments.\\\"\\n        ),\\n    )\\n    AUTHZ_AUDIT_CLEANUP_INTERVAL: int = Field(\\n        default=86400,\\n        ge=300,\\n        description=(\\n            \\\"Seconds between scheduled ``authz_audit_log`` retention sweeps. A sweep runs once at \\\"\\n            \\\"startup; thereafter a background worker prunes rows older than \\\"\\n            \\\"AUTHZ_AUDIT_RETENTION_DAYS every interval so a long-running instance stays bounded \\\"\\n            \\\"between restarts. The worker only runs when AUTHZ_AUDIT_ENABLED is True and \\\"\\n            \\\"AUTHZ_AUDIT_RETENTION_DAYS > 0. Default 86400 (daily); minimum 300 (5 minutes).\\\"\\n        ),\\n    )\\n\\n    pwd_context: CryptContext = CryptContext(schemes=[\\\"bcrypt\\\"], deprecated=\\\"auto\\\")\\n\\n    model_config = SettingsConfigDict(validate_assignment=True, extra=\\\"ignore\\\", env_prefix=\\\"LANGFLOW_\\\")\\n\\n    def reset_credentials(self) -> None:\\n        # Preserve the configured username but scrub the password from memory to avoid plaintext exposure.\\n        self.SUPERUSER_PASSWORD = SecretStr(\\\"\\\")\\n\\n    @field_validator(\\\"SECRET_KEY\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def get_secret_key(cls, value, info):\\n        config_dir = info.data.get(\\\"CONFIG_DIR\\\")\\n\\n        if not config_dir:\\n            logger.debug(\\\"No CONFIG_DIR provided, not saving secret key\\\")\\n            value = value or secrets.token_urlsafe(32)\\n            _warn_if_secret_key_is_short(value)\\n            return value\\n\\n        secret_key_path = Path(config_dir) / \\\"secret_key\\\"\\n\\n        if value:\\n            logger.debug(\\\"Secret key provided\\\")\\n            secret_value = value.get_secret_value() if isinstance(value, SecretStr) else value\\n            write_secret_to_file(secret_key_path, secret_value)\\n        elif secret_key_path.exists():\\n            value = read_secret_from_file(secret_key_path)\\n            logger.debug(\\\"Loaded secret key\\\")\\n            if not value:\\n                value = secrets.token_urlsafe(32)\\n                write_secret_to_file(secret_key_path, value)\\n                logger.debug(\\\"Saved secret key\\\")\\n        else:\\n            value = secrets.token_urlsafe(32)\\n            write_secret_to_file(secret_key_path, value)\\n            logger.debug(\\\"Saved secret key\\\")\\n\\n        _warn_if_secret_key_is_short(value)\\n        return value if isinstance(value, SecretStr) else SecretStr(value).get_secret_value()\\n\\n    @field_validator(\\\"EXTERNAL_AUTH_PROVIDER\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def normalize_external_auth_provider(cls, value):\\n        \\\"\\\"\\\"Normalize the external provider key once at the config boundary.\\n\\n        Every consumer (JIT provisioning, the API-key floor in the auth service,\\n        SSOUserProfile.sso_provider lookups) reads this value directly, so an\\n        empty/whitespace value must resolve to the same canonical string here.\\n        Otherwise the value written (\\\"external\\\") and the value compared against\\n        (\\\"\\\") would diverge and silently disable a security floor.\\n        \\\"\\\"\\\"\\n        if value is None:\\n            return \\\"external\\\"\\n        normalized = str(value).strip()\\n        return normalized or \\\"external\\\"\\n\\n    @field_validator(\\\"SSO_REDIRECT_URL\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def validate_sso_redirect_url(cls, value):\\n        \\\"\\\"\\\"Allow only same-origin relative URL references.\\\"\\\"\\\"\\n        if value is None:\\n            return None\\n\\n        raw_url = str(value)\\n        url = raw_url.strip()\\n        if not url:\\n            return None\\n        if any(\\n            ord(character) < ASCII_CONTROL_CHARACTER_LIMIT or ord(character) == ASCII_DELETE_CHARACTER\\n            for character in raw_url\\n        ):\\n            msg = \\\"SSO_REDIRECT_URL must not contain control characters.\\\"\\n            raise ValueError(msg)\\n\\n        parsed = urlparse(url)\\n        normalized_separators = url.replace(\\\"\\\\\\\\\\\", \\\"/\\\")\\n        if parsed.scheme or parsed.netloc or normalized_separators.startswith(\\\"//\\\"):\\n            msg = (\\n                \\\"SSO_REDIRECT_URL must be a same-origin relative path; \\\"\\n                \\\"absolute and protocol-relative URLs are not allowed.\\\"\\n            )\\n            raise ValueError(msg)\\n\\n        return url\\n\\n    @field_validator(\\\"EXTERNAL_AUTH_JWKS_URL\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def validate_external_auth_jwks_url(cls, value):\\n        \\\"\\\"\\\"Reject non-HTTPS JWKS URLs to stop a network MITM swapping signing keys.\\n\\n        An ``http://`` JWKS endpoint lets an on-path attacker substitute their own\\n        keys and forge tokens. HTTPS is required; ``http`` is permitted only for\\n        loopback hosts (localhost / 127.0.0.1 / ::1) to keep local development\\n        usable.\\n        \\\"\\\"\\\"\\n        if value is None:\\n            return value\\n        url = str(value).strip()\\n        if not url:\\n            return None\\n\\n        parsed = urlparse(url)\\n        scheme = parsed.scheme.lower()\\n        if scheme == \\\"https\\\":\\n            return url\\n        if scheme == \\\"http\\\" and parsed.hostname in {\\\"localhost\\\", \\\"127.0.0.1\\\", \\\"::1\\\"}:\\n            return url\\n\\n        msg = (\\n            \\\"EXTERNAL_AUTH_JWKS_URL must use https so a network attacker cannot swap the JWKS \\\"\\n            \\\"signing keys and forge tokens. http is allowed only for localhost/127.0.0.1/::1.\\\"\\n        )\\n        raise ValueError(msg)\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def setup_rsa_keys(self):\\n        \\\"\\\"\\\"Generate or load RSA keys when using RS256/RS512 algorithm.\\\"\\\"\\\"\\n        if not self.ALGORITHM.is_asymmetric():\\n            return self\\n\\n        config_dir = self.CONFIG_DIR\\n        private_key_value = self.PRIVATE_KEY.get_secret_value() if self.PRIVATE_KEY else \\\"\\\"\\n\\n        if not config_dir:\\n            # No config dir - generate keys in memory if not provided\\n            if not private_key_value:\\n                logger.debug(\\\"No CONFIG_DIR provided, generating RSA keys in memory\\\")\\n                private_key_pem, public_key_pem = generate_rsa_key_pair()\\n                object.__setattr__(self, \\\"PRIVATE_KEY\\\", SecretStr(private_key_pem))\\n                object.__setattr__(self, \\\"PUBLIC_KEY\\\", public_key_pem)\\n            elif not self.PUBLIC_KEY:\\n                # Derive public key from private key\\n                public_key_pem = derive_public_key_from_private(private_key_value)\\n                object.__setattr__(self, \\\"PUBLIC_KEY\\\", public_key_pem)\\n            return self\\n\\n        private_key_path = Path(config_dir) / \\\"private_key.pem\\\"\\n        public_key_path = Path(config_dir) / \\\"public_key.pem\\\"\\n\\n        if private_key_value:\\n            # Private key provided via env var - save it and derive public key\\n            logger.debug(\\\"RSA private key provided\\\")\\n            write_secret_to_file(private_key_path, private_key_value)\\n\\n            if not self.PUBLIC_KEY:\\n                public_key_pem = derive_public_key_from_private(private_key_value)\\n                object.__setattr__(self, \\\"PUBLIC_KEY\\\", public_key_pem)\\n                write_public_key_to_file(public_key_path, public_key_pem)\\n        # No private key provided - load from file or generate\\n        elif private_key_path.exists():\\n            logger.debug(\\\"Loading RSA keys from files\\\")\\n            private_key_pem = read_secret_from_file(private_key_path)\\n            object.__setattr__(self, \\\"PRIVATE_KEY\\\", SecretStr(private_key_pem))\\n\\n            if public_key_path.exists():\\n                public_key_pem = public_key_path.read_text(encoding=\\\"utf-8\\\")\\n                object.__setattr__(self, \\\"PUBLIC_KEY\\\", public_key_pem)\\n            else:\\n                # Derive public key from private key\\n                public_key_pem = derive_public_key_from_private(private_key_pem)\\n                object.__setattr__(self, \\\"PUBLIC_KEY\\\", public_key_pem)\\n                write_public_key_to_file(public_key_path, public_key_pem)\\n        else:\\n            # Generate new RSA key pair\\n            logger.debug(\\\"Generating new RSA key pair\\\")\\n            private_key_pem, public_key_pem = generate_rsa_key_pair()\\n            write_secret_to_file(private_key_path, private_key_pem)\\n            write_public_key_to_file(public_key_path, public_key_pem)\\n            object.__setattr__(self, \\\"PRIVATE_KEY\\\", SecretStr(private_key_pem))\\n            object.__setattr__(self, \\\"PUBLIC_KEY\\\", public_key_pem)\\n            logger.debug(\\\"RSA key pair generated and saved\\\")\\n\\n        return self\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/settings/base.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"006fe2ae3e5a5d55764ba3dc481c86cd758c2ebd2c59545ae2dd0ac3641cd9d3\",\"content\":\"\\\"\\\"\\\"Composed ``Settings`` class for Langflow.\\n\\nFields live in per-group mixins under :mod:`lfx.services.settings.groups`.\\nThis module wires them together, configures env-var loading, and exposes the\\nYAML helpers and a few model-level utilities (``update_settings``,\\n``voice_mode_available``).\\n\\nGroup order in the inheritance list matters: Pydantic collects fields from the\\nrightmost base first, so cross-group validators see their dependencies in\\n``info.data``. Specifically:\\n\\n- :class:`PathSettings` is rightmost so ``config_dir`` is validated before\\n  ``database_url``.\\n- :class:`ServerSettings` precedes :class:`RuntimeSettings` so ``workers`` is\\n  validated before ``event_delivery``.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nimport contextlib\\nimport json\\nfrom pathlib import Path\\nfrom typing import TYPE_CHECKING, Any\\n\\nimport aiofiles\\nimport orjson\\nimport yaml\\nfrom pydantic_settings import BaseSettings, EnvSettingsSource, PydanticBaseSettingsSource, SettingsConfigDict\\nfrom typing_extensions import override\\n\\nfrom lfx.constants import BASE_COMPONENTS_PATH as BASE_COMPONENTS_PATH  # noqa: PLC0414  # re-export for back-compat\\nfrom lfx.services.settings.groups import (\\n    CacheSettings,\\n    ComponentsSettings,\\n    DatabaseSettings,\\n    McpSettings,\\n    ObservabilitySettings,\\n    PathSettings,\\n    RuntimeSettings,\\n    SecuritySettings,\\n    ServerSettings,\\n    StorageSettings,\\n    TelemetrySettings,\\n    UiSettings,\\n    VariablesSettings,\\n)\\n\\nif TYPE_CHECKING:\\n    from pydantic.fields import FieldInfo\\n\\n\\ndef is_list_of_any(field: FieldInfo) -> bool:\\n    \\\"\\\"\\\"Check if the given field is a list or an optional list of any type.\\n\\n    Args:\\n        field (FieldInfo): The field to be checked.\\n\\n    Returns:\\n        bool: True if the field is a list or a list of any type, False otherwise.\\n    \\\"\\\"\\\"\\n    if field.annotation is None:\\n        return False\\n    try:\\n        union_args = field.annotation.__args__ if hasattr(field.annotation, \\\"__args__\\\") else []\\n\\n        return field.annotation.__origin__ is list or any(\\n            arg.__origin__ is list for arg in union_args if hasattr(arg, \\\"__origin__\\\")\\n        )\\n    except AttributeError:\\n        return False\\n\\n\\nclass CustomSource(EnvSettingsSource):\\n    @override\\n    def prepare_field_value(self, field_name: str, field: FieldInfo, value: Any, value_is_complex: bool) -> Any:  # type: ignore[misc]\\n        # allow comma-separated list parsing\\n\\n        # fieldInfo contains the annotation of the field\\n        if is_list_of_any(field):\\n            if isinstance(value, str):\\n                value = value.split(\\\",\\\")\\n            if isinstance(value, list):\\n                return value\\n\\n        return super().prepare_field_value(field_name, field, value, value_is_complex)\\n\\n\\nclass Settings(\\n    VariablesSettings,\\n    UiSettings,\\n    ComponentsSettings,\\n    SecuritySettings,\\n    ObservabilitySettings,\\n    TelemetrySettings,\\n    StorageSettings,\\n    CacheSettings,\\n    McpSettings,\\n    DatabaseSettings,\\n    RuntimeSettings,\\n    ServerSettings,\\n    PathSettings,\\n    BaseSettings,\\n):\\n    \\\"\\\"\\\"Top-level Langflow settings.\\n\\n    Composed from per-group mixins. See module docstring for the inheritance\\n    order rationale.\\n    \\\"\\\"\\\"\\n\\n    model_config = SettingsConfigDict(validate_assignment=True, extra=\\\"ignore\\\", env_prefix=\\\"LANGFLOW_\\\")\\n\\n    async def update_from_yaml(self, file_path: str, *, dev: bool = False) -> None:\\n        new_settings = await load_settings_from_yaml(file_path)\\n        self.components_path = new_settings.components_path or []\\n        self.dev = dev\\n\\n    def update_settings(self, **kwargs) -> None:\\n        for key, value in kwargs.items():\\n            # value may contain sensitive information, so we don't want to log it\\n            if not hasattr(self, key):\\n                continue\\n            if isinstance(getattr(self, key), list):\\n                # value might be a '[something]' string\\n                value_ = value\\n                with contextlib.suppress(json.decoder.JSONDecodeError):\\n                    value_ = orjson.loads(str(value))\\n                if isinstance(value_, list):\\n                    for item in value_:\\n                        item_ = str(item) if isinstance(item, Path) else item\\n                        if item_ not in getattr(self, key):\\n                            getattr(self, key).append(item_)\\n                else:\\n                    value_ = str(value_) if isinstance(value_, Path) else value_\\n                    if value_ not in getattr(self, key):\\n                        getattr(self, key).append(value_)\\n            else:\\n                setattr(self, key, value)\\n\\n    @property\\n    def voice_mode_available(self) -> bool:\\n        \\\"\\\"\\\"Check whether the optional voice runtime dependencies are installed.\\\"\\\"\\\"\\n        try:\\n            import openai  # noqa: F401\\n            import webrtcvad  # noqa: F401\\n        except ImportError:\\n            return False\\n        else:\\n            return True\\n\\n    @classmethod\\n    @override\\n    def settings_customise_sources(  # type: ignore[misc]\\n        cls,\\n        settings_cls: type[BaseSettings],\\n        init_settings: PydanticBaseSettingsSource,\\n        env_settings: PydanticBaseSettingsSource,\\n        dotenv_settings: PydanticBaseSettingsSource,\\n        file_secret_settings: PydanticBaseSettingsSource,\\n    ) -> tuple[PydanticBaseSettingsSource, ...]:\\n        return (CustomSource(settings_cls),)\\n\\n\\ndef save_settings_to_yaml(settings: Settings, file_path: str) -> None:\\n    with Path(file_path).open(\\\"w\\\", encoding=\\\"utf-8\\\") as f:\\n        settings_dict = settings.model_dump()\\n        yaml.dump(settings_dict, f)\\n\\n\\nasync def load_settings_from_yaml(file_path: str) -> Settings:\\n    from lfx.log.logger import logger\\n\\n    # Check if a string is a valid path or a file name\\n    if \\\"/\\\" not in file_path:\\n        # Get current path\\n        current_path = Path(__file__).resolve().parent\\n        file_path_ = Path(current_path) / file_path\\n    else:\\n        file_path_ = Path(file_path)\\n\\n    async with aiofiles.open(file_path_.name, encoding=\\\"utf-8\\\") as f:\\n        content = await f.read()\\n        settings_dict = yaml.safe_load(content)\\n        settings_dict = {k.upper(): v for k, v in settings_dict.items()}\\n\\n        for key in settings_dict:\\n            if key not in Settings.model_fields:\\n                msg = f\\\"Key {key} not found in settings\\\"\\n                raise KeyError(msg)\\n            await logger.adebug(f\\\"Loading {len(settings_dict[key])} {key} from {file_path}\\\")\\n\\n    return await asyncio.to_thread(Settings, **settings_dict)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/settings/constants.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"2df7bb5bbf04631e2517346bd74baabe2a6d639894f216de145e738abc3404bc\",\"content\":\"from pydantic import SecretStr\\n\\nDEFAULT_SUPERUSER = \\\"langflow\\\"\\nDEFAULT_SUPERUSER_PASSWORD = SecretStr(\\\"\\\")\\n# Only used to detect and rotate credentials created by older releases.\\nLEGACY_DEFAULT_SUPERUSER_PASSWORD = SecretStr(\\\"langflow\\\")\\n\\nMINIMUM_SECRET_KEY_LENGTH = 32\\nSHORT_SECRET_KEY_WARNING = (\\n    \\\"LANGFLOW_SECRET_KEY is shorter than 32 characters. Short secrets are not recommended for production. \\\"  # noqa: S105\\n    \\\"Keep this key unchanged during an upgrade so Langflow can read credentials encrypted before 1.10.1, \\\"\\n    \\\"then use a planned credential rotation to replace it with a randomly generated key of at least 32 characters.\\\"\\n)\\n\\nVARIABLES_TO_GET_FROM_ENVIRONMENT = [\\n    \\\"COMPOSIO_API_KEY\\\",\\n    \\\"OPENAI_API_KEY\\\",\\n    \\\"ANTHROPIC_API_KEY\\\",\\n    \\\"GOOGLE_API_KEY\\\",\\n    \\\"AZURE_AI_FOUNDRY_API_KEY\\\",\\n    \\\"AZURE_AI_FOUNDRY_ENDPOINT\\\",\\n    \\\"AZURE_AI_FOUNDRY_API_VERSION\\\",\\n    \\\"AZURE_OPENAI_API_KEY\\\",\\n    \\\"AZURE_OPENAI_API_VERSION\\\",\\n    \\\"AZURE_OPENAI_API_INSTANCE_NAME\\\",\\n    \\\"AZURE_OPENAI_API_DEPLOYMENT_NAME\\\",\\n    \\\"AZURE_OPENAI_API_EMBEDDINGS_DEPLOYMENT_NAME\\\",\\n    \\\"ASTRA_DB_APPLICATION_TOKEN\\\",\\n    \\\"ASTRA_DB_API_ENDPOINT\\\",\\n    \\\"COHERE_API_KEY\\\",\\n    \\\"GROQ_API_KEY\\\",\\n    \\\"HUGGINGFACEHUB_API_TOKEN\\\",\\n    \\\"PINECONE_API_KEY\\\",\\n    \\\"SAMBANOVA_API_KEY\\\",\\n    \\\"SEARCHAPI_API_KEY\\\",\\n    \\\"SERPAPI_API_KEY\\\",\\n    \\\"UPSTASH_VECTOR_REST_URL\\\",\\n    \\\"UPSTASH_VECTOR_REST_TOKEN\\\",\\n    \\\"VECTARA_CUSTOMER_ID\\\",\\n    \\\"VECTARA_CORPUS_ID\\\",\\n    \\\"VECTARA_API_KEY\\\",\\n    \\\"AWS_ACCESS_KEY_ID\\\",\\n    \\\"AWS_SECRET_ACCESS_KEY\\\",\\n    \\\"NOVITA_API_KEY\\\",\\n    \\\"TAVILY_API_KEY\\\",\\n    \\\"COMETAPI_KEY\\\",\\n    \\\"EMPIRIOLABS_API_KEY\\\",\\n    # IBM WatsonX variables\\n    \\\"WATSONX_APIKEY\\\",\\n    \\\"WATSONX_PROJECT_ID\\\",\\n    \\\"WATSONX_URL\\\",\\n    # OpenRouter variables\\n    \\\"OPENROUTER_API_KEY\\\",\\n    \\\"OPENROUTER_SITE_URL\\\",\\n    \\\"OPENROUTER_APP_NAME\\\",\\n]\\n\\n# Agentic experience specific variables\\nAGENTIC_VARIABLES = [\\n    \\\"FLOW_ID\\\",\\n    \\\"COMPONENT_ID\\\",\\n    \\\"FIELD_NAME\\\",\\n    \\\"ASTRA_TOKEN\\\",\\n]\\n\\nDEFAULT_AGENTIC_VARIABLE_VALUE = \\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/settings/factory.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"35ecd9e9313fc4ff79e41f65f6923a38d372a3296b1cf7d464df1aaef2d54578\",\"content\":\"from typing_extensions import override\\n\\nfrom lfx.services.factory import ServiceFactory\\nfrom lfx.services.settings.service import SettingsService\\n\\n\\nclass SettingsServiceFactory(ServiceFactory):\\n    _instance = None\\n\\n    def __new__(cls):\\n        if cls._instance is None:\\n            cls._instance = super().__new__(cls)\\n        return cls._instance\\n\\n    def __init__(self) -> None:\\n        super().__init__()\\n        self.service_class = SettingsService\\n\\n    @override\\n    def create(self):\\n        # Here you would have logic to create and configure a SettingsService\\n\\n        return SettingsService.initialize()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/settings/feature_flags.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"49b7faf0032e5892a8c59dc3295165cbec7ad349ef1f85b3394856f60480bc98\",\"content\":\"from pydantic_settings import BaseSettings\\n\\n\\nclass FeatureFlags(BaseSettings):\\n    wxo_deployments: bool = False\\n    \\\"\\\"\\\"\\n    Enable Watsonx Orchestrate deployments.\\n    \\\"\\\"\\\"\\n    mvp_components: bool = False\\n\\n    class Config:\\n        env_prefix = \\\"LANGFLOW_FEATURE_\\\"\\n\\n\\nFEATURE_FLAGS = FeatureFlags()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/settings/groups/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7b4d8fa977123460053201a0f9e3d041efeb4a3a11ff195c0f2b129b7383386a\",\"content\":\"\\\"\\\"\\\"Logical groupings of Langflow settings.\\n\\nEach module defines a ``BaseModel`` mixin that owns a cohesive subset of fields\\nplus their intra-group validators. They are composed into the final\\n``Settings`` class in :mod:`lfx.services.settings.base`.\\n\\nMixins inherit from ``BaseModel`` (not ``BaseSettings``) and are not intended\\nto be instantiated directly.\\n\\\"\\\"\\\"\\n\\nfrom lfx.services.settings.groups.cache import CacheSettings\\nfrom lfx.services.settings.groups.components import ComponentsSettings\\nfrom lfx.services.settings.groups.database import DatabaseSettings\\nfrom lfx.services.settings.groups.mcp import McpSettings\\nfrom lfx.services.settings.groups.observability import ObservabilitySettings\\nfrom lfx.services.settings.groups.paths import PathSettings\\nfrom lfx.services.settings.groups.runtime import RuntimeSettings\\nfrom lfx.services.settings.groups.security import SecuritySettings\\nfrom lfx.services.settings.groups.server import ServerSettings\\nfrom lfx.services.settings.groups.storage import StorageSettings\\nfrom lfx.services.settings.groups.telemetry import TelemetrySettings\\nfrom lfx.services.settings.groups.ui import UiSettings\\nfrom lfx.services.settings.groups.variables import VariablesSettings\\n\\n__all__ = [\\n    \\\"CacheSettings\\\",\\n    \\\"ComponentsSettings\\\",\\n    \\\"DatabaseSettings\\\",\\n    \\\"McpSettings\\\",\\n    \\\"ObservabilitySettings\\\",\\n    \\\"PathSettings\\\",\\n    \\\"RuntimeSettings\\\",\\n    \\\"SecuritySettings\\\",\\n    \\\"ServerSettings\\\",\\n    \\\"StorageSettings\\\",\\n    \\\"TelemetrySettings\\\",\\n    \\\"UiSettings\\\",\\n    \\\"VariablesSettings\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/settings/groups/cache.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a92e27a576c6f59a2e625ba785d116c3346f948a264fa3eed9ef7c80f5c86b21\",\"content\":\"from pathlib import Path\\nfrom typing import Literal\\n\\nfrom pydantic import BaseModel, field_validator\\n\\n\\nclass CacheSettings(BaseModel):\\n    \\\"\\\"\\\"In-memory and Redis cache settings.\\\"\\\"\\\"\\n\\n    cache_type: Literal[\\\"async\\\", \\\"redis\\\", \\\"memory\\\"] = \\\"async\\\"\\n    \\\"\\\"\\\"The cache backend: 'async' (default in-memory), 'memory' (sync in-memory), or 'redis'.\\\"\\\"\\\"\\n    cache_expire: int = 3600\\n    \\\"\\\"\\\"The cache expire in seconds.\\\"\\\"\\\"\\n    cache_dir: str | None = None\\n    \\\"\\\"\\\"Directory used by FlowEventsService for cross-worker event storage. Defaults to a temp dir if not set.\\\"\\\"\\\"\\n    langchain_cache: str = \\\"InMemoryCache\\\"\\n\\n    # Redis\\n    redis_host: str = \\\"localhost\\\"\\n    redis_port: int = 6379\\n    redis_db: int = 0\\n    redis_url: str | None = None\\n    redis_cache_expire: int = 3600\\n\\n    @field_validator(\\\"cache_dir\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def validate_cache_dir(cls, value):\\n        \\\"\\\"\\\"Validate and normalize cache_dir path.\\n\\n        If not set, returns None and the factory will fall back to config_dir.\\n        If set, resolves to an absolute path and creates the directory if needed.\\n        \\\"\\\"\\\"\\n        if not value:\\n            return None\\n\\n        if isinstance(value, str):\\n            value = Path(value)\\n        # Resolve to absolute path to handle relative paths correctly\\n        value = value.resolve()\\n        if not value.exists():\\n            value.mkdir(parents=True, exist_ok=True)\\n\\n        return str(value)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/settings/groups/components.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a9bd00472902a3847828e12ac22ac1fbe5b22c09ba2438e77734670166908bd6\",\"content\":\"import os\\nfrom pathlib import Path\\n\\nfrom pydantic import BaseModel, field_validator, model_validator\\n\\nfrom lfx.constants import BASE_COMPONENTS_PATH\\nfrom lfx.log.logger import logger\\n\\n\\nclass ComponentsSettings(BaseModel):\\n    \\\"\\\"\\\"Component discovery, indexing, and startup-load behavior.\\\"\\\"\\\"\\n\\n    components_path: list[str] = []\\n    \\\"\\\"\\\"List of paths to custom components.\\n\\n    Security: This setting defines an allow-list of custom components\\n    permitted to execute, even when LANGFLOW_ALLOW_CUSTOM_COMPONENTS is False.\\n    \\\"\\\"\\\"\\n    components_index_path: str | None = None\\n    \\\"\\\"\\\"Path or URL to a prebuilt component index JSON file.\\n\\n    If None, uses the built-in index at lfx/_assets/component_index.json.\\n    Set to a file path (e.g., '/path/to/index.json') or URL (e.g., 'https://example.com/index.json')\\n    to use a custom index.\\n    \\\"\\\"\\\"\\n\\n    load_flows_path: str | None = None\\n    load_flows_overwrite_on_name_match: bool = False\\n    \\\"\\\"\\\"When a flow loaded from ``load_flows_path`` shares a name with an existing DB row but has\\n    a different id, overwrite the existing row's content from the file.\\n\\n    Default ``False`` preserves user edits made in the UI on restart: name-matched rows are\\n    skipped with a warning instead of being silently overwritten when file UUIDs regenerate.\\n    (Pre-1.10.0 this case raised ``IntegrityError`` and crashed startup; the loader now boots\\n    successfully either way.) Set ``True`` to opt into \\\"prepackaged flows are the source of\\n    truth on restart\\\" semantics, typically for CI/CD pipelines.\\n    \\\"\\\"\\\"\\n    load_flows_preserve_variable_bindings: bool = True\\n    \\\"\\\"\\\"Preserve global-variable bindings configured in the UI when reloading an existing flow.\\n\\n    The flow file remains authoritative for the rest of the flow structure and for bindings it\\n    explicitly defines. Set this to ``False`` to restore blind ``data`` replacement on restart.\\n    \\\"\\\"\\\"\\n    bundle_urls: list[str] = []\\n\\n    lazy_load_components: bool = False\\n    \\\"\\\"\\\"If set to True, Langflow will only partially load components at startup and fully load them on demand.\\n    This significantly reduces startup time but may cause a slight delay when a component is first used.\\\"\\\"\\\"\\n\\n    # Starter Projects\\n    create_starter_projects: bool = True\\n    \\\"\\\"\\\"If set to True, Langflow will create starter projects. If False, skips all starter project setup.\\n    Note that this doesn't check if the starter projects are already loaded in the db;\\n    this is intended to be used to skip all startup project logic.\\\"\\\"\\\"\\n    update_starter_projects: bool = True\\n    \\\"\\\"\\\"If set to True, Langflow will update starter projects.\\\"\\\"\\\"\\n\\n    # Extension reload (Mode A only)\\n    enable_extension_reload: bool = False\\n    \\\"\\\"\\\"If True, registers ``POST /api/v1/extensions/{id}/bundles/{name}/reload``\\n    so authenticated users can hot-swap a Bundle's components in-process.\\n\\n    This is a Mode A (local-dev / pip-installed) facility only.  In Mode B/C\\n    (Docker image with baked-in bundles) Bundle changes require an image\\n    rebuild and the in-process reload route would mask the real deploy\\n    pipeline.  Defaults to ``False`` so self-hosted / production deployments\\n    do not expose runtime imports through an HTTP endpoint without an\\n    explicit opt-in.  Set ``LANGFLOW_ENABLE_EXTENSION_RELOAD=true`` in your\\n    local dev environment to turn it on.\\\"\\\"\\\"\\n\\n    @field_validator(\\\"components_path\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def set_components_path(cls, value):\\n        \\\"\\\"\\\"Processes and updates the components path list, incorporating environment variable overrides.\\n\\n        If the `LANGFLOW_COMPONENTS_PATH` environment variable is set and points to an existing path, it is\\n        appended to the provided list if not already present. If the input list is empty or missing, it is\\n        set to an empty list.\\n        \\\"\\\"\\\"\\n        env_value = os.getenv(\\\"LANGFLOW_COMPONENTS_PATH\\\")\\n        if env_value:\\n            logger.debug(\\\"Adding LANGFLOW_COMPONENTS_PATH to components_path\\\")\\n            # Split on os.pathsep so multi-entry env vars\\n            # (\\\"/path/A:/path/B\\\" on POSIX, \\\"C:\\\\\\\\a;D:\\\\\\\\b\\\" on Windows) are\\n            # parsed as multiple components paths instead of one literal\\n            # non-existent path. Empty segments (e.g. trailing pathsep) are\\n            # ignored.\\n            for raw_entry in env_value.split(os.pathsep):\\n                entry = raw_entry.strip()\\n                if not entry:\\n                    continue\\n                if not Path(entry).exists():\\n                    # Surface at warning so a typo in LANGFLOW_COMPONENTS_PATH\\n                    # is visible in default log levels rather than silently\\n                    # producing zero components and zero diagnostics. The\\n                    # extension loader emits a typed ``inline-path-missing``\\n                    # warning at the same layer for events-pipeline consumers.\\n                    logger.warning(f\\\"Skipping non-existent components path: {entry}\\\")\\n                    continue\\n                if entry not in value:\\n                    value.append(entry)\\n                    logger.debug(f\\\"Appending {entry} to components_path\\\")\\n\\n        if not value:\\n            value = [BASE_COMPONENTS_PATH]\\n        elif isinstance(value, Path):\\n            value = [str(value)]\\n        elif isinstance(value, list):\\n            value = [str(p) if isinstance(p, Path) else p for p in value]\\n        return value\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def _enforce_components_paths_override(self):\\n        \\\"\\\"\\\"Strip env-var-provided component paths when their bypass is disabled.\\n\\n        When ``allow_custom_components`` is False the server only trusts components\\n        matching built-in templates. By default ``LANGFLOW_COMPONENTS_PATH`` and\\n        ``LANGFLOW_COMPONENTS_INDEX_PATH`` still contribute to that trust set (an\\n        admin-curated allow-list). Setting ``allow_components_paths_override=False``\\n        disables that bypass: here we remove the env-contributed entries so nothing\\n        downstream loads or trusts them.\\n        \\\"\\\"\\\"\\n        if self.allow_custom_components or self.allow_components_paths_override:\\n            return self\\n\\n        env_components_path = os.getenv(\\\"LANGFLOW_COMPONENTS_PATH\\\")\\n        if env_components_path:\\n            # The env var may be a comma-separated list; CustomSource splits it\\n            # before the field validator runs, so self.components_path contains\\n            # individual entries rather than the raw comma-joined string.\\n            # In-place removal avoids re-triggering ``set_components_path``, which\\n            # would re-read LANGFLOW_COMPONENTS_PATH and append the paths again.\\n            env_paths = [p.strip() for p in env_components_path.split(\\\",\\\") if p.strip()]\\n            stripped_any = False\\n            for env_path in env_paths:\\n                while env_path in self.components_path:\\n                    self.components_path.remove(env_path)\\n                    stripped_any = True\\n            if stripped_any:\\n                logger.warning(\\n                    \\\"Ignoring LANGFLOW_COMPONENTS_PATH=%s: \\\"\\n                    \\\"LANGFLOW_ALLOW_CUSTOM_COMPONENTS=False and \\\"\\n                    \\\"LANGFLOW_ALLOW_COMPONENTS_PATHS_OVERRIDE=False.\\\",\\n                    env_components_path,\\n                )\\n\\n        # Only strip the index path when it came from the env var, mirroring the\\n        # components_path handling above. A value set via config/YAML is not part of\\n        # the env-var bypass this flag governs, so leave it untouched.\\n        env_components_index_path = os.getenv(\\\"LANGFLOW_COMPONENTS_INDEX_PATH\\\")\\n        if env_components_index_path and self.components_index_path == env_components_index_path:\\n            logger.warning(\\n                \\\"Ignoring LANGFLOW_COMPONENTS_INDEX_PATH=%s: \\\"\\n                \\\"LANGFLOW_ALLOW_CUSTOM_COMPONENTS=False and \\\"\\n                \\\"LANGFLOW_ALLOW_COMPONENTS_PATHS_OVERRIDE=False.\\\",\\n                self.components_index_path,\\n            )\\n            self.components_index_path = None\\n\\n        return self\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/settings/groups/database.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a64309616cde6635933e42112ef073e427f49bdb018529d1975d5d7e3c8afe0d\",\"content\":\"import os\\nfrom pathlib import Path\\nfrom shutil import copy2\\n\\nfrom pydantic import BaseModel, field_validator\\n\\nfrom lfx.log.logger import logger\\nfrom lfx.utils.util_strings import is_valid_database_url, sanitize_database_url\\n\\n\\nclass DatabaseSettings(BaseModel):\\n    \\\"\\\"\\\"Database connection, pooling, and migration settings.\\n\\n    Note: ``database_url`` is validated at the :class:`Settings` level because\\n    it reads ``config_dir`` from :class:`PathSettings`.\\n    \\\"\\\"\\\"\\n\\n    save_db_in_config_dir: bool = False\\n    \\\"\\\"\\\"Define if langflow database should be saved in LANGFLOW_CONFIG_DIR or in the langflow directory\\n    (i.e. in the package directory).\\\"\\\"\\\"\\n\\n    database_url: str | None = None\\n    \\\"\\\"\\\"Database URL for Langflow. If not provided, Langflow will use a SQLite database.\\n    The driver shall be an async one like `sqlite+aiosqlite` (`sqlite` and `postgresql`\\n    will be automatically converted to the async drivers `sqlite+aiosqlite` and\\n    `postgresql+psycopg` respectively).\\\"\\\"\\\"\\n\\n    database_connection_retry: bool = False\\n    \\\"\\\"\\\"If True, Langflow will retry to connect to the database if it fails.\\\"\\\"\\\"\\n\\n    pool_size: int = 20\\n    \\\"\\\"\\\"The number of connections to keep open in the connection pool.\\n    For high load scenarios, this should be increased based on expected concurrent users.\\\"\\\"\\\"\\n\\n    max_overflow: int = 30\\n    \\\"\\\"\\\"The number of connections to allow that can be opened beyond the pool size.\\n    Should be 2x the pool_size for optimal performance under load.\\\"\\\"\\\"\\n\\n    db_connect_timeout: int = 30\\n    \\\"\\\"\\\"The number of seconds to wait before giving up on a lock to released or establishing a connection to the\\n    database.\\\"\\\"\\\"\\n\\n    migration_lock_namespace: str | None = None\\n    \\\"\\\"\\\"Optional namespace identifier for PostgreSQL advisory lock during migrations.\\n    If not provided, a hash of the database URL will be used. Useful when multiple Langflow\\n    instances share the same database and need coordinated migration locking.\\\"\\\"\\\"\\n\\n    sqlite_pragmas: dict | None = {\\\"synchronous\\\": \\\"NORMAL\\\", \\\"journal_mode\\\": \\\"WAL\\\", \\\"busy_timeout\\\": 30000}\\n    \\\"\\\"\\\"SQLite pragmas to use when connecting to the database.\\\"\\\"\\\"\\n\\n    db_driver_connection_settings: dict | None = None\\n    \\\"\\\"\\\"Database driver connection settings.\\\"\\\"\\\"\\n\\n    db_connection_settings: dict | None = {\\n        \\\"pool_size\\\": 20,\\n        \\\"max_overflow\\\": 30,\\n        \\\"pool_timeout\\\": 30,\\n        \\\"pool_pre_ping\\\": True,\\n        \\\"pool_recycle\\\": 1800,\\n        \\\"echo\\\": False,\\n    }\\n    \\\"\\\"\\\"Database connection settings optimized for high load scenarios.\\n    Note: These settings are most effective with PostgreSQL. For SQLite:\\n    - Reduce pool_size and max_overflow if experiencing lock contention\\n    - SQLite has limited concurrent write capability even with WAL mode\\n    - Best for read-heavy or moderate write workloads\\n\\n    Settings:\\n    - pool_size: Number of connections to maintain (increase for higher concurrency)\\n    - max_overflow: Additional connections allowed beyond pool_size\\n    - pool_timeout: Seconds to wait for an available connection\\n    - pool_pre_ping: Validates connections before use to prevent stale connections\\n    - pool_recycle: Seconds before connections are recycled (prevents timeouts)\\n    - echo: Enable SQL query logging (development only)\\n    \\\"\\\"\\\"\\n\\n    use_noop_database: bool = False\\n    \\\"\\\"\\\"If True, disables all database operations and uses a no-op session.\\n    Controlled by LANGFLOW_USE_NOOP_DATABASE env variable.\\\"\\\"\\\"\\n\\n    @field_validator(\\\"use_noop_database\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def set_use_noop_database(cls, value):\\n        if value:\\n            logger.info(\\\"Running with NOOP database session. All DB operations are disabled.\\\")\\n        return value\\n\\n    @field_validator(\\\"database_url\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def set_database_url(cls, value, info):\\n        if value and not is_valid_database_url(value):\\n            sanitized = sanitize_database_url(value)\\n            msg = f\\\"Invalid database_url provided: '{sanitized}'\\\"\\n            raise ValueError(msg)\\n\\n        if langflow_database_url := os.getenv(\\\"LANGFLOW_DATABASE_URL\\\"):\\n            value = langflow_database_url\\n            logger.debug(\\\"Using LANGFLOW_DATABASE_URL env variable\\\")\\n        else:\\n            if not info.data.get(\\\"config_dir\\\"):\\n                msg = \\\"config_dir not set, please set it or provide a database_url\\\"\\n                raise ValueError(msg)\\n\\n            from lfx.utils.version import get_version_info\\n            from lfx.utils.version import is_pre_release as langflow_is_pre_release\\n\\n            version = get_version_info()[\\\"version\\\"]\\n            is_pre_release = langflow_is_pre_release(version)\\n\\n            if info.data[\\\"save_db_in_config_dir\\\"]:\\n                database_dir = info.data[\\\"config_dir\\\"]\\n            else:\\n                try:\\n                    import langflow\\n\\n                    database_dir = Path(langflow.__file__).parent.resolve()\\n                except ImportError:\\n                    database_dir = Path(__file__).parent.parent.parent.parent.resolve()\\n\\n            pre_db_file_name = \\\"langflow-pre.db\\\"\\n            db_file_name = \\\"langflow.db\\\"\\n            new_pre_path = f\\\"{database_dir}/{pre_db_file_name}\\\"\\n            new_path = f\\\"{database_dir}/{db_file_name}\\\"\\n            final_path = None\\n            if is_pre_release:\\n                if Path(new_pre_path).exists():\\n                    final_path = new_pre_path\\n                elif Path(new_path).exists() and info.data[\\\"save_db_in_config_dir\\\"]:\\n                    logger.debug(\\\"Copying existing database to new location\\\")\\n                    copy2(new_path, new_pre_path)\\n                    logger.debug(f\\\"Copied existing database to {new_pre_path}\\\")\\n                elif Path(f\\\"./{db_file_name}\\\").exists() and info.data[\\\"save_db_in_config_dir\\\"]:\\n                    logger.debug(\\\"Copying existing database to new location\\\")\\n                    copy2(f\\\"./{db_file_name}\\\", new_pre_path)\\n                    logger.debug(f\\\"Copied existing database to {new_pre_path}\\\")\\n                else:\\n                    logger.debug(f\\\"Creating new database at {new_pre_path}\\\")\\n                    final_path = new_pre_path\\n            elif Path(new_path).exists():\\n                final_path = new_path\\n            elif Path(f\\\"./{db_file_name}\\\").exists():\\n                try:\\n                    logger.debug(\\\"Copying existing database to new location\\\")\\n                    copy2(f\\\"./{db_file_name}\\\", new_path)\\n                    logger.debug(f\\\"Copied existing database to {new_path}\\\")\\n                except OSError:\\n                    logger.exception(\\\"Failed to copy database, using default path\\\")\\n                    new_path = f\\\"./{db_file_name}\\\"\\n            else:\\n                final_path = new_path\\n\\n            if final_path is None:\\n                final_path = new_pre_path if is_pre_release else new_path\\n\\n            value = f\\\"sqlite:///{final_path}\\\"\\n\\n        return value\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/settings/groups/mcp.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"2ce3f527db6d409cbd608c4c8dc6393a3210d7fb6d231faffd27ffc7a9e261e1\",\"content\":\"import re\\n\\nfrom pydantic import BaseModel, field_validator\\n\\nfrom lfx.log.logger import logger\\n\\n\\nclass McpSettings(BaseModel):\\n    \\\"\\\"\\\"MCP server, session manager, and composer settings, plus the A2A protocol toggle.\\\"\\\"\\\"\\n\\n    mcp_base_url: str = \\\"\\\"\\n    \\\"\\\"\\\"External base URL (scheme + host + optional path) used to build MCP server URLs.\\n    Set it to the externally reachable origin (e.g. 'https://langflow.example.com'); this is\\n    required in multi-pod deployments where the pod binds 0.0.0.0 but must advertise a routable\\n    gateway/service address, since the bind host cannot also serve as the advertised host.\\n    When empty (default): the backend builds URLs from host/port (0.0.0.0 -> localhost) and the\\n    frontend falls back to the browser's window.location.origin.\\\"\\\"\\\"\\n\\n    mcp_server_timeout: int = 60\\n    \\\"\\\"\\\"The number of seconds to wait before giving up on establishing a connection to the MCP server.\\n\\n    Bounds the outer ``connect_to_server`` call for every transport and the wait for a new\\n    stdio or Streamable HTTP session to become ready. It does not change the per-attempt 2 s\\n    cap on the Streamable HTTP ``initialize`` handshake, so a slow-to-start server is only\\n    tolerated over stdio. The default is sized for a cold stdio server inside a packaged\\n    interpreter (Langflow Desktop's bundled ``langflow.agentic.mcp`` takes 18-25 s to import\\n    on first launch), not a warm developer venv.\\n\\n    It also acts as a floor for ``mcp_tool_execution_timeout``: tool calls wait for the larger\\n    of the two, so lowering the tool timeout below this value has no effect.\\n    Env var: LANGFLOW_MCP_SERVER_TIMEOUT.\\\"\\\"\\\"\\n\\n    mcp_tool_execution_timeout: float = 180.0\\n    \\\"\\\"\\\"Maximum seconds to wait for MCP tool execution before timing out.\\n    Default is 180 seconds (3 minutes) to support long-running operations.\\n    Supports decimal values for sub-second timeouts (e.g., 0.5 for 500ms).\\n    Individual components can override this with their own timeout setting.\\n    Must be a positive number greater than 0.\\\"\\\"\\\"\\n\\n    @field_validator(\\\"mcp_tool_execution_timeout\\\")\\n    @classmethod\\n    def validate_mcp_tool_execution_timeout(cls, v: float) -> float:\\n        \\\"\\\"\\\"Validate that mcp_tool_execution_timeout is positive.\\\"\\\"\\\"\\n        if v <= 0:\\n            msg = \\\"mcp_tool_execution_timeout must be greater than 0\\\"\\n            raise ValueError(msg)\\n        return v\\n\\n    # ---------------------------------------------------------------------\\n    # MCP Session-manager tuning\\n    # ---------------------------------------------------------------------\\n    mcp_max_sessions_per_server: int = 10\\n    \\\"\\\"\\\"Maximum number of MCP sessions to keep per unique server (command/url).\\n    Mirrors the default constant MAX_SESSIONS_PER_SERVER in util.py. Adjust to\\n    control resource usage or concurrency per server.\\\"\\\"\\\"\\n\\n    mcp_session_idle_timeout: int = 400  # seconds (~6.7 minutes)\\n    \\\"\\\"\\\"How long (in seconds) an MCP session can stay idle before the background\\n    cleanup task disposes of it.\\\"\\\"\\\"\\n\\n    mcp_session_cleanup_interval: int = 120  # seconds\\n    \\\"\\\"\\\"Frequency (in seconds) at which the background cleanup task wakes up to\\n    reap idle sessions.\\\"\\\"\\\"\\n\\n    # MCP Server\\n    mcp_server_enabled: bool = True\\n    \\\"\\\"\\\"If set to False, Langflow will not enable the MCP server.\\\"\\\"\\\"\\n\\n    mcp_sse_enabled: bool = True\\n    \\\"\\\"\\\"If set to False, the legacy SSE transport and its message endpoint answer 404.\\n\\n    ``mcp_server_enabled`` mounts both transports and there is no way to serve only the\\n    modern one. SSE holds a stream open for the life of the connection and keeps a\\n    never-evicted ``SseServerTransport`` per project, which is a poor fit for a shared\\n    multi-tenant serving tier. Default True preserves compatibility for clients that\\n    still speak SSE; Streamable HTTP is unaffected either way.\\n    Env var: LANGFLOW_MCP_SSE_ENABLED.\\\"\\\"\\\"\\n    mcp_server_enable_progress_notifications: bool = False\\n    \\\"\\\"\\\"If set to False, Langflow will not send progress notifications in the MCP server.\\\"\\\"\\\"\\n\\n    # Add projects to MCP servers automatically on creation\\n    add_projects_to_mcp_servers: bool = True\\n    \\\"\\\"\\\"If set to True, newly created projects will be added to the user's MCP servers config automatically.\\\"\\\"\\\"\\n\\n    skip_mcp_auto_init: bool = False\\n    \\\"\\\"\\\"If set to True, Langflow skips the background MCP server auto-initialization on startup.\\n\\n    The startup task reconciles every project's MCP server config, which for apikey/none\\n    projects can spawn ``uvx mcp-proxy`` and open an outbound connection. On an offline or\\n    firewalled host (or CI) that connect has no bounded timeout and blocks until the OS\\n    connect timeout (~127s). Enable this in tests or air-gapped deployments to keep startup\\n    local and deterministic.\\\"\\\"\\\"\\n\\n    # MCP Composer\\n    mcp_composer_enabled: bool = True\\n    \\\"\\\"\\\"If set to False, Langflow will not start the MCP Composer service.\\\"\\\"\\\"\\n    mcp_composer_version: str = \\\"==0.1.0.8.10\\\"\\n    \\\"\\\"\\\"Version constraint for mcp-composer when using uvx. Uses PEP 440 syntax.\\\"\\\"\\\"\\n\\n    mcp_sdk_constraint: str = \\\"mcp~=1.28\\\"\\n    \\\"\\\"\\\"Requirement injected as ``uvx --with`` when Langflow launches an MCP server through uvx.\\n\\n    ``uvx`` resolves each server into its own ephemeral environment, so Langflow's own\\n    ``mcp`` pin does not apply there. ``mcp-proxy`` and ``mcp-composer`` still declare an\\n    unbounded ``mcp>=1.x``, and the 2.0 SDK removed ``request_ctx`` and renamed ``McpError``,\\n    so an unconstrained resolve installs a release those packages cannot import. Keep the\\n    specifier free of ``<``/``>``, which the stdio command policy rejects as shell\\n    metacharacters. The exact configured specifier is exempt from\\n    ``mcp_server_allowed_packages``, so allowlisted deployments keep working without\\n    adding ``mcp``. Set to an empty string to disable the injection once upstream\\n    supports the 2.x SDK. Env var: LANGFLOW_MCP_SDK_CONSTRAINT.\\\"\\\"\\\"\\n\\n    # A2A protocol\\n    a2a_enabled: bool = False\\n    \\\"\\\"\\\"If set to True, Langflow serves spec-valid A2A agent cards at a per-flow\\n    discovery endpoint for agent-typed, a2a_enabled flows. Default off (opt-in).\\n    Env var: LANGFLOW_A2A_ENABLED.\\\"\\\"\\\"\\n    a2a_allow_private_webhooks: bool = False\\n    \\\"\\\"\\\"If True, A2A push-notification webhooks may target private/loopback/link-local\\n    addresses. Default False blocks them (SSRF protection on the public endpoint); enable\\n    only in a trusted network where agents notify internal services.\\n    Env var: LANGFLOW_A2A_ALLOW_PRIVATE_WEBHOOKS.\\\"\\\"\\\"\\n\\n    # MCP Server management\\n    mcp_servers_locked: bool = False\\n    \\\"\\\"\\\"If set to True, users cannot add or modify MCP servers via the UI/API.\\n\\n    This control is independent from ``embedded_mode`` and must be enabled\\n    explicitly when you want to lock MCP server management.\\n    \\\"\\\"\\\"\\n\\n    mcp_server_allowed_packages: str | None = None\\n    \\\"\\\"\\\"Comma-separated package allowlist for MCP ``npx``/``uvx`` stdio servers.\\n\\n    When set, package runners may download and execute only these exact package names.\\n    Version specifiers are allowed but do not change the package identity. Leave unset to\\n    preserve the legacy single-tenant behavior. Multi-tenant deployments should set this\\n    to the packages installed by their operator; an empty value blocks all package runners.\\n    \\\"\\\"\\\"\\n\\n    mcp_server_env_allowlist: str | None = None\\n    \\\"\\\"\\\"Comma-separated allowlist of environment-variable names an MCP stdio config may set.\\n\\n    Unset (the default) applies only the built-in policy, which denies whole runtime families\\n    -- loader (``LD_*``/``DYLD_*``), OpenSSL (``OPENSSL_*``), interpreter option and module\\n    paths (``PYTHON*``, ``NODE_*``, ``PERL*``, ``JAVA_*``, ...), package-runner source\\n    overrides (``UV_*``, ``NPM_CONFIG_*``, ``PIP_*``), git helper commands (``GIT_*``), and\\n    TLS trust anchors -- while permitting the arbitrary vendor-named credentials that real MCP\\n    servers require (``GITHUB_TOKEN``, ``BRAVE_API_KEY``, ...).\\n\\n    Setting this switches to a strict allowlist: exactly these names are accepted and every\\n    other name is rejected. That is the durable posture for multi-tenant deployments, since no\\n    blocklist can enumerate every code-loading variable across libc, OpenSSL, git, and every\\n    interpreter. An explicitly empty value (``\\\"\\\"``) is the strictest setting -- it rejects all\\n    tenant-supplied environment variables -- and is distinct from leaving this unset.\\n\\n    Because the list is authoritative, naming a loader or interpreter variable here\\n    re-enables that code-execution vector; list only application credentials and configuration\\n    your servers actually need. Langflow always injects ``PATH`` itself, so it need not be\\n    listed. Env var: LANGFLOW_MCP_SERVER_ENV_ALLOWLIST.\\n    \\\"\\\"\\\"\\n\\n    mcp_server_interpreter_hardening: bool = False\\n    \\\"\\\"\\\"If set to True, blocks tenant-controlled Python, Node.js, and shell MCP entrypoints.\\n\\n    The command allowlist alone cannot make ``python <uploaded-file>`` or\\n    ``node <uploaded-file>`` or ``bash <uploaded-file>`` safe. Hardened mode rejects direct\\n    interpreter/script invocations while retaining validated package wrappers and the\\n    authenticated internal ``python -m langflow.agentic.mcp`` server. Leave disabled to\\n    preserve legacy single-tenant MCP configurations.\\n    \\\"\\\"\\\"\\n\\n    @field_validator(\\\"mcp_composer_version\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def validate_mcp_composer_version(cls, value):\\n        \\\"\\\"\\\"Ensure the version string has a version specifier prefix.\\n\\n        If a bare version like '0.1.0.7' is provided, prepend '~=' to allow patch updates.\\n        Supports PEP 440 specifiers: ==, !=, <=, >=, <, >, ~=, ===\\n        \\\"\\\"\\\"\\n        if not value:\\n            return \\\"==0.1.0.8.10\\\"  # Default\\n\\n        specifiers = [\\\"===\\\", \\\"==\\\", \\\"!=\\\", \\\"<=\\\", \\\">=\\\", \\\"~=\\\", \\\"<\\\", \\\">\\\"]\\n        if any(value.startswith(spec) for spec in specifiers):\\n            return value\\n\\n        if re.match(r\\\"^\\\\d+(\\\\.\\\\d+)*\\\", value):\\n            logger.debug(f\\\"Adding ~= prefix to bare version '{value}' -> '~={value}'\\\")\\n            return f\\\"~={value}\\\"\\n\\n        return value\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/settings/groups/observability.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6529fe31f67099f2f8cb296589c0cffbbef859d952c8db8df003eaa153d134fa\",\"content\":\"from pydantic import BaseModel\\n\\n\\nclass ObservabilitySettings(BaseModel):\\n    \\\"\\\"\\\"Metrics exposure and historical record retention.\\\"\\\"\\\"\\n\\n    prometheus_enabled: bool = False\\n    \\\"\\\"\\\"If set to True, Langflow will expose Prometheus metrics.\\\"\\\"\\\"\\n    prometheus_port: int = 9090\\n    \\\"\\\"\\\"The port on which Langflow will expose Prometheus metrics. 9090 is the default port.\\\"\\\"\\\"\\n\\n    max_transactions_to_keep: int = 3000\\n    \\\"\\\"\\\"The maximum number of transactions to keep in the database.\\\"\\\"\\\"\\n    max_vertex_builds_to_keep: int = 3000\\n    \\\"\\\"\\\"The maximum number of vertex builds to keep in the database.\\\"\\\"\\\"\\n    max_vertex_builds_per_vertex: int = 50\\n    \\\"\\\"\\\"The maximum number of builds to keep per vertex. Older builds will be deleted.\\\"\\\"\\\"\\n    max_flow_version_entries_per_flow: int = 50\\n    \\\"\\\"\\\"Max version history entries per flow. Oldest entries pruned on next snapshot.\\n\\n    If retroactively lowered below the current count for a flow,\\n    the oldest entries are deleted only when the next entry is created.\\n    \\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/settings/groups/paths.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d39923411c58efacd6837cb64916a447392f3c425050087db6e245367aa83cda\",\"content\":\"from pathlib import Path\\nfrom typing import Any\\n\\nfrom pydantic import BaseModel, Field, field_validator\\n\\n\\nclass PathSettings(BaseModel):\\n    \\\"\\\"\\\"Filesystem paths Langflow reads from and writes to.\\\"\\\"\\\"\\n\\n    config_dir: str | None = None\\n    \\\"\\\"\\\"Base directory for Langflow data (db, logs, caches).\\\"\\\"\\\"\\n\\n    knowledge_bases_dir: str | None = \\\"~/.langflow/knowledge_bases\\\"\\n    \\\"\\\"\\\"The directory to store knowledge bases.\\\"\\\"\\\"\\n\\n    kb_disk_reconcile_enabled: bool = False\\n    \\\"\\\"\\\"Whether startup scans ``knowledge_bases_dir`` for KB directories lacking a DB row.\\n\\n    The ``knowledge_base`` table is the sole authority for KB metadata; the on-disk\\n    ``embedding_metadata.json`` sidecar is no longer written or read by any steady-state\\n    code path. This reconcile exists only to adopt directories left by a Langflow version\\n    that predates that change, so it is off by default and pays no boot cost.\\n\\n    Set ``LANGFLOW_KB_DISK_RECONCILE_ENABLED=true`` to re-enable it at startup, or run it\\n    once on demand with ``langflow reconcile-kb-from-disk`` (which also accepts\\n    ``--dry-run``). It never deletes anything and is idempotent.\\\"\\\"\\\"\\n\\n    kb_allowed_folder_roots: list[str] = []\\n    \\\"\\\"\\\"Allow-list of directories the folder-ingestion endpoint may read from.\\n\\n    Comma-separated when set via env (``LANGFLOW_KB_ALLOWED_FOLDER_ROOTS``),\\n    e.g. ``/srv/docs,/data/shared``. Empty by default \u2014 operators must opt in.\\n    ``POST /api/v1/knowledge_bases/{kb_name}/ingest/folder`` refuses to walk any\\n    directory that is not equal to or inside one of these roots; symlink escapes\\n    are blocked because the path is resolved before the containment check. Leave\\n    empty in multi-tenant cloud deployments to refuse arbitrary-path access.\\\"\\\"\\\"\\n\\n    kb_folder_max_file_size_bytes: int = Field(default=25 * 1024 * 1024, gt=0)\\n    \\\"\\\"\\\"Maximum file size accepted by Knowledge Base folder ingestion.\\n\\n    Set ``LANGFLOW_KB_FOLDER_MAX_FILE_SIZE_BYTES`` to an operator-chosen positive\\n    byte count. Public ingestion routes inject this value into ``FolderSource``;\\n    request bodies cannot raise or lower the server-owned limit.\\\"\\\"\\\"\\n\\n    directory_component_allowed_roots: list[str] = []\\n    \\\"\\\"\\\"Additional directories the legacy Directory component may read from.\\n\\n    The component always allows paths equal to or inside the process working\\n    directory. Operators can set ``LANGFLOW_DIRECTORY_COMPONENT_ALLOWED_ROOTS``\\n    as a comma-separated list for other trusted read-only content roots. Parent\\n    traversal and symlink escapes are still blocked after canonicalization.\\\"\\\"\\\"\\n\\n    @field_validator(\\\"config_dir\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def set_langflow_dir(cls, value: Any) -> str:\\n        if not value:\\n            from platformdirs import user_cache_dir\\n\\n            app_name = \\\"langflow\\\"\\n            app_author = \\\"langflow\\\"\\n\\n            cache_dir = user_cache_dir(app_name, app_author)\\n\\n            value = Path(cache_dir)\\n            value.mkdir(parents=True, exist_ok=True)\\n\\n        if isinstance(value, str):\\n            value = Path(value)\\n        value = value.resolve()\\n        if not value.exists():\\n            value.mkdir(parents=True, exist_ok=True)\\n\\n        return str(value)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/settings/groups/runtime.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"00f13dab388a31e3cfca678b5e26a52fac1eea23b9a956fd74a748efe7500d25\",\"content\":\"from typing import Literal\\n\\nfrom pydantic import BaseModel, Field, field_validator\\n\\nfrom lfx.log.logger import logger\\n\\n\\nclass RuntimeSettings(BaseModel):\\n    \\\"\\\"\\\"Runtime behaviors: event delivery, worker timeouts, polling intervals, public flows, misc toggles.\\n\\n    Note: ``event_delivery`` is validated here but reads ``workers`` from\\n    :class:`ServerSettings`. The composition order in :class:`Settings`\\n    guarantees ``workers`` is in ``info.data`` when this validator runs.\\n    \\\"\\\"\\\"\\n\\n    warm_registry_enabled: bool = False\\n    \\\"\\\"\\\"Enable the process-local warm graph registry (LANGFLOW_WARM_REGISTRY_ENABLED).\\\"\\\"\\\"\\n\\n    warm_registry_preload_limit: int = Field(default=0, ge=0)\\n    \\\"\\\"\\\"Maximum flows each worker eagerly preloads (LANGFLOW_WARM_REGISTRY_PRELOAD_LIMIT).\\n\\n    The safe default is zero: flows warm lazily after an authorized request, so\\n    enabling the cache on a shared cluster cannot make every worker materialize\\n    every tenant's saved graph. Dedicated trusted execution workers may opt into\\n    a bounded preload. Must be >= 0.\\n    \\\"\\\"\\\"\\n\\n    warm_registry_max_entries: int = Field(default=128, gt=0)\\n    \\\"\\\"\\\"Maximum resident flow templates per worker (LANGFLOW_WARM_REGISTRY_MAX_ENTRIES).\\\"\\\"\\\"\\n\\n    warm_registry_max_flow_bytes: int = Field(default=2_000_000, gt=0)\\n    \\\"\\\"\\\"Maximum serialized retained execution snapshot eligible for warming, in bytes.\\\"\\\"\\\"\\n\\n    warm_registry_max_total_bytes: int = Field(default=32_000_000, gt=0)\\n    \\\"\\\"\\\"Maximum total serialized execution-snapshot bytes retained or in flight per worker.\\\"\\\"\\\"\\n\\n    dev: bool = False\\n    \\\"\\\"\\\"If True, Langflow will run in development mode.\\\"\\\"\\\"\\n\\n    warm_reconcile_interval: float = Field(default=20.0, gt=0)\\n    \\\"\\\"\\\"Seconds between warm-registry reconcile passes (LANGFLOW_WARM_RECONCILE_INTERVAL).\\n\\n    Each execution machine independently diffs its in-memory registry against the\\n    shared ``flow`` table every ``interval`` seconds, so a deploy or delete takes up\\n    to this long to propagate across the fleet. Lower for faster convergence at the\\n    cost of more manifest queries. Only used when ``warm_registry_enabled`` is true.\\n    Must be > 0.\\\"\\\"\\\"\\n\\n    # Job Queue\\n    job_queue_type: Literal[\\\"asyncio\\\", \\\"redis\\\"] = \\\"asyncio\\\"\\n    \\\"\\\"\\\"The job queue backend. Use 'redis' for multi-worker deployments to solve cross-worker JobQueueNotFoundError.\\\"\\\"\\\"\\n    dangerously_allow_multi_worker_without_shared_queue: bool = False\\n    \\\"\\\"\\\"Opt out of the startup guard that refuses ``workers > 1`` with the default\\n    in-memory job queue.\\n\\n    Off by default. Enabling it lets headless deployments take multi-worker\\n    throughput without standing up Redis, at the cost of every behavior that\\n    needs process-shared state: the v1 ``/build`` editor and playground flows and\\n    MCP over SSE stop working, and rate limiting, webhook UI feedback, and the\\n    orphan sweep degrade to per-worker or per-node. ``LANGFLOW_JOB_QUEUE_TYPE=redis``\\n    remains the supported way to run multiple workers; see\\n    ``langflow.__main__.ensure_multi_worker_safe`` for the full list of caveats\\n    logged when the bypass is active.\\\"\\\"\\\"\\n    redis_queue_host: str | None = None\\n    \\\"\\\"\\\"Redis host for the job queue. Falls back to redis_host if not set.\\\"\\\"\\\"\\n    redis_queue_port: int | None = None\\n    \\\"\\\"\\\"Redis port for the job queue. Falls back to redis_port if not set.\\\"\\\"\\\"\\n    redis_queue_db: int = 1\\n    \\\"\\\"\\\"Redis DB number for the job queue. Defaults to 1 to avoid conflict with the cache (DB 0).\\\"\\\"\\\"\\n    redis_queue_url: str | None = None\\n    \\\"\\\"\\\"Full Redis URL for the job queue. Takes priority over host/port/db if set.\\\"\\\"\\\"\\n    redis_queue_ttl: int = 3600\\n    \\\"\\\"\\\"TTL in seconds for job stream keys in Redis.\\\"\\\"\\\"\\n    redis_queue_startup_grace_s: float = Field(default=30.0, ge=0)\\n    \\\"\\\"\\\"Seconds a cross-worker consumer waits for the producer's first XADD before\\n    treating a missing stream key as end-of-stream. Bump this if cold-start build\\n    latency on the producer worker can exceed the default (e.g. large graph\\n    instantiation, slow container image pulls). Negative values would make\\n    consumers treat a not-yet-created stream as EOF immediately, so values must\\n    be non-negative.\\\"\\\"\\\"\\n    redis_queue_cancel_channel_enabled: bool = True\\n    \\\"\\\"\\\"If True, RedisJobQueueService runs a single PSUBSCRIBE dispatcher per worker\\n    so POST /build/{job_id}/cancel works cross-worker. Any worker can publish a\\n    cancel signal; the owning worker cancels the local build task.\\\"\\\"\\\"\\n    redis_queue_cancel_marker_ttl: int = Field(default=60, gt=0)\\n    \\\"\\\"\\\"TTL in seconds for the persistent cancel-marker key used to close the race\\n    where a cancel signal is published before the owning worker's dispatcher\\n    subscribes or before the job is registered. Should comfortably exceed worker\\n    cold-start latency. Must be > 0: a non-positive TTL makes the marker\\n    ineffective and reopens the publish-before-subscribe race it closes.\\\"\\\"\\\"\\n    redis_queue_polling_stale_threshold_s: float = Field(default=90.0, ge=0)\\n    \\\"\\\"\\\"Maximum seconds a polling job may go without client activity before the\\n    watchdog publishes a cross-worker cancel. Polling clients have no persistent\\n    connection, so the server detects abandonment by tracking the most recent\\n    poll (or streaming-response heartbeat). Set to 0 to disable the watchdog.\\\"\\\"\\\"\\n    redis_queue_polling_watchdog_interval_s: float = Field(default=15.0, gt=0)\\n    \\\"\\\"\\\"How often the polling watchdog scans owned jobs. Smaller values give\\n    faster reclamation of abandoned builds at the cost of more Redis GETs.\\n    The watchdog only checks jobs this worker owns (entries in self._queues).\\n    Must be > 0 so the scan loop makes progress.\\\"\\\"\\\"\\n\\n    # Background execution (v2 workflows background mode)\\n    background_max_concurrency: int = Field(default=5, gt=0)\\n    \\\"\\\"\\\"Max number of background workflow jobs the in-process executor runs\\n    concurrently. Jobs beyond this queue and start as workers free up. Kept\\n    small by default so background runs cannot starve the request event loop;\\n    raise it for dedicated worker processes. The redis backend ignores this in\\n    favor of its own worker-process pool. Must be > 0.\\\"\\\"\\\"\\n    background_job_timeout: float | None = None\\n    \\\"\\\"\\\"Wall-clock seconds a single background job may run before it is marked\\n    TIMED_OUT. ``None`` (default) means no timeout. Applies per job, enforced by\\n    the runner via ``asyncio.wait_for`` around the build loop.\\\"\\\"\\\"\\n    background_input_deadline_s: float | None = None\\n    \\\"\\\"\\\"Optional wall-clock seconds a background run may stay SUSPENDED (awaiting human\\n    input) before it is given up on. Independent of ``background_job_timeout``: paused\\n    time never accrues against the compute timeout (resume re-enqueues a fresh pass).\\n    ``None`` (default) disables the deadline \u2014 nothing is stamped, nothing enforced.\\n    Enforced by ``sweep_input_deadlines`` (startup sweep + the periodic watchdog when\\n    the setting is set), which FAILs overdue runs with an ``input_timed_out`` error.\\\"\\\"\\\"\\n    background_lease_ttl_s: float = Field(default=45.0, gt=0)\\n    \\\"\\\"\\\"Liveness lease window for a running background job. The running owner\\n    refreshes a heartbeat on the job row; a reconciler (startup sweep / scaled\\n    watchdog) only fails or requeues an IN_PROGRESS job whose heartbeat is older\\n    than this TTL (or never recorded). Must comfortably exceed\\n    ``background_heartbeat_interval_s`` so a healthy owner never looks stale.\\\"\\\"\\\"\\n    background_heartbeat_interval_s: float = Field(default=15.0, gt=0)\\n    \\\"\\\"\\\"How often a running background job refreshes its liveness heartbeat. Kept\\n    well below ``background_lease_ttl_s`` so a brief stall does not trip the\\n    reconciler. Must be > 0.\\\"\\\"\\\"\\n    background_watchdog_interval_s: float = Field(default=15.0, gt=0)\\n    \\\"\\\"\\\"How often the scaled worker's periodic watchdog scans for orphaned leases\\n    (a dead worker's in-flight job) and reconciles them WITHOUT requiring a\\n    restart. Must be > 0.\\\"\\\"\\\"\\n    test_redis_url: str | None = Field(default=None)\\n    \\\"\\\"\\\"Redis URL used by tests that exercise the scaled background backend.\\n\\n    Mirrors LANGFLOW_TEST_DATABASE_URI: when set, lease/watchdog/Streams/pubsub\\n    timing tests run against this real Redis; when unset they skip. Read from\\n    the LANGFLOW_TEST_REDIS_URL environment variable via the env_prefix.\\\"\\\"\\\"\\n\\n    event_delivery: Literal[\\\"polling\\\", \\\"streaming\\\", \\\"direct\\\"] = \\\"streaming\\\"\\n    \\\"\\\"\\\"How to deliver build events to the frontend. Can be 'polling', 'streaming' or 'direct'.\\\"\\\"\\\"\\n\\n    worker_timeout: int = 300\\n    \\\"\\\"\\\"Timeout for the API calls in seconds.\\\"\\\"\\\"\\n\\n    workflow_execution_timeout: int = 300\\n    \\\"\\\"\\\"Wall-clock ceiling in seconds for a client-attached v2 workflow run.\\n    Sync runs raise a 408; stream and public runs emit the protocol's terminal-error\\n    event. Background runs use ``background_job_timeout`` instead.\\\"\\\"\\\"\\n\\n    model_provider_policy_refresh_interval_s: float = Field(default=10.0, gt=0)\\n    \\\"\\\"\\\"How often each backend worker refreshes the install-wide model-provider policy.\\n\\n    A several-second default limits steady-state database traffic while still\\n    converging policy updates promptly across workers. Must be positive so the\\n    refresh loop cannot spin continuously.\\n    \\\"\\\"\\\"\\n\\n    public_flow_cleanup_interval: int = Field(default=3600, gt=600)\\n    \\\"\\\"\\\"The interval in seconds at which public temporary flows will be cleaned up.\\n    Default is 1 hour (3600 seconds). Minimum is 600 seconds (10 minutes).\\\"\\\"\\\"\\n    public_flow_expiration: int = Field(default=86400, gt=600)\\n    \\\"\\\"\\\"The time in seconds after which a public temporary flow will be considered expired and eligible for cleanup.\\n    Default is 24 hours (86400 seconds). Minimum is 600 seconds (10 minutes).\\\"\\\"\\\"\\n\\n    webhook_polling_interval: int = 0\\n    \\\"\\\"\\\"The polling interval for the webhook in ms. Set to 0 to disable (SSE provides real-time updates).\\\"\\\"\\\"\\n    fs_flows_polling_interval: int = 10000\\n    \\\"\\\"\\\"The polling interval in milliseconds for synchronizing flows from the file system.\\\"\\\"\\\"\\n\\n    health_check_max_retries: int = 5\\n    \\\"\\\"\\\"The maximum number of retries for the health check.\\\"\\\"\\\"\\n\\n    max_file_size_upload: int = 1024\\n    \\\"\\\"\\\"The maximum file size for the upload in MB.\\\"\\\"\\\"\\n\\n    max_ingestion_timeout_secs: int = 600\\n\\n    celery_enabled: bool = False\\n\\n    executor_kind: str = \\\"in-process\\\"\\n    \\\"\\\"\\\"The default executor kind used by the execution coordinator.\\n\\n    Must match the `kind` of an Executor registered with the executor service. The built-in\\n    `in-process` executor runs graphs in the current process; third-party executors registered\\n    via the `lfx.executors` entry-point group can be selected by setting this to their kind.\\n    \\\"\\\"\\\"\\n\\n    @field_validator(\\\"event_delivery\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def set_event_delivery(cls, value, info):\\n        # Multi-worker deployments with the in-memory job queue cannot route\\n        # ``polling`` or ``streaming`` responses correctly: build events live in\\n        # the in-process queue of whichever worker started the job, and a later\\n        # poll/stream request may land on a different worker.  Switch to Redis\\n        # (LANGFLOW_JOB_QUEUE_TYPE=redis) to share state across workers, or\\n        # accept ``direct`` delivery which keeps the whole exchange on one\\n        # worker.  The override below preserves backwards compatibility for\\n        # deployments that haven't set this explicitly; new explicit values are\\n        # logged loudly so the cause is easy to diagnose if the UI loses events.\\n        if info.data.get(\\\"workers\\\", 1) > 1 and info.data.get(\\\"job_queue_type\\\", \\\"asyncio\\\") != \\\"redis\\\":\\n            requested = value or \\\"polling\\\"\\n            if requested != \\\"direct\\\":\\n                logger.warning(\\n                    \\\"Multi-worker mode without a Redis-backed job queue cannot deliver \\\"\\n                    \\\"'%s' events across workers; forcing event_delivery='direct'. \\\"\\n                    \\\"Set LANGFLOW_JOB_QUEUE_TYPE=redis to keep '%s' delivery in multi-worker setups.\\\",\\n                    requested,\\n                    requested,\\n                )\\n            return \\\"direct\\\"\\n        return value\\n\\n    @property\\n    def background_backend_is_scaled(self) -> bool:\\n        \\\"\\\"\\\"True when the background executor should use the redis-backed queue.\\n\\n        Backend selection follows the existing job_queue_type/redis settings:\\n        a redis job queue means a separate `langflow worker` process drains\\n        jobs, so the scaled background backend is used. Otherwise the default\\n        in-process executor runs jobs inside the API process.\\n        \\\"\\\"\\\"\\n        return self.job_queue_type == \\\"redis\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/settings/groups/security.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6d0dbf4975cc8d57a9070a5c20eebc84b60c6765a3a5c78eda4f8402669889f6\",\"content\":\"from typing import Literal\\n\\nfrom pydantic import BaseModel, Field, field_validator\\n\\n\\nclass SecuritySettings(BaseModel):\\n    \\\"\\\"\\\"CORS, SSRF protection, API key handling, and custom-component policy.\\\"\\\"\\\"\\n\\n    # CORS\\n    cors_origins: list[str] | str = \\\"*\\\"\\n    \\\"\\\"\\\"Allowed origins for CORS. Can be a list of origins or '*' for all origins.\\n    Default is '*' for backward compatibility. In production, specify exact origins.\\\"\\\"\\\"\\n    cors_allow_credentials: bool = True\\n    \\\"\\\"\\\"Whether to allow credentials in CORS requests.\\n    Default is True for backward compatibility. In v2.0, this will be changed to False when using wildcard origins.\\\"\\\"\\\"\\n    cors_allow_methods: list[str] | str = \\\"*\\\"\\n    \\\"\\\"\\\"Allowed HTTP methods for CORS requests.\\\"\\\"\\\"\\n    cors_allow_headers: list[str] | str = \\\"*\\\"\\n    \\\"\\\"\\\"Allowed headers for CORS requests.\\\"\\\"\\\"\\n\\n    # SSRF Protection\\n    ssrf_protection_enabled: bool = True\\n    \\\"\\\"\\\"If set to True, Langflow will enable SSRF (Server-Side Request Forgery) protection.\\n    When enabled, blocks requests to private IP ranges, localhost, and cloud metadata endpoints.\\n    When False, no URL validation is performed, allowing requests to any destination\\n    including internal services, private networks, and cloud metadata endpoints.\\n    Default is True to protect against SSRF attacks including DNS rebinding.\\n\\n    Note: When ssrf_protection_enabled is disabled, the ssrf_allowed_hosts setting is ignored and has no effect.\\\"\\\"\\\"\\n    ssrf_allowed_hosts: list[str] = []\\n    \\\"\\\"\\\"Comma-separated list of hosts/IPs/CIDR ranges to allow despite SSRF protection.\\n    Examples: 'internal-api.company.local,192.168.1.0/24,10.0.0.5,*.dev.internal'\\n    Supports exact hostnames, wildcard domains (*.example.com), exact IPs, and CIDR ranges.\\n\\n    Note: This setting only takes effect when ssrf_protection_enabled is True.\\n    When protection is disabled, all hosts are allowed regardless of this setting.\\\"\\\"\\\"\\n    connector_ssrf_validation_enabled: bool = True\\n    \\\"\\\"\\\"SSRF validation for CONNECTOR components that take a tenant-controlled host/URL:\\n    vector stores (Chroma/Qdrant/Elasticsearch/OpenSearch/Milvus/Weaviate/Supabase/Upstash/\\n    ClickHouse), the SQL Database components, the Glean and AstraDB-CQL tools, the DataStax\\n    Astra DB / HCD API endpoint (shared by the Data API, tool, vector store, graph and chat-memory\\n    components), model-provider model discovery (LiteLLM/HuggingFace/xAI/DeepSeek/Groq/watsonx),\\n    the Ollama / LM Studio / Home Assistant base-URL fields, the A2A Agent agent URL, and the\\n    PaddleOCR base URL.\\n\\n    Default True: connector host validation follows ssrf_protection_enabled / ssrf_allowed_hosts\\n    so tenant-controlled connector URLs cannot reach internal/cloud-metadata hosts by default.\\n    Single-tenant/self-hosted operators who intentionally point connectors at localhost or private\\n    networks can either allowlist those hosts or set this to False. For the SQL Database\\n    components, the separate LANGFLOW_RESTRICT_LOCAL_FILE_ACCESS toggle still governs local-file\\n    dialects (e.g. sqlite) independently of this flag.\\\"\\\"\\\"\\n    connector_ssrf_allow_loopback: bool = True\\n    \\\"\\\"\\\"Whether a literal loopback host (localhost, 127.0.0.0/8, ::1) is allowed for ordinary HTTP\\n    CONNECTOR URLs, even while connector SSRF validation is on.\\n\\n    Default True because connectors routinely target a *local* service: Ollama and LM Studio\\n    default to http://localhost:11434 / http://localhost:1234, and local vector stores bind to\\n    loopback. Blocking loopback by default would break those single-tenant setups out of the box.\\n    Cloud-metadata (169.254.169.254) and private/RFC1918 ranges are still blocked regardless.\\n\\n    Multi-tenant deployers, where a tenant pointing a connector at the *server's* loopback is an\\n    SSRF vector, set this to False to block loopback too. Only literal loopback references are\\n    exempted \u2014 a hostname that *resolves* to loopback is still blocked, so DNS-rebinding cannot\\n    abuse this. When SSRF validation is enabled, credential-bearing URLs guarded by\\n    ``lfx.base.models.provider_ssrf`` use the strict path and require an explicit\\n    ``ssrf_allowed_hosts`` entry for loopback. Has no effect on the API Request component,\\n    database URLs, or git URLs, which validate loopback independently.\\\"\\\"\\\"\\n\\n    # API key handling\\n    disable_track_apikey_usage: bool = False\\n    remove_api_keys: bool = False\\n\\n    # Custom Component Security\\n    allow_custom_components: bool = True\\n    \\\"\\\"\\\"If set to False, blocks execution of components whose code does not match a known\\n    server template and disables registered built-in code-execution components at runtime.\\n\\n    The server validates node code against its component template cache;\\n    when the cache is not yet loaded (e.g., during startup), all flow execution is blocked\\n    as a safety measure.\\n\\n    Note: LANGFLOW_COMPONENTS_PATH and LANGFLOW_COMPONENTS_INDEX_PATH can be used to define\\n    an allow-list of custom components that will be allowed to execute, even when\\n    allow_custom_components is False. That bypass can be disabled with\\n    allow_components_paths_override.\\n\\n    Note: this is a beta feature. For security in a multi-tenant environment,\\n    use hardware-level isolation to restrict access.\\\"\\\"\\\"\\n    custom_component_admin_only: bool = False\\n    \\\"\\\"\\\"If set to True, only admin users can edit custom component code. Regular editors\\n    are blocked from modifying custom component templates.\\\"\\\"\\\"\\n\\n    allow_components_paths_override: bool = True\\n    \\\"\\\"\\\"If set to False, LANGFLOW_COMPONENTS_PATH and LANGFLOW_COMPONENTS_INDEX_PATH will\\n    not bypass the allow_custom_components=False restriction \u2014 only components matching\\n    built-in server templates will be executable.\\n\\n    Default is True, which preserves the existing behavior: components loaded from those\\n    env-var paths act as an admin-curated allow-list that remains executable even when\\n    allow_custom_components is False.\\n\\n    Has no effect when allow_custom_components is True (the flag is not blocking anything\\n    to override).\\\"\\\"\\\"\\n\\n    allow_public_custom_components: bool = False\\n    \\\"\\\"\\\"If set to True, the unauthenticated public flow build path\\n    (POST /api/v1/build_public_tmp/{flow_id}/flow) honors allow_custom_components just like\\n    the authenticated build path, building the flow from the database as its owner.\\n\\n    Default is False: on the public path the server substitutes its own trusted code into\\n    every known component and rejects unrecognized custom components, so anonymous visitors\\n    can only ever run server code that matches a known component template. The global\\n    allow_custom_components flag grants custom-code execution to *authenticated* users; it is\\n    intentionally not extended to the unauthenticated public path, which builds flows as their\\n    owner (report H1-3754930 follow-up). Enable this only if you knowingly want public flows to\\n    run custom component code permitted by allow_custom_components.\\\"\\\"\\\"\\n\\n    substitute_outdated_component_code: bool = True\\n    \\\"\\\"\\\"Whether a built-in component whose stored code has drifted from this server's copy is\\n    rebuilt with this server's code instead of being refused. Only consulted when\\n    ``allow_custom_components`` is False (with the default True nothing is gated, so nothing is\\n    substituted).\\n\\n    With ``allow_custom_components=False`` the node's stored code never runs anyway \u2014 the build\\n    already substitutes the server's copy keyed by code hash (``resolve_trusted_code_for_build``).\\n    The hash check therefore refuses flows over code it was not going to execute, which makes every\\n    upgrade that touches a built-in component break every saved flow using it until each node is\\n    updated by hand.\\n\\n    Default is True: a node whose ``type`` is a known server component is rebuilt with that\\n    component's current server code, matching what the unauthenticated public build path already\\n    does by default (see ``prepare_public_flow_build``). Nothing new becomes runnable \u2014 the code\\n    that runs is always this server's own, selected by component type, and a node whose type is\\n    not a known server component is still refused. Substitutions are logged, and the stored flow is\\n    left untouched so the editor keeps flagging the node as outdated.\\n\\n    Set to False to keep the strict behavior: refuse the build whenever a node's stored code does\\n    not match the current server template. Has no effect when ``allow_custom_components`` is True.\\\"\\\"\\\"\\n\\n    block_code_interpreter_components: bool = False\\n    \\\"\\\"\\\"If set to True, blocks built-in components that execute user- or model-supplied\\n    Python, including Python Interpreter/REPL/Function, Smart Transform, CSV Agent,\\n    CodeAct, Cuga, and OpenDsStar.\\n\\n    The policy is enforced during flow validation and again during component and tool\\n    execution. ``LANGFLOW_ALLOW_CUSTOM_COMPONENTS=false`` also disables these registered\\n    code-execution components while blocking user-authored component code. Set this flag\\n    independently when custom components should remain allowed but built-in code execution\\n    should not.\\n\\n    Defaults to False to preserve existing single-tenant behavior.\\\"\\\"\\\"\\n\\n    sandbox_backend: str = \\\"none\\\"\\n    \\\"\\\"\\\"Execution backend for user-authored code in the code-execution components\\n    (Python Interpreter and the legacy Python REPL tool).\\n\\n    - \\\"none\\\" (default): code runs in-process via ``exec`` with the best-effort\\n      Python-level hardening (restricted builtins + AST checks). Preserves existing\\n      behavior; nothing extra to install.\\n    - \\\"exec-sandbox\\\": each execution runs in a dedicated QEMU microVM via the\\n      optional ``exec-sandbox`` package (``pip install 'langflow[sandbox]'``;\\n      requires Python >= 3.12 and QEMU 8+ with KVM/HVF hardware acceleration \u2014\\n      hosts without a hardware hypervisor are refused unless\\n      ``sandbox_allow_software_emulation`` is enabled). The VM has a read-only\\n      rootfs, no host filesystem access, and no network unless\\n      ``sandbox_allow_network`` is enabled. In this mode the Python-level import\\n      allow-list and AST escape-gadget restrictions are not applied \u2014 the VM\\n      boundary replaces them \u2014 so sandboxed code may import any module available\\n      in the guest image. If the backend is configured but unusable, execution\\n      fails closed with an error instead of silently running in-process.\\n\\n    See https://github.com/langflow-ai/langflow/issues/12029.\\\"\\\"\\\"\\n\\n    sandbox_timeout_seconds: int = Field(default=30, ge=1, le=300)\\n    \\\"\\\"\\\"Wall-clock limit for one sandboxed execution, in seconds (1-300).\\n    Only used when sandbox_backend is not \\\"none\\\".\\\"\\\"\\\"\\n\\n    sandbox_memory_mb: int = Field(default=192, ge=128)\\n    \\\"\\\"\\\"Guest VM memory for sandboxed executions, in MB (minimum 128).\\n    Only used when sandbox_backend is not \\\"none\\\".\\\"\\\"\\\"\\n\\n    sandbox_allow_network: bool = False\\n    \\\"\\\"\\\"Whether sandboxed code may access the network. Default False: the microVM\\n    runs fully offline, which is the strongest isolation. Note the in-process\\n    backend has full server-side network access, so enabling the sandbox with the\\n    default here is a behavior change for code that fetches URLs.\\n\\n    When enabled WITHOUT ``sandbox_allowed_domains``, exec-sandbox's DNS filter\\n    still only permits its package-registry defaults (PyPI /\\n    files.pythonhosted.org) \u2014 ordinary APIs stay unreachable until their domains\\n    are listed explicitly. Only used when sandbox_backend is not \\\"none\\\".\\\"\\\"\\\"\\n\\n    sandbox_allowed_domains: list[str] = []\\n    \\\"\\\"\\\"Comma-separated list of domains sandboxed code may reach when\\n    ``sandbox_allow_network`` is enabled (forwarded to exec-sandbox's DNS\\n    filter). Empty (default) keeps exec-sandbox's package-registry-only\\n    default. Listing a domain here permits guest egress to it, so treat this\\n    like an SSRF allow-list: prefer narrow, fully-qualified domains.\\n    Only used when sandbox_backend is not \\\"none\\\".\\\"\\\"\\\"\\n\\n    sandbox_allow_software_emulation: bool = False\\n    \\\"\\\"\\\"Permit the sandbox to run without a hardware hypervisor (KVM on Linux,\\n    HVF on macOS), letting QEMU fall back to TCG software emulation.\\n\\n    Default False and strongly recommended to keep it that way: upstream\\n    exec-sandbox documents TCG as NOT security-supported (and ~5-8x slower),\\n    while sandbox mode disables the in-process Python defenses on the\\n    assumption of a hardware boundary. Enable only for trusted/development\\n    workloads, e.g. CI smoke tests or containers without /dev/kvm passthrough.\\n    Only used when sandbox_backend is not \\\"none\\\".\\\"\\\"\\\"\\n\\n    restrict_local_file_access: bool = False\\n    \\\"\\\"\\\"If set to True, the built-in file-reading components (File, Directory, JSON/CSV-to-Data)\\n    may only read paths that resolve inside the authenticated user's or executing flow's storage\\n    subdirectory under ``config_dir``, where uploaded files live.\\n\\n    These components accept a filesystem path from a tenant-controlled input field. With the\\n    default (False) a tenant can set that path to an absolute server path (``/etc/passwd``, the\\n    SQLite DB, secrets) or a traversal string and read arbitrary server files \u2014 or another\\n    tenant's uploads. Multi-tenant / untrusted-user deployments that disallow user-authored\\n    components should set this to True (alongside ``LANGFLOW_ALLOW_CUSTOM_COMPONENTS=false``) so\\n    these components cannot read server files or storage belonging to another user or flow.\\n\\n    Defaults to False to preserve existing single-tenant behavior, where reading local server\\n    files by absolute path is a legitimate feature.\\\"\\\"\\\"\\n\\n    mcp_server_docker_hardening: bool = False\\n    \\\"\\\"\\\"If set to True, applies a strict docker-argument policy to MCP stdio servers (both\\n    flow-embedded configs and the ``/api/v2/mcp/servers`` REST endpoint).\\n\\n    ``docker`` is an allowed MCP transport, but flags like ``-v /:/host`` (mount the host\\n    filesystem), ``--use-api-socket`` (Docker-API root), ``--env-file`` (host file read),\\n    ``--device``, ``--network host``, and ``--privileged`` turn a container run into host access.\\n    With the default (False) only ``--privileged`` / ``--cap-add`` and the host-namespace ``=``\\n    forms are blocked, which preserves existing single-tenant behavior where docker MCP servers\\n    legitimately use volume mounts and custom networks.\\n\\n    Multi-tenant / untrusted-tenant deployments should set this to True (alongside\\n    ``LANGFLOW_ALLOW_CUSTOM_COMPONENTS=false``): host file/API/device access, published ports,\\n    custom runtimes, restart persistence, and privilege flags are then rejected outright;\\n    host/another-container namespaces and non-default networks are rejected; and\\n    ``--security-opt`` is rejected only when it disables the sandbox. Benign forms (no flags,\\n    ``--user``, ``--network none``/``bridge``, ``--security-opt no-new-privileges``) stay allowed.\\\"\\\"\\\"\\n\\n    # Runtime tweak policy\\n    tweaks_policy: Literal[\\\"permissive\\\", \\\"declared\\\", \\\"off\\\"] = \\\"permissive\\\"\\n    \\\"\\\"\\\"Which fields a run request may set through ``tweaks``.\\n\\n    ``permissive`` (default) preserves existing behavior: the protected-field floor\\n    refuses code fields and privileged sinks, and every other field accepts a tweak.\\n\\n    ``declared`` honors the per-flow allowlist the flow author sets in the parameters\\n    panel. On a flow where at least one field is marked editable via API, only those\\n    fields accept a tweak. A flow where the author has marked nothing keeps permissive\\n    behavior, so enabling this does not break flows nobody has prepared.\\n\\n    ``off`` refuses every tweak, and also refuses component-targeted ``inputs``. A\\n    caller can still send ``input_value`` and ``session_id``, so chat flows keep\\n    running.\\n\\n    The protected-field floor applies in all three modes and no setting relaxes it.\\n    ``declared`` cannot expose a code field, because the flow author's allowlist is\\n    consulted only after the floor has already refused.\\n\\n    Refused tweaks return 422 naming the refused keys in every mode. They previously\\n    logged a warning and returned 200, which left a caller unable to tell a refused\\n    tweak from an applied one.\\n\\n    This setting governs what a *caller* may override. ``tweaks`` is also the internal\\n    mechanism for passing values into a sub-flow, so tweaks the runtime generates for\\n    itself (the Run Flow component feeding its declared inputs to a sub-flow, resolved\\n    global-variable values) are not judged by it. Otherwise ``off`` would stop the Run\\n    Flow component and every flow used as an agent tool, which is not what closing an\\n    API surface should mean. The protected-field floor still applies to those.\\n\\n    MCP deserves one qualification. Its primary ``input_value`` travels through the\\n    normal graph-input channel and is not a tweak. Additional advertised input fields\\n    are translated into tweaks, so this setting judges them. Under ``off`` those extra\\n    fields are refused, while ``input_value``-only MCP tools continue to work. Use\\n    ``permissive`` or ``declared`` for MCP tools that require tweak-backed parameters.\\\"\\\"\\\"\\n    # Serving-plane end-user identity\\n    serving_end_user_header: str | None = None\\n    \\\"\\\"\\\"Name of the trusted request header that carries the end-user identity on the serving plane\\n    (e.g. ``X-End-User-Id``). The value is an opaque, deterministic per-user string minted and\\n    injected by the authenticated gateway; Langflow does not parse or validate it, it only uses it\\n    as the per-user memory/state scope key.\\n\\n    UNSET (the default) means the feature is OFF: no end-user identity is read and every serving\\n    request is fully anonymous (ephemeral, no persisted per-user memory). Setting a header name\\n    turns the feature on, but the header is still only trusted when\\n    ``serving_trust_proxy_headers`` is True.\\n\\n    Security: an unverified client-supplied header would let any caller read another user's memory,\\n    so the header must be injected/validated by the authenticated gateway and the serving pods must\\n    be reachable only through that gateway (network policy). See ``serving_trust_proxy_headers``.\\\"\\\"\\\"\\n    serving_trust_proxy_headers: bool = False\\n    \\\"\\\"\\\"Fail-closed opt-in for the serving-plane end-user identity header. The header named by\\n    ``serving_end_user_header`` is trusted ONLY when this is True.\\n\\n    Default False: even with a header name configured, the header is ignored and every request is\\n    anonymous until an operator explicitly opts in. Enable this only when the deployment guarantees\\n    (a) the authenticated gateway injects/overwrites the header from a validated identity and\\n    (b) network policy makes the gateway the only caller able to reach the serving pods. Without\\n    those two guarantees a client can spoof the header and read another user's memory.\\\"\\\"\\\"\\n    serving_end_user_required: bool = False\\n    \\\"\\\"\\\"Whether a serving request with no end-user identity is rejected. Only meaningful when the\\n    feature is on (``serving_end_user_header`` set and ``serving_trust_proxy_headers`` True).\\n\\n    Default False: a request with no identity is allowed and runs as an anonymous, ephemeral\\n    session with no persisted memory. Set True to reject identity-less requests instead (e.g. a\\n    deployment that must attribute every run to an end user).\\\"\\\"\\\"\\n    serving_trace_end_user: bool = False\\n    \\\"\\\"\\\"Whether the serving-plane end-user id is forwarded to the configured tracing provider.\\n\\n    The end-user id is PII (the same reason outbound MCP forwarding is allowlist-gated and\\n    fail-closed). Tracing providers (Langfuse, LangSmith, Opik, ...) are third-party SaaS, so this is\\n    OFF by default: an identified serving run's trace shows only the service account (SID), never the\\n    end user. Set True to surface the end user as the ``langflow.tracing_user_id`` trace label\\n    (attribution) \u2014 an explicit operator decision to send that identity off-deployment. Independent of\\n    the primary ``trace.userId``, which is always the SID regardless of this flag.\\\"\\\"\\\"\\n    serving_internal_mcp_hosts: str | None = None\\n    \\\"\\\"\\\"Comma-separated allowlist of hosts (``host`` or ``host:port``) treated as INTERNAL for\\n    outbound MCP calls. When a flow's MCPTools component calls out to a server whose host is on this\\n    list, the serving-plane end-user identity header (``serving_end_user_header``) is auto-appended\\n    so a sibling project on the same plane can attribute the run to the same end user.\\n\\n    Default UNSET means the allowlist is empty, so the end-user header is NEVER auto-appended to any\\n    outbound MCP call (fail-closed): the identity is PII and must never leak to an external MCP\\n    server. Only hosts an operator explicitly lists here \u2014 the deployment's own serving endpoints \u2014\\n    receive it. Matching is exact on the URL host (and port when given); it does not widen to\\n    subdomains. Unrelated to by-name header substitution, which stays opt-in and unaffected.\\\"\\\"\\\"\\n\\n    # Rate Limiting\\n    rate_limit_enabled: bool = True\\n    \\\"\\\"\\\"Enable rate limiting for login and public-flow endpoints. Set to False to disable.\\\"\\\"\\\"\\n    rate_limit_per_minute: int = 5\\n    \\\"\\\"\\\"Number of login attempts allowed per minute per IP.\\\"\\\"\\\"\\n    rate_limit_storage_uri: str = \\\"memory://\\\"\\n    \\\"\\\"\\\"Storage backend for rate limiting. Use 'memory://' for single-server or 'redis://host:port' for multi-server.\\\"\\\"\\\"\\n    rate_limit_trust_proxy: bool = False\\n    \\\"\\\"\\\"Trust X-Forwarded-For header when behind a reverse proxy. Only enable when behind a trusted proxy.\\\"\\\"\\\"\\n    public_flow_rate_limit_per_minute: int = 20\\n    \\\"\\\"\\\"Public-flow runs allowed per minute per IP on the unauthenticated v1 build and v2 workflow endpoints.\\n    V1 uses one bucket per flow; v2 uses its public-workflow bucket. Each run executes as the flow owner, so\\n    anonymous callers are throttled separately from and more generously than login. Gated by rate_limit_enabled.\\\"\\\"\\\"\\n\\n    @field_validator(\\\"sandbox_allowed_domains\\\", mode=\\\"after\\\")\\n    @classmethod\\n    def normalize_sandbox_allowed_domains(cls, value: list[str]) -> list[str]:\\n        \\\"\\\"\\\"Strip whitespace and drop empty entries.\\n\\n        The env parser splits ``LANGFLOW_SANDBOX_ALLOWED_DOMAINS=a.com, b.com``\\n        on commas without trimming, and exec-sandbox's DNS filter rejects\\n        entries with leading/trailing whitespace \u2014 normalize here so the\\n        natural comma-and-space spelling works.\\n        \\\"\\\"\\\"\\n        return [domain.strip() for domain in value if domain and domain.strip()]\\n\\n    @field_validator(\\\"sandbox_backend\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def validate_sandbox_backend(cls, value):\\n        \\\"\\\"\\\"Reject unknown backends at startup so a typo cannot silently disable sandboxing.\\\"\\\"\\\"\\n        # Sourced from the sandbox module rather than repeated here: a second\\n        # hand-maintained list would let the two drift, and a name accepted by\\n        # only one of them either fails at startup or reaches a dispatch that\\n        # cannot serve it.\\n        from lfx.utils.sandbox import known_sandbox_backends\\n\\n        normalized = str(value).strip().lower() if value is not None else \\\"none\\\"\\n        allowed = set(known_sandbox_backends())\\n        if normalized not in allowed:\\n            msg = f\\\"sandbox_backend must be one of {sorted(allowed)}, got {value!r}\\\"\\n            raise ValueError(msg)\\n        return normalized\\n\\n    @field_validator(\\\"cors_origins\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def validate_cors_origins(cls, value):\\n        \\\"\\\"\\\"Convert comma-separated string to list if needed.\\n\\n        Pydantic-settings on Python 3.14 parses the env var \\\"*\\\" into [\\\"*\\\"]\\n        before this validator runs (the union list[str] | str resolves\\n        differently). Collapse that back to the bare-string wildcard so\\n        downstream consumers see the same shape on every Python version.\\n        \\\"\\\"\\\"\\n        if isinstance(value, list) and value == [\\\"*\\\"]:\\n            return \\\"*\\\"\\n        if isinstance(value, str) and value != \\\"*\\\":\\n            if \\\",\\\" in value:\\n                return [origin.strip() for origin in value.split(\\\",\\\")]\\n            return [value]\\n        return value\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/settings/groups/server.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"934a9c4400fe98ad75303a632c3bcbdbbfa2da5b5969f3cf71bd0c024cf00558\",\"content\":\"import os\\nfrom pathlib import Path\\nfrom typing import Any, Literal\\nfrom urllib.parse import urlparse\\n\\nfrom pydantic import BaseModel, Field, field_validator\\n\\nfrom lfx.log.logger import logger\\n\\nDeploymentProfile = Literal[\\\"dev\\\", \\\"prod\\\"]\\n\\n\\nclass ServerSettings(BaseModel):\\n    \\\"\\\"\\\"ASGI server, process, and logging settings.\\\"\\\"\\\"\\n\\n    deployment_profile: DeploymentProfile = \\\"dev\\\"\\n    \\\"\\\"\\\"Deployment profile for this boot. 'prod' signals a production deployment and runs\\n    fail-loud infrastructure preflight checks before the server starts (aborting on missing\\n    required services). 'dev' (the default) skips those checks. Set via the\\n    LANGFLOW_DEPLOYMENT_PROFILE environment variable or the --deployment-profile CLI option.\\\"\\\"\\\"\\n    host: str = \\\"localhost\\\"\\n    \\\"\\\"\\\"The host on which Langflow will run.\\\"\\\"\\\"\\n    port: int = 7860\\n    \\\"\\\"\\\"The port on which Langflow will run.\\\"\\\"\\\"\\n    runtime_port: int | None = Field(default=None, exclude=True)\\n    \\\"\\\"\\\"TEMPORARY: The port detected at runtime after checking for conflicts.\\n    This field is system-managed only and will be removed in future versions\\n    when strict port enforcement is implemented (errors will be raised if port unavailable).\\\"\\\"\\\"\\n    workers: int = 1\\n    \\\"\\\"\\\"The number of workers to run.\\\"\\\"\\\"\\n    log_level: str = \\\"critical\\\"\\n    \\\"\\\"\\\"The log level for Langflow.\\\"\\\"\\\"\\n    log_file: str | None = \\\"logs/langflow.log\\\"\\n    \\\"\\\"\\\"The path to log file for Langflow.\\\"\\\"\\\"\\n    alembic_log_file: str = \\\"alembic/alembic.log\\\"\\n    \\\"\\\"\\\"The path to log file for Alembic for SQLAlchemy.\\\"\\\"\\\"\\n    alembic_log_to_stdout: bool = False\\n    \\\"\\\"\\\"If set to True, the log file will be ignored and Alembic will log to stdout.\\\"\\\"\\\"\\n    frontend_path: str | None = None\\n    \\\"\\\"\\\"The path to the frontend directory containing build files. This is for development purposes only.\\\"\\\"\\\"\\n    open_browser: bool = False\\n    \\\"\\\"\\\"If set to True, Langflow will open the browser on startup.\\\"\\\"\\\"\\n    backend_only: bool = False\\n    \\\"\\\"\\\"If set to True, Langflow will not serve the frontend.\\\"\\\"\\\"\\n    ssl_cert_file: str | None = None\\n    \\\"\\\"\\\"Path to the SSL certificate file on the local system.\\\"\\\"\\\"\\n    ssl_key_file: str | None = None\\n    \\\"\\\"\\\"Path to the SSL key file on the local system.\\\"\\\"\\\"\\n    root_path: str = \\\"\\\"\\n    \\\"\\\"\\\"ASGI root_path for deployments behind a reverse proxy that strips a URL\\n    prefix (e.g. '/langflow').  When set, the MCP SSE transport includes this\\n    prefix in the POST-back URL so clients can reach the correct endpoint.\\n    Can also be set via the LANGFLOW_ROOT_PATH environment variable.\\\"\\\"\\\"\\n    user_agent: str = \\\"langflow\\\"\\n    \\\"\\\"\\\"User agent for the API calls.\\\"\\\"\\\"\\n\\n    @field_validator(\\\"deployment_profile\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def validate_deployment_profile(cls, value: Any) -> str:\\n        \\\"\\\"\\\"Normalize the deployment profile so 'PROD', ' prod ' etc. resolve to the literal set.\\\"\\\"\\\"\\n        if value is None:\\n            return \\\"dev\\\"\\n        if not isinstance(value, str):\\n            msg = \\\"deployment_profile must be a string\\\"\\n            raise TypeError(msg)\\n        normalized = value.strip().lower()\\n        if normalized not in {\\\"dev\\\", \\\"prod\\\"}:\\n            msg = f\\\"deployment_profile must be one of 'dev' or 'prod', got {value!r}\\\"\\n            raise ValueError(msg)\\n        return normalized\\n\\n    @field_validator(\\\"root_path\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def validate_root_path(cls, value: Any) -> str:\\n        if value is None:\\n            return \\\"\\\"\\n        if not isinstance(value, str):\\n            msg = \\\"root_path must be a string\\\"\\n            raise TypeError(msg)\\n\\n        value = value.strip()\\n        if not value or value == \\\"/\\\":\\n            return \\\"\\\"\\n\\n        if \\\"://\\\" in value or \\\"?\\\" in value or \\\"#\\\" in value:\\n            msg = \\\"root_path must be an ASGI path prefix only, without scheme, query string, or fragment\\\"\\n            raise ValueError(msg)\\n\\n        if not value.startswith(\\\"/\\\"):\\n            value = f\\\"/{value}\\\"\\n\\n        return value.rstrip(\\\"/\\\")\\n\\n    @field_validator(\\\"runtime_port\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def validate_runtime_port(cls, value):\\n        \\\"\\\"\\\"Parse port from Kubernetes service discovery env vars.\\n\\n        Kubernetes auto-creates env vars like LANGFLOW_RUNTIME_PORT=tcp://<ip>:<port>\\n        for services, which collides with the LANGFLOW_ env prefix. Extract the port\\n        number from URL-like values instead of failing.\\n        \\\"\\\"\\\"\\n        if value is None:\\n            return None\\n        if isinstance(value, int):\\n            return value\\n        if isinstance(value, str):\\n            if value.isdigit():\\n                return int(value)\\n            if \\\"://\\\" in value:\\n                try:\\n                    parsed_port = urlparse(value).port\\n                except ValueError:\\n                    return None\\n                if parsed_port is not None:\\n                    return parsed_port\\n        return None\\n\\n    @field_validator(\\\"log_file\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def set_log_file(cls, value):\\n        if isinstance(value, Path):\\n            value = str(value)\\n        return value\\n\\n    @field_validator(\\\"user_agent\\\", mode=\\\"after\\\")\\n    @classmethod\\n    def set_user_agent(cls, value):\\n        if not value:\\n            value = \\\"Langflow\\\"\\n        os.environ[\\\"USER_AGENT\\\"] = value\\n        logger.debug(f\\\"Setting user agent to {value}\\\")\\n        return value\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/settings/groups/storage.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b99815591164236c31679837ba85b234a0767dc96b189eb8399f5b32b2125953\",\"content\":\"from pydantic import BaseModel\\n\\n\\nclass StorageSettings(BaseModel):\\n    \\\"\\\"\\\"File storage backend (local filesystem or object storage).\\\"\\\"\\\"\\n\\n    storage_type: str = \\\"local\\\"\\n    \\\"\\\"\\\"Storage type for file storage. Defaults to 'local'. Supports 'local' and 's3'.\\\"\\\"\\\"\\n    object_storage_bucket_name: str | None = \\\"langflow-bucket\\\"\\n    \\\"\\\"\\\"Object storage bucket name for file storage. Defaults to 'langflow-bucket'.\\\"\\\"\\\"\\n    object_storage_prefix: str | None = \\\"files\\\"\\n    \\\"\\\"\\\"Object storage prefix for file storage. Defaults to 'files'.\\\"\\\"\\\"\\n    object_storage_tags: dict[str, str] | None = None\\n    \\\"\\\"\\\"Object storage tags for file storage.\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/settings/groups/telemetry.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f3807c56701d83b3e7284564f612dafd58b339b4056a9c24b821ecc28b59cdcc\",\"content\":\"from typing import Literal\\n\\nfrom pydantic import BaseModel\\n\\n\\nclass TelemetrySettings(BaseModel):\\n    \\\"\\\"\\\"Telemetry, error tracking, and tracing settings.\\\"\\\"\\\"\\n\\n    # Sentry\\n    sentry_dsn: str | None = None\\n    sentry_traces_sample_rate: float | None = 1.0\\n    sentry_profiles_sample_rate: float | None = 1.0\\n\\n    # Telemetry\\n    do_not_track: bool = False\\n    \\\"\\\"\\\"If set to True, Langflow will not track telemetry.\\\"\\\"\\\"\\n    telemetry_base_url: str = \\\"https://langflow.gateway.scarf.sh\\\"\\n\\n    transactions_storage_enabled: bool = True\\n    \\\"\\\"\\\"If set to True, Langflow will track transactions between flows.\\\"\\\"\\\"\\n    vertex_builds_storage_enabled: bool = True\\n    \\\"\\\"\\\"If set to True, Langflow will keep track of each vertex builds (outputs) in the UI for any flow.\\\"\\\"\\\"\\n    sync_result_storage_enabled: bool = False\\n    \\\"\\\"\\\"If set to True, a completed ``mode=sync`` workflow run caches its outputs to ``Job.result``\\n    (and its session to ``job_metadata``) so a later GET status on that job_id returns them.\\n\\n    Off by default: sync callers already receive the full outputs and session_id in the inline\\n    response, so persisting them again is an extra per-request job-row write with no documented\\n    consumer. Enable only for a client that submits sync runs and later polls GET status. Background\\n    runs are unaffected \u2014 they always persist their result (the caller is detached and must poll).\\\"\\\"\\\"\\n\\n    telemetry_writer_enabled: bool = True\\n    \\\"\\\"\\\"Route transaction and vertex_build writes through an async batched writer backed by a\\n    disk-persisted outbox and a dedicated database connection. Eliminates SQLite\\n    'database is locked' errors and Postgres pool-timeouts under heavy load by keeping\\n    telemetry traffic off the request-handling connection pool.\\n    Set to False to fall back to the legacy direct-write path.\\\"\\\"\\\"\\n    telemetry_writer_batch_size: int = 200\\n    \\\"\\\"\\\"Maximum rows per batched INSERT executed by the telemetry writer.\\\"\\\"\\\"\\n    telemetry_writer_flush_interval_s: float = 0.5\\n    \\\"\\\"\\\"Maximum seconds the writer waits before flushing a partial batch.\\\"\\\"\\\"\\n    telemetry_writer_cleanup_interval_s: int = 60\\n    \\\"\\\"\\\"Cadence (seconds) of the retention sweeper that enforces max_transactions_to_keep\\n    and max_vertex_builds_to_keep. Retention is amortized rather than per-row to avoid\\n    inflating per-write cost.\\\"\\\"\\\"\\n    telemetry_writer_max_queue: int = 100_000\\n    \\\"\\\"\\\"Per-outbox cap. When exceeded, oldest entries are dropped and a counter is\\n    incremented. Bounds disk usage in pathological backlog scenarios.\\\"\\\"\\\"\\n    telemetry_writer_outbox_dir: str | None = None\\n    \\\"\\\"\\\"Directory for the disk-backed outbox. Defaults to\\n    <tempdir>/langflow_telemetry_outbox. Each worker process uses an isolated\\n    subdirectory keyed by PID; sibling subdirectories from crashed workers are\\n    automatically adopted on startup.\\\"\\\"\\\"\\n    telemetry_writer_shutdown_drain_s: float = 5.0\\n    \\\"\\\"\\\"Maximum seconds the writer waits to drain in-flight batches on shutdown\\n    before disposing the dedicated engine.\\\"\\\"\\\"\\n    telemetry_writer_orphan_max_age_s: float = 3600.0\\n    \\\"\\\"\\\"Cross-host orphan outboxes (e.g. dead pods on a shared volume) are pruned\\n    when their owner file hasn't been heartbeated within this many seconds.\\n    Same-host orphans are adopted regardless of age via owner-file identity.\\\"\\\"\\\"\\n    telemetry_writer_size_strategy: Literal[\\\"count\\\", \\\"bytes\\\", \\\"either\\\"] = \\\"count\\\"\\n    \\\"\\\"\\\"How the writer bounds memory and flushes.\\n\\n    - 'count' (default): preserve legacy row-count semantics. ``batch_size`` and\\n      ``max_queue`` are the only thresholds.\\n    - 'bytes': bound by the byte thresholds below; row caps are ignored.\\n    - 'either': whichever (rows or bytes) trips first wins. Recommended for\\n      deployments with variable payload sizes (large vertex_build artifacts,\\n      doc-loader outputs).\\\"\\\"\\\"\\n    telemetry_writer_batch_size_bytes: int = 262_144\\n    \\\"\\\"\\\"Cap on per-flush batch size in *encoded JSON bytes*. Consulted when\\n    ``telemetry_writer_size_strategy`` is 'bytes' or 'either'. Sized around a\\n    single TCP frame so individual INSERTs stay below DB packet limits.\\n\\n    Note: this measures the payload's serialized size, not Python's in-memory\\n    footprint (dicts carry significant overhead beyond their JSON form).\\\"\\\"\\\"\\n    telemetry_writer_max_queue_bytes: int = 209_715_200\\n    \\\"\\\"\\\"Per-outbox cap in *encoded JSON bytes*. When exceeded under 'bytes' or\\n    'either' strategy, oldest entries are dropped until the buffer fits.\\n    Defaults to ~200MB so a single worker's telemetry buffer can't dominate\\n    container memory. As with ``batch_size_bytes`` this is serialized size, not\\n    Python in-memory size \u2014 actual RSS will be 2-5x higher.\\\"\\\"\\\"\\n\\n    deactivate_tracing: bool = False\\n    \\\"\\\"\\\"If set to True, tracing will be deactivated.\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/settings/groups/ui.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b433fcaeda6ba54d87edbfd2f4dbec47cf83c9b1155c2219e414cb6abbec0bac\",\"content\":\"from pydantic import AliasChoices, BaseModel, Field\\n\\nfrom lfx.serialization.constants import MAX_ITEMS_LENGTH, MAX_TEXT_LENGTH\\n\\n\\nclass UiSettings(BaseModel):\\n    \\\"\\\"\\\"Frontend, auto-save, display limits, and (legacy) Langflow Store integration.\\\"\\\"\\\"\\n\\n    auto_saving: bool = True\\n    \\\"\\\"\\\"If set to True, Langflow will auto save flows.\\\"\\\"\\\"\\n    auto_saving_interval: int = 1000\\n    \\\"\\\"\\\"The interval in ms at which Langflow will auto save flows.\\\"\\\"\\\"\\n\\n    max_text_length: int = MAX_TEXT_LENGTH\\n    \\\"\\\"\\\"Maximum number of characters to store and display in the UI. Responses longer than this\\n    will be truncated when displayed in the UI. Does not truncate responses between components nor outputs.\\\"\\\"\\\"\\n    max_items_length: int = MAX_ITEMS_LENGTH\\n    \\\"\\\"\\\"Maximum number of items to store and display in the UI. Lists longer than this\\n    will be truncated when displayed in the UI. Does not affect data passed between components nor outputs.\\\"\\\"\\\"\\n\\n    frontend_timeout: int = 0\\n    \\\"\\\"\\\"Timeout for the frontend API calls in seconds.\\\"\\\"\\\"\\n\\n    # Embedded mode flags\\n    embedded_mode: bool = False\\n    \\\"\\\"\\\"Umbrella flag for iframe/embedded mode. When True, hides UI elements specific to\\n    standalone installations (logout button, new project/flow buttons, starter projects, etc.).\\n\\n    This flag does not implicitly enable security controls such as\\n    ``mcp_servers_locked`` or ``custom_component_admin_only``. Configure those\\n    explicitly based on your deployment hardening requirements.\\n    \\\"\\\"\\\"\\n    hide_getting_started_progress: bool = Field(\\n        default=False,\\n        validation_alias=AliasChoices(\\n            \\\"LANGFLOW_HIDE_GETTING_STARTED_PROGRESS\\\",\\n            \\\"HIDE_GETTING_STARTED_PROGRESS\\\",\\n        ),\\n    )\\n    \\\"\\\"\\\"If set to True, hides the getting-started onboarding progress UI.\\\"\\\"\\\"\\n    hide_logout_button: bool = False\\n    \\\"\\\"\\\"If set to True, hides the Logout button in the account menu.\\\"\\\"\\\"\\n    hide_new_project_button: bool = False\\n    \\\"\\\"\\\"If set to True, hides the ability to create new projects/folders.\\\"\\\"\\\"\\n    hide_new_flow_button: bool = False\\n    \\\"\\\"\\\"If set to True, hides the ability to create new flows.\\\"\\\"\\\"\\n    hide_starter_projects: bool = False\\n    \\\"\\\"\\\"If set to True, hides starter projects from the UI (does not affect database seeding).\\\"\\\"\\\"\\n\\n    # Langflow Store (legacy)\\n    store: bool | None = True\\n    store_url: str | None = \\\"https://api.langflow.store\\\"\\n    download_webhook_url: str | None = \\\"https://api.langflow.store/flows/trigger/ec611a61-8460-4438-b187-a4f65e5559d4\\\"\\n    like_webhook_url: str | None = \\\"https://api.langflow.store/flows/trigger/64275852-ec00-45c1-984e-3bff814732da\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/settings/groups/variables.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ba88792edcdc908a72d063973ec7d0d2e4c1f284d7c0c07a1f07dca9a67af9e0\",\"content\":\"from pydantic import BaseModel, Field, ValidationInfo, field_validator\\n\\nfrom lfx.services.settings.constants import AGENTIC_VARIABLES, VARIABLES_TO_GET_FROM_ENVIRONMENT\\n\\n\\nclass VariablesSettings(BaseModel):\\n    \\\"\\\"\\\"Global variable store, environment-variable bridge, and experimental feature toggles.\\\"\\\"\\\"\\n\\n    variable_store: str = \\\"db\\\"\\n    \\\"\\\"\\\"The store can be 'db' or 'kubernetes'.\\\"\\\"\\\"\\n\\n    fallback_to_env_var: bool = True\\n    \\\"\\\"\\\"If set to True, Global Variables set in the UI will fallback to a environment variable\\n    with the same name in case Langflow fails to retrieve the variable value.\\\"\\\"\\\"\\n\\n    store_environment_variables: bool = True\\n    \\\"\\\"\\\"Whether to store environment variables as Global Variables in the database.\\\"\\\"\\\"\\n\\n    # Agentic Experience\\n    agentic_experience: bool = True\\n    \\\"\\\"\\\"Whether the Langflow Assistant is available. On by default: it is the primary way into\\n    the product, so requiring opt-in would hide the main entry point behind an env var.\\n\\n    Set it to False to turn the Assistant off for a deployment -- an operator who does not want\\n    LLM-authored component code running on their server. That withholds the assistant's\\n    code-generating endpoints under ``/api/v1/agentic`` (404), the ``run_assistant`` MCP tool,\\n    the seeding of the assistant's built-in flows, and the per-user agentic global variables.\\n    It does NOT withhold the rest of the MCP toolkit at ``/api/v1/agentic/mcp``, whose tools are\\n    REST calls the API already authorizes. Note this is not the control over in-process code\\n    execution -- that is ``allow_custom_components``, which applies to the Assistant and to\\n    hand-written custom components alike.\\n    \\\"\\\"\\\"\\n\\n    assistant_max_message_length: int = Field(default=2000, ge=1)\\n    \\\"\\\"\\\"Maximum length, in characters, of a single message sent to the Langflow Assistant.\\n\\n    Enforced server-side on the assistant API entry points and mirrored to the UI through\\n    ``/api/v1/config`` so the composer and the API agree on one number -- a UI cap below the\\n    server's would silently truncate the prompt before it is ever sent. Raise it for\\n    deployments whose users paste specs or schemas into the composer; the cost of a turn grows\\n    with it, which is why it is capped at all.\\n    \\\"\\\"\\\"\\n\\n    variables_to_get_from_environment: list[str] = VARIABLES_TO_GET_FROM_ENVIRONMENT\\n    \\\"\\\"\\\"List of environment variables to get from the environment and store in the database.\\\"\\\"\\\"\\n\\n    # Developer API\\n    developer_api_enabled: bool = False\\n    \\\"\\\"\\\"If set to True, Langflow will enable developer API endpoints for advanced debugging and introspection.\\\"\\\"\\\"\\n\\n    @field_validator(\\\"variables_to_get_from_environment\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def set_variables_to_get_from_environment(cls, value, info: ValidationInfo):\\n        if isinstance(value, str):\\n            value = value.split(\\\",\\\")\\n\\n        result = list(set(VARIABLES_TO_GET_FROM_ENVIRONMENT + value))\\n\\n        if info.data.get(\\\"agentic_experience\\\", True):\\n            result.extend(AGENTIC_VARIABLES)\\n\\n        return list(set(result))\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/settings/service.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"69fd8be394007e9d985a1e53e7d1497c6870d7017f6d59e235144a785c32d97b\",\"content\":\"from __future__ import annotations\\n\\nfrom lfx.services.base import Service\\nfrom lfx.services.settings.auth import AuthSettings\\nfrom lfx.services.settings.base import Settings\\n\\n\\nclass SettingsService(Service):\\n    name = \\\"settings_service\\\"\\n\\n    def __init__(self, settings: Settings, auth_settings: AuthSettings):\\n        super().__init__()\\n        self.settings: Settings = settings\\n        self.auth_settings: AuthSettings = auth_settings\\n\\n    @classmethod\\n    def initialize(cls) -> SettingsService:\\n        # Check if a string is a valid path or a file name\\n\\n        settings = Settings()\\n        if not settings.config_dir:\\n            msg = \\\"CONFIG_DIR must be set in settings\\\"\\n            raise ValueError(msg)\\n\\n        auth_settings = AuthSettings(\\n            CONFIG_DIR=settings.config_dir,\\n        )\\n        return cls(settings, auth_settings)\\n\\n    def set(self, key, value):\\n        setattr(self.settings, key, value)\\n        return self.settings\\n\\n    async def teardown(self):\\n        pass\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/settings/utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9815742b523f82498f52b00c39a7e5a5e0cdc157b015cc78b2a0e93cf3a87237\",\"content\":\"import platform\\nfrom pathlib import Path\\n\\nfrom cryptography.hazmat.primitives import serialization\\nfrom cryptography.hazmat.primitives.asymmetric import rsa\\nfrom cryptography.hazmat.primitives.serialization import load_pem_private_key\\n\\nfrom lfx.log.logger import logger\\n\\n\\nclass RSAKeyError(Exception):\\n    \\\"\\\"\\\"Exception raised when RSA key operations fail.\\\"\\\"\\\"\\n\\n\\ndef derive_public_key_from_private(private_key_pem: str) -> str:\\n    \\\"\\\"\\\"Derive a public key from a private key PEM string.\\n\\n    Args:\\n        private_key_pem: The private key in PEM format.\\n\\n    Returns:\\n        str: The public key in PEM format.\\n\\n    Raises:\\n        RSAKeyError: If the private key is invalid or cannot be processed.\\n    \\\"\\\"\\\"\\n    try:\\n        private_key = load_pem_private_key(private_key_pem.encode(), password=None)\\n        return (\\n            private_key.public_key()\\n            .public_bytes(\\n                encoding=serialization.Encoding.PEM,\\n                format=serialization.PublicFormat.SubjectPublicKeyInfo,\\n            )\\n            .decode(\\\"utf-8\\\")\\n        )\\n    except Exception as e:\\n        msg = f\\\"Failed to derive public key from private key: {e}\\\"\\n        logger.error(msg)\\n        raise RSAKeyError(msg) from e\\n\\n\\ndef generate_rsa_key_pair() -> tuple[str, str]:\\n    \\\"\\\"\\\"Generate an RSA key pair for RS256 JWT signing.\\n\\n    Returns:\\n        tuple[str, str]: A tuple of (private_key_pem, public_key_pem) as strings.\\n    \\\"\\\"\\\"\\n    private_key = rsa.generate_private_key(\\n        public_exponent=65537,\\n        key_size=2048,\\n    )\\n\\n    private_key_pem = private_key.private_bytes(\\n        encoding=serialization.Encoding.PEM,\\n        format=serialization.PrivateFormat.PKCS8,\\n        encryption_algorithm=serialization.NoEncryption(),\\n    ).decode(\\\"utf-8\\\")\\n\\n    public_key_pem = (\\n        private_key.public_key()\\n        .public_bytes(\\n            encoding=serialization.Encoding.PEM,\\n            format=serialization.PublicFormat.SubjectPublicKeyInfo,\\n        )\\n        .decode(\\\"utf-8\\\")\\n    )\\n\\n    return private_key_pem, public_key_pem\\n\\n\\ndef _get_windows_process_user_sid():\\n    \\\"\\\"\\\"Return the SID of the user that owns the current process token.\\n\\n    Resolving the user by name (``LookupAccountName(\\\"\\\", GetUserName())``) is\\n    ambiguous: when the machine name equals the username, the bare name\\n    resolves to the machine-domain object (SidTypeDomain, no user RID), and a\\n    DACL granting only that SID locks the real user out of the file. The\\n    process token needs no name resolution and always yields the user SID.\\n    \\\"\\\"\\\"\\n    import win32api\\n    import win32con\\n    import win32security\\n\\n    token = win32security.OpenProcessToken(win32api.GetCurrentProcess(), win32con.TOKEN_QUERY)\\n    sid, _attributes = win32security.GetTokenInformation(token, win32security.TokenUser)\\n    return sid\\n\\n\\ndef set_secure_permissions(file_path: Path) -> None:\\n    if platform.system() in {\\\"Linux\\\", \\\"Darwin\\\"}:  # Unix/Linux/Mac\\n        file_path.chmod(0o600)\\n    elif platform.system() == \\\"Windows\\\":\\n        import win32con\\n        import win32security\\n\\n        user = _get_windows_process_user_sid()\\n        sd = win32security.GetFileSecurity(str(file_path), win32security.DACL_SECURITY_INFORMATION)\\n        dacl = win32security.ACL()\\n\\n        # Set the new DACL for the file: read and write access for the owner, no access for everyone else\\n        dacl.AddAccessAllowedAce(\\n            win32security.ACL_REVISION,\\n            win32con.GENERIC_READ | win32con.GENERIC_WRITE,\\n            user,\\n        )\\n        sd.SetSecurityDescriptorDacl(1, dacl, 0)\\n        win32security.SetFileSecurity(str(file_path), win32security.DACL_SECURITY_INFORMATION, sd)\\n    else:\\n        logger.error(\\\"Unsupported OS\\\")\\n\\n\\ndef write_secret_to_file(path: Path, value: str) -> None:\\n    path.write_text(value, encoding=\\\"utf-8\\\")\\n    try:\\n        set_secure_permissions(path)\\n    except Exception:  # noqa: BLE001\\n        logger.exception(\\\"Failed to set secure permissions on secret key\\\")\\n\\n\\ndef read_secret_from_file(path: Path) -> str:\\n    try:\\n        return path.read_text(encoding=\\\"utf-8\\\")\\n    except PermissionError:\\n        if platform.system() != \\\"Windows\\\":\\n            raise\\n        # Self-heal files whose DACL was written by a version affected by the\\n        # machine-name/username collision: the file owner keeps implicit\\n        # WRITE_DAC, so the ACL can be rewritten even with no read access.\\n        logger.warning(f\\\"Permission denied reading secret file at {path}; rewriting its ACL and retrying\\\")\\n        set_secure_permissions(path)\\n        return path.read_text(encoding=\\\"utf-8\\\")\\n\\n\\ndef write_public_key_to_file(path: Path, value: str) -> None:\\n    \\\"\\\"\\\"Write a public key to file with appropriate permissions (0o644).\\n\\n    Public keys can be readable by others but should only be writable by owner.\\n\\n    Args:\\n        path: The file path to write to.\\n        value: The public key content.\\n    \\\"\\\"\\\"\\n    path.write_text(value, encoding=\\\"utf-8\\\")\\n    try:\\n        if platform.system() in {\\\"Linux\\\", \\\"Darwin\\\"}:\\n            path.chmod(0o644)\\n    except Exception:  # noqa: BLE001\\n        logger.exception(\\\"Failed to set permissions on public key file\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/shared_component_cache/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"2203617319252c7c2ef2c521ddd62569543420feb96988b89e47b80155551fc6\",\"content\":\"\\\"\\\"\\\"Shared component cache service module.\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/shared_component_cache/factory.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d1865adf04b2402f6ea7b740e4fbbdde594d8c43468b3194598b669907f1fa8a\",\"content\":\"\\\"\\\"\\\"Factory for creating shared component cache service.\\\"\\\"\\\"\\n\\nfrom typing import TYPE_CHECKING\\n\\nfrom lfx.services.factory import ServiceFactory\\nfrom lfx.services.shared_component_cache.service import SharedComponentCacheService\\n\\nif TYPE_CHECKING:\\n    from lfx.services.base import Service\\n\\n\\nclass SharedComponentCacheServiceFactory(ServiceFactory):\\n    \\\"\\\"\\\"Factory for creating SharedComponentCacheService instances.\\\"\\\"\\\"\\n\\n    def __init__(self) -> None:\\n        \\\"\\\"\\\"Initialize the factory.\\\"\\\"\\\"\\n        super().__init__()\\n        self.service_class = SharedComponentCacheService\\n\\n    def create(self, **kwargs) -> \\\"Service\\\":\\n        \\\"\\\"\\\"Create a SharedComponentCacheService instance.\\n\\n        Args:\\n            **kwargs: Keyword arguments including expiration_time\\n\\n        Returns:\\n            SharedComponentCacheService instance\\n        \\\"\\\"\\\"\\n        expiration_time = kwargs.get(\\\"expiration_time\\\", 60 * 60)  # Default 1 hour\\n        return SharedComponentCacheService(expiration_time=expiration_time)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/shared_component_cache/service.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c176b7c1631c30ec27a5a136a53994eab2af1333d2bff75cd355633d5e644708\",\"content\":\"\\\"\\\"\\\"Shared component cache service implementation.\\\"\\\"\\\"\\n\\nfrom lfx.services.cache.service import ThreadingInMemoryCache\\n\\n\\nclass SharedComponentCacheService(ThreadingInMemoryCache):\\n    \\\"\\\"\\\"A caching service shared across components.\\\"\\\"\\\"\\n\\n    name = \\\"shared_component_cache_service\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/storage/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"48ee6412cb203f9f3ba0b78156050566492624c452b6e89979f0ad41e6934163\",\"content\":\"\\\"\\\"\\\"Storage services for lfx package.\\\"\\\"\\\"\\n\\nfrom lfx.services.storage.local import LocalStorageService\\n\\n__all__ = [\\\"LocalStorageService\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/storage/local.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"4be5a719debbc0c10d2949520df414fb0d30c5abe617cb4d5135bc300948c014\",\"content\":\"\\\"\\\"\\\"Local file-based storage service for lfx package.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING\\n\\nimport aiofiles\\n\\nfrom lfx.log.logger import logger\\nfrom lfx.services.base import Service\\nfrom lfx.services.storage.service import StorageService\\n\\nif TYPE_CHECKING:\\n    import anyio\\n    from langflow.services.session.service import SessionService\\n\\n    from lfx.services.settings.service import SettingsService\\n\\n# Constants for path parsing\\nEXPECTED_PATH_PARTS = 2  # Path format: \\\"flow_id/filename\\\"\\n\\n\\nclass LocalStorageService(StorageService, Service):\\n    \\\"\\\"\\\"A service class for handling local file storage operations.\\\"\\\"\\\"\\n\\n    def __init__(\\n        self,\\n        session_service: SessionService,\\n        settings_service: SettingsService,\\n    ) -> None:\\n        \\\"\\\"\\\"Initialize the local storage service.\\n\\n        Args:\\n            session_service: Session service instance\\n            settings_service: Settings service instance containing configuration\\n        \\\"\\\"\\\"\\n        # Initialize base class with services\\n        super().__init__(session_service, settings_service)\\n        # Base class already sets self.data_dir as anyio.Path from settings_service.settings.config_dir\\n\\n    async def _validated_path(self, flow_id: str, file_name: str) -> anyio.Path:\\n        \\\"\\\"\\\"Return a path inside the flow directory or raise if traversal is attempted.\\n\\n        Centralizes the path-containment check used across every file operation so\\n        a single bug cannot re-introduce the traversal issue on a subset of methods.\\n        Both flow_id and file_name must be free of separators / traversal so a\\n        caller-supplied flow_id like \\\"/etc\\\" cannot collapse data_dir via Path\\n        joining (absolute segment resets the join).\\n        \\\"\\\"\\\"\\n        if not isinstance(file_name, str) or \\\"/\\\" in file_name or \\\"\\\\\\\\\\\" in file_name or \\\"..\\\" in file_name:\\n            await logger.aerror(\\n                f\\\"Invalid file_name contains path separators or traversal sequences: flow_id='{flow_id}'\\\"\\n            )\\n            msg = \\\"Invalid file name: contains path separators\\\"\\n            raise ValueError(msg)\\n\\n        if (\\n            not isinstance(flow_id, str)\\n            or not flow_id\\n            or \\\"/\\\" in flow_id\\n            or \\\"\\\\\\\\\\\" in flow_id\\n            or \\\"..\\\" in flow_id\\n            or \\\"\\\\x00\\\" in flow_id\\n        ):\\n            await logger.aerror(\\\"Invalid flow_id contains path separators or traversal sequences\\\")\\n            msg = \\\"Invalid flow_id: contains path separators\\\"\\n            raise ValueError(msg)\\n\\n        folder_path = self.data_dir / flow_id\\n        file_path = folder_path / file_name\\n\\n        try:\\n            resolved_data_dir = await self.data_dir.resolve()\\n            resolved_file = await file_path.resolve()\\n            # Containment check is anchored at data_dir, not folder_path: an\\n            # attacker-controlled flow_id segment must not be allowed to define\\n            # the boundary it is then compared against.\\n            if not resolved_file.is_relative_to(resolved_data_dir):\\n                await logger.aerror(\\n                    f\\\"Path traversal attempt detected for flow_id='{flow_id}'. \\\"\\n                    \\\"File path would escape data directory boundary.\\\"\\n                )\\n                msg = \\\"Invalid file path: path traversal detected\\\"\\n                raise ValueError(msg)\\n        except ValueError:\\n            raise\\n        except AttributeError:\\n            resolved_data_dir_str = str(await self.data_dir.resolve())\\n            resolved_file_str = str(await file_path.resolve())\\n            if not resolved_file_str.startswith(resolved_data_dir_str):\\n                await logger.aerror(f\\\"Path traversal attempt detected for flow_id='{flow_id}' (fallback check)\\\")\\n                msg = \\\"Invalid file path: path traversal detected\\\"\\n                raise ValueError(msg) from None\\n        except Exception as e:\\n            await logger.aerror(f\\\"Error validating file path for flow_id='{flow_id}': {type(e).__name__}\\\")\\n            msg = \\\"Invalid file path\\\"\\n            raise ValueError(msg) from e\\n\\n        return file_path\\n\\n    def resolve_component_path(self, logical_path: str) -> str:\\n        \\\"\\\"\\\"Convert logical path to absolute filesystem path for local storage.\\n\\n        Args:\\n            logical_path: Path in format \\\"flow_id/filename\\\"\\n        Returns:\\n            str: Absolute filesystem path\\n        \\\"\\\"\\\"\\n        # Split the logical path into flow_id and filename\\n        parts = logical_path.split(\\\"/\\\", 1)\\n        if len(parts) != EXPECTED_PATH_PARTS:\\n            # Handle edge case - return as-is if format is unexpected\\n            return logical_path\\n\\n        flow_id, file_name = parts\\n        return self.build_full_path(flow_id, file_name)\\n\\n    async def teardown(self) -> None:\\n        \\\"\\\"\\\"Teardown the storage service.\\\"\\\"\\\"\\n        # No cleanup needed for local storage\\n\\n    def build_full_path(self, flow_id: str, file_name: str) -> str:\\n        \\\"\\\"\\\"Build the full path of a file in the local storage.\\\"\\\"\\\"\\n        return str(self.data_dir / flow_id / file_name)\\n\\n    def parse_file_path(self, full_path: str) -> tuple[str, str]:\\n        r\\\"\\\"\\\"Parse a full local storage path to extract flow_id and file_name.\\n\\n        Args:\\n            full_path: Filesystem path, may or may not include data_dir\\n                e.g., \\\"/data/user_123/image.png\\\" or \\\"user_123/image.png\\\". On Windows the\\n                separators may be backslashes (\\\"\\\\\\\\\\\"). This method handles both.\\n\\n        Returns:\\n            tuple[str, str]: A tuple of (flow_id, file_name)\\n\\n        Examples:\\n            >>> parse_file_path(\\\"/data/user_123/image.png\\\")  # with data_dir\\n            (\\\"user_123\\\", \\\"image.png\\\")\\n            >>> parse_file_path(\\\"user_123/image.png\\\")  # without data_dir\\n            (\\\"user_123\\\", \\\"image.png\\\")\\n        \\\"\\\"\\\"\\n        data_dir_str = str(self.data_dir)\\n\\n        # Remove data_dir if present (but don't require it)\\n        path_without_prefix = full_path\\n        if full_path.startswith(data_dir_str):\\n            # Strip both POSIX and Windows separators\\n            path_without_prefix = full_path[len(data_dir_str) :].lstrip(\\\"/\\\").lstrip(\\\"\\\\\\\\\\\")\\n\\n        # Normalize separators so downstream logic is platform-agnostic\\n        normalized_path = path_without_prefix.replace(\\\"\\\\\\\\\\\", \\\"/\\\")\\n\\n        # Split from the right to get the filename; everything before the last\\n        # \\\"/\\\" is the flow_id\\n        if \\\"/\\\" not in normalized_path:\\n            return \\\"\\\", normalized_path\\n\\n        # Use rsplit to split from the right, limiting to 1 split\\n        flow_id, file_name = normalized_path.rsplit(\\\"/\\\", 1)\\n        return flow_id, file_name\\n\\n    async def save_file(self, flow_id: str, file_name: str, data: bytes, *, append: bool = False) -> None:\\n        \\\"\\\"\\\"Save a file in the local storage.\\n\\n        Args:\\n            flow_id: The identifier for the flow.\\n            file_name: The name of the file to be saved.\\n            data: The byte content of the file.\\n            append: If True, append to existing file; if False, overwrite.\\n\\n        Raises:\\n            FileNotFoundError: If the specified flow does not exist.\\n            IsADirectoryError: If the file name is a directory.\\n            PermissionError: If there is no permission to write the file.\\n            ValueError: If path traversal is detected (security violation).\\n        \\\"\\\"\\\"\\n        # SECURITY: Validate BEFORE creating any directories to prevent race conditions\\n        # and path traversal. Shared with all read/write/delete entry points so the\\n        # storage boundary cannot be bypassed by any single call site.\\n        file_path = await self._validated_path(flow_id, file_name)\\n        folder_path = self.data_dir / flow_id\\n        await folder_path.mkdir(parents=True, exist_ok=True)\\n\\n        try:\\n            mode = \\\"ab\\\" if append else \\\"wb\\\"\\n            async with aiofiles.open(str(file_path), mode) as f:\\n                await f.write(data)\\n            action = \\\"appended to\\\" if append else \\\"saved\\\"\\n            await logger.ainfo(f\\\"File {file_name} {action} successfully in flow {flow_id}.\\\")\\n        except Exception:\\n            logger.exception(f\\\"Error saving file {file_name} in flow {flow_id}\\\")\\n            raise\\n\\n    async def get_file(self, flow_id: str, file_name: str) -> bytes:\\n        \\\"\\\"\\\"Retrieve a file from the local storage.\\n\\n        Args:\\n            flow_id: The identifier for the flow.\\n            file_name: The name of the file to be retrieved.\\n\\n        Returns:\\n            The byte content of the file.\\n\\n        Raises:\\n            FileNotFoundError: If the file does not exist.\\n            ValueError: If path traversal is detected (security violation).\\n        \\\"\\\"\\\"\\n        file_path = await self._validated_path(flow_id, file_name)\\n        if not await file_path.exists():\\n            await logger.awarning(f\\\"File {file_name} not found in flow {flow_id}.\\\")\\n            msg = f\\\"File {file_name} not found in flow {flow_id}\\\"\\n            raise FileNotFoundError(msg)\\n\\n        async with aiofiles.open(str(file_path), \\\"rb\\\") as f:\\n            content = await f.read()\\n\\n        logger.debug(f\\\"File {file_name} retrieved successfully from flow {flow_id}.\\\")\\n        return content\\n\\n    async def list_files(self, flow_id: str) -> list[str]:\\n        \\\"\\\"\\\"List all files in a specific flow directory.\\n\\n        Args:\\n            flow_id: The identifier for the flow.\\n\\n        Returns:\\n            List of file names in the flow directory.\\n        \\\"\\\"\\\"\\n        if not isinstance(flow_id, str):\\n            flow_id = str(flow_id)\\n\\n        folder_path = self.data_dir / flow_id\\n        if not await folder_path.exists() or not await folder_path.is_dir():\\n            await logger.awarning(f\\\"Flow {flow_id} directory does not exist.\\\")\\n            return []\\n\\n        try:\\n            files = [p.name async for p in folder_path.iterdir() if await p.is_file()]\\n        except Exception:  # noqa: BLE001\\n            logger.exception(f\\\"Error listing files in flow {flow_id}\\\")\\n            return []\\n        else:\\n            await logger.ainfo(f\\\"Listed {len(files)} files in flow {flow_id}.\\\")\\n            return files\\n\\n    async def delete_file(self, flow_id: str, file_name: str) -> None:\\n        \\\"\\\"\\\"Delete a file from the local storage.\\n\\n        Args:\\n            flow_id: The identifier for the flow.\\n            file_name: The name of the file to be deleted.\\n\\n        Raises:\\n            FileNotFoundError: If the file does not exist.\\n            ValueError: If path traversal is detected (security violation).\\n        \\\"\\\"\\\"\\n        file_path = await self._validated_path(flow_id, file_name)\\n        if await file_path.exists():\\n            await file_path.unlink()\\n            await logger.ainfo(f\\\"File {file_name} deleted successfully from flow {flow_id}.\\\")\\n        else:\\n            await logger.awarning(f\\\"Attempted to delete non-existent file {file_name} in flow {flow_id}.\\\")\\n\\n    async def get_file_size(self, flow_id: str, file_name: str) -> int:\\n        \\\"\\\"\\\"Get the size of a file in bytes.\\n\\n        Args:\\n            flow_id: The identifier for the flow.\\n            file_name: The name of the file.\\n\\n        Returns:\\n            The size of the file in bytes.\\n\\n        Raises:\\n            FileNotFoundError: If the file does not exist.\\n            ValueError: If path traversal is detected (security violation).\\n        \\\"\\\"\\\"\\n        file_path = await self._validated_path(flow_id, file_name)\\n        if not await file_path.exists():\\n            await logger.awarning(f\\\"File {file_name} not found in flow {flow_id}.\\\")\\n            msg = f\\\"File {file_name} not found in flow {flow_id}\\\"\\n            raise FileNotFoundError(msg)\\n\\n        try:\\n            file_size_stat = await file_path.stat()\\n        except Exception:\\n            logger.exception(f\\\"Error getting size of file {file_name} in flow {flow_id}\\\")\\n            raise\\n        else:\\n            return file_size_stat.st_size\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/storage/service.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1575819338eb5381eeb962ba367e8d2762f127dc51ce287b033a759869607fe4\",\"content\":\"from __future__ import annotations\\n\\nimport uuid\\nfrom abc import abstractmethod\\nfrom dataclasses import dataclass\\nfrom typing import TYPE_CHECKING\\n\\nimport anyio\\n\\nfrom lfx.services.base import Service\\n\\nif TYPE_CHECKING:\\n    from collections.abc import AsyncIterator\\n\\n    from lfx.services.settings.service import SettingsService\\n\\n\\n@dataclass(frozen=True)\\nclass StorageReadiness:\\n    \\\"\\\"\\\"Result of a storage backend readiness probe (used by production preflight).\\n\\n    Attributes:\\n        ok: True when the backend is usable (writable / reachable).\\n        backend: The configured backend identifier, e.g. \\\"local\\\" or \\\"s3\\\".\\n        detail: Human-readable one-line summary for display.\\n        reason: Machine-friendly failure reason when ``ok`` is False\\n            (e.g. \\\"no-credentials\\\", \\\"bucket-missing\\\", \\\"access-denied\\\",\\n            \\\"unreachable\\\", \\\"unwritable\\\"). Empty on success.\\n    \\\"\\\"\\\"\\n\\n    ok: bool\\n    backend: str\\n    detail: str\\n    reason: str = \\\"\\\"\\n\\n\\nclass StorageService(Service):\\n    \\\"\\\"\\\"Abstract base class for file storage services.\\n\\n    This class defines the interface for file storage operations that can be\\n    implemented by different backends (local filesystem, S3, etc.).\\n\\n    All file operations are namespaced by flow_id to isolate files between\\n    different flows or users.\\n    \\\"\\\"\\\"\\n\\n    name = \\\"storage_service\\\"\\n\\n    def __init__(self, session_service, settings_service: SettingsService):\\n        \\\"\\\"\\\"Initialize the storage service.\\n\\n        Args:\\n            session_service: The session service instance\\n            settings_service: The settings service instance containing configuration\\n        \\\"\\\"\\\"\\n        self.settings_service = settings_service\\n        self.session_service = session_service\\n        self.data_dir: anyio.Path = anyio.Path(settings_service.settings.config_dir)\\n        self.set_ready()\\n\\n    @abstractmethod\\n    def build_full_path(self, flow_id: str, file_name: str) -> str:\\n        \\\"\\\"\\\"Build the full path/key for a file.\\n\\n        Args:\\n            flow_id: The flow/user identifier for namespacing\\n            file_name: The name of the file\\n\\n        Returns:\\n            str: The full path or key for the file\\n        \\\"\\\"\\\"\\n        raise NotImplementedError\\n\\n    @abstractmethod\\n    def parse_file_path(self, full_path: str) -> tuple[str, str]:\\n        \\\"\\\"\\\"Parse a full storage path to extract flow_id and file_name.\\n\\n        This reverses the build_full_path operation.\\n\\n        Args:\\n            full_path: Full path as returned by build_full_path\\n\\n        Returns:\\n            tuple[str, str]: A tuple of (flow_id, file_name)\\n\\n        Raises:\\n            ValueError: If the path format is invalid or doesn't match expected structure\\n        \\\"\\\"\\\"\\n        raise NotImplementedError\\n\\n    @abstractmethod\\n    def resolve_component_path(self, logical_path: str) -> str:\\n        \\\"\\\"\\\"Convert a logical path to a format that components can use directly.\\n\\n        Logical paths are in the format \\\"{flow_id}/{filename}\\\" as stored in the database.\\n        This method converts them to a format appropriate for the storage backend:\\n        - Local storage: Absolute filesystem path (/data_dir/flow_id/filename)\\n        - S3 storage: Logical path as-is (flow_id/filename)\\n\\n        Components receive this resolved path and can use it without knowing the\\n        storage implementation details.\\n\\n        Args:\\n            logical_path: Path in the format \\\"flow_id/filename\\\"\\n\\n        Returns:\\n            str: A path that components can use directly\\n        \\\"\\\"\\\"\\n        raise NotImplementedError\\n\\n    def set_ready(self) -> None:\\n        \\\"\\\"\\\"Mark the service as ready.\\\"\\\"\\\"\\n        self._ready = True\\n\\n    @abstractmethod\\n    async def save_file(self, flow_id: str, file_name: str, data: bytes, *, append: bool = False) -> None:\\n        \\\"\\\"\\\"Save a file to storage.\\n\\n        Args:\\n            flow_id: The flow/user identifier for namespacing\\n            file_name: The name of the file to save\\n            data: The file content as bytes\\n            append: If True, append to existing file instead of overwriting.\\n\\n        Raises:\\n            Exception: If the file cannot be saved\\n        \\\"\\\"\\\"\\n        raise NotImplementedError\\n\\n    @abstractmethod\\n    async def get_file(self, flow_id: str, file_name: str) -> bytes:\\n        \\\"\\\"\\\"Retrieve a file from storage.\\n\\n        Args:\\n            flow_id: The flow/user identifier for namespacing\\n            file_name: The name of the file to retrieve\\n\\n        Returns:\\n            bytes: The file content\\n\\n        Raises:\\n            FileNotFoundError: If the file does not exist\\n        \\\"\\\"\\\"\\n        raise NotImplementedError\\n\\n    async def get_file_stream(self, flow_id: str, file_name: str, chunk_size: int = 8192) -> AsyncIterator[bytes]:\\n        \\\"\\\"\\\"Retrieve a file from storage as a stream.\\n\\n        Default implementation loads the entire file and yields it in chunks.\\n        Subclasses can override this for more efficient streaming.\\n\\n        Args:\\n            flow_id: The flow/user identifier for namespacing\\n            file_name: The name of the file to retrieve\\n            chunk_size: Size of chunks to yield (default: 8192 bytes)\\n\\n        Yields:\\n            bytes: Chunks of the file content\\n\\n        Raises:\\n            FileNotFoundError: If the file does not exist\\n        \\\"\\\"\\\"\\n        # Default implementation - subclasses can override for true streaming\\n        content = await self.get_file(flow_id, file_name)\\n        for i in range(0, len(content), chunk_size):\\n            yield content[i : i + chunk_size]\\n\\n    @abstractmethod\\n    async def list_files(self, flow_id: str) -> list[str]:\\n        \\\"\\\"\\\"List all files in a flow's storage namespace.\\n\\n        Args:\\n            flow_id: The flow/user identifier for namespacing\\n\\n        Returns:\\n            list[str]: List of file names in the namespace\\n\\n        Raises:\\n            FileNotFoundError: If the namespace directory does not exist\\n        \\\"\\\"\\\"\\n        raise NotImplementedError\\n\\n    @abstractmethod\\n    async def get_file_size(self, flow_id: str, file_name: str) -> int:\\n        \\\"\\\"\\\"Get the size of a file in bytes.\\n\\n        Args:\\n            flow_id: The flow/user identifier for namespacing\\n            file_name: The name of the file\\n\\n        Returns:\\n            int: Size of the file in bytes\\n\\n        Raises:\\n            FileNotFoundError: If the file does not exist\\n        \\\"\\\"\\\"\\n        raise NotImplementedError\\n\\n    @abstractmethod\\n    async def delete_file(self, flow_id: str, file_name: str) -> None:\\n        \\\"\\\"\\\"Delete a file from storage.\\n\\n        Args:\\n            flow_id: The flow/user identifier for namespacing\\n            file_name: The name of the file to delete\\n\\n        Note:\\n            Should not raise an error if the file doesn't exist\\n        \\\"\\\"\\\"\\n        raise NotImplementedError\\n\\n    async def check_readiness(self) -> StorageReadiness:\\n        \\\"\\\"\\\"Probe whether this storage backend is usable, for production preflight.\\n\\n        The default implementation targets a local filesystem ``data_dir``: it\\n        creates the directory if needed, writes and deletes a sentinel file to\\n        prove the backend is writable. Object-store backends (e.g. S3) override\\n        this with a credentials + reachability probe.\\n\\n        Returns:\\n            StorageReadiness: ``ok=True`` when the backend is usable, otherwise a\\n            typed failure with a human-readable ``detail`` and a machine ``reason``.\\n        \\\"\\\"\\\"\\n        backend = getattr(self.settings_service.settings, \\\"storage_type\\\", \\\"local\\\")\\n        try:\\n            await self.data_dir.mkdir(parents=True, exist_ok=True)\\n            sentinel = self.data_dir / f\\\".langflow-preflight-{uuid.uuid4().hex}\\\"\\n            await sentinel.write_bytes(b\\\"ok\\\")\\n            await sentinel.unlink()\\n        except OSError as exc:\\n            reason = getattr(exc, \\\"strerror\\\", None) or str(exc)\\n            return StorageReadiness(\\n                ok=False,\\n                backend=backend,\\n                detail=f\\\"{self.data_dir} is not writable ({reason})\\\",\\n                reason=\\\"unwritable\\\",\\n            )\\n        return StorageReadiness(ok=True, backend=backend, detail=f\\\"writable ({self.data_dir})\\\")\\n\\n    async def teardown(self) -> None:\\n        \\\"\\\"\\\"Perform cleanup operations when the service is being shut down.\\n\\n        Subclasses can override this to clean up any resources (connections, etc.).\\n        Default implementation is a no-op.\\n        \\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/telemetry/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0594c33152707618156c609479b37a91081408268a0f222992d8520b1ed64076\",\"content\":\"\\\"\\\"\\\"Telemetry service for lfx package.\\\"\\\"\\\"\\n\\nfrom .schema import MCPToolPayload\\nfrom .service import TelemetryService\\n\\n__all__ = [\\\"MCPToolPayload\\\", \\\"TelemetryService\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/telemetry/base.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5d61b88cd85b1539feb61fe23c494045120058b27446961c65b6e37d06ddc21d\",\"content\":\"\\\"\\\"\\\"Abstract base class for telemetry services.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom abc import ABC, abstractmethod\\nfrom typing import TYPE_CHECKING\\n\\nfrom lfx.services.base import Service\\n\\nif TYPE_CHECKING:\\n    from pydantic import BaseModel\\n\\n\\nclass BaseTelemetryService(Service, ABC):\\n    \\\"\\\"\\\"Abstract base class for telemetry services.\\n\\n    Defines the minimal interface that all telemetry service implementations\\n    must provide, whether minimal (LFX) or full-featured (Langflow).\\n    \\\"\\\"\\\"\\n\\n    @abstractmethod\\n    def __init__(self):\\n        \\\"\\\"\\\"Initialize the telemetry service.\\\"\\\"\\\"\\n        super().__init__()\\n\\n    @abstractmethod\\n    async def send_telemetry_data(self, payload: BaseModel, path: str | None = None) -> None:\\n        \\\"\\\"\\\"Send telemetry data to the telemetry backend.\\n\\n        Args:\\n            payload: The telemetry payload to send\\n            path: Optional path to append to the base URL\\n        \\\"\\\"\\\"\\n\\n    @abstractmethod\\n    async def log_package_run(self, payload: BaseModel) -> None:\\n        \\\"\\\"\\\"Log a package run event.\\n\\n        Args:\\n            payload: Run payload containing run information\\n        \\\"\\\"\\\"\\n\\n    @abstractmethod\\n    async def log_package_shutdown(self) -> None:\\n        \\\"\\\"\\\"Log a package shutdown event.\\\"\\\"\\\"\\n\\n    @abstractmethod\\n    async def log_package_version(self) -> None:\\n        \\\"\\\"\\\"Log the package version information.\\\"\\\"\\\"\\n\\n    @abstractmethod\\n    async def log_package_playground(self, payload: BaseModel) -> None:\\n        \\\"\\\"\\\"Log a playground interaction event.\\n\\n        Args:\\n            payload: Playground payload containing interaction information\\n        \\\"\\\"\\\"\\n\\n    @abstractmethod\\n    async def log_package_component(self, payload: BaseModel) -> None:\\n        \\\"\\\"\\\"Log a component usage event.\\n\\n        Args:\\n            payload: Component payload containing component information\\n        \\\"\\\"\\\"\\n\\n    @abstractmethod\\n    async def log_exception(self, exc: Exception, context: str) -> None:\\n        \\\"\\\"\\\"Log an unhandled exception.\\n\\n        Args:\\n            exc: The exception that occurred\\n            context: Context where exception occurred\\n        \\\"\\\"\\\"\\n\\n    @abstractmethod\\n    def start(self) -> None:\\n        \\\"\\\"\\\"Start the telemetry service.\\\"\\\"\\\"\\n\\n    @abstractmethod\\n    async def stop(self) -> None:\\n        \\\"\\\"\\\"Stop the telemetry service.\\\"\\\"\\\"\\n\\n    @abstractmethod\\n    async def flush(self) -> None:\\n        \\\"\\\"\\\"Flush any pending telemetry data.\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/telemetry/schema.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"91fab45d1fc57fd9d3c8f91cb2959c59b78b3073913f1e8f393336929e962796\",\"content\":\"\\\"\\\"\\\"Telemetry payload schemas.\\n\\nAll payloads are sent as URL query parameters via GET requests (Scarf pixel\\ntracking), so keep fields small. Max URL size is ~2KB.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom pydantic import BaseModel, Field\\n\\nMAX_TELEMETRY_URL_SIZE = 2048\\n\\n\\nclass BasePayload(BaseModel):\\n    client_type: str | None = Field(default=None, serialization_alias=\\\"clientType\\\")\\n\\n\\nclass RunPayload(BasePayload):\\n    run_is_webhook: bool = Field(default=False, serialization_alias=\\\"runIsWebhook\\\")\\n    run_seconds: int = Field(serialization_alias=\\\"runSeconds\\\")\\n    run_success: bool = Field(serialization_alias=\\\"runSuccess\\\")\\n    run_error_message: str | None = Field(None, serialization_alias=\\\"runErrorMessage\\\")\\n\\n\\nclass ShutdownPayload(BasePayload):\\n    time_running: int = Field(serialization_alias=\\\"timeRunning\\\")\\n\\n\\nclass VersionPayload(BasePayload):\\n    package: str\\n    version: str\\n    platform: str\\n    python: str\\n    arch: str\\n\\n\\nclass ComponentPayload(BasePayload):\\n    component_name: str = Field(serialization_alias=\\\"componentName\\\")\\n    component_seconds: int = Field(serialization_alias=\\\"componentSeconds\\\")\\n    component_success: bool = Field(serialization_alias=\\\"componentSuccess\\\")\\n    component_error_message: str | None = Field(None, serialization_alias=\\\"componentErrorMessage\\\")\\n\\n\\nclass ExceptionPayload(BasePayload):\\n    exception_type: str = Field(serialization_alias=\\\"exceptionType\\\")\\n    exception_message: str = Field(serialization_alias=\\\"exceptionMessage\\\")\\n    exception_context: str = Field(serialization_alias=\\\"exceptionContext\\\")\\n    stack_trace_hash: str | None = Field(None, serialization_alias=\\\"stackTraceHash\\\")\\n\\n\\nclass MCPToolPayload(BasePayload):\\n    \\\"\\\"\\\"Tracks an MCP tool invocation. Kept small for URL query params.\\\"\\\"\\\"\\n\\n    tool: str\\n    success: bool\\n    ms: int = Field(0, serialization_alias=\\\"ms\\\")\\n    error: str | None = None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/telemetry/service.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e0e9bd4a628edcbe58c334037b1ad99ff4e1e929adacc8f11a70f5aae74caf74\",\"content\":\"\\\"\\\"\\\"Telemetry service for lfx.\\n\\nSends lightweight analytics via GET requests to a Scarf pixel endpoint.\\nAll data goes through an async queue so tool calls are never blocked.\\nRespects DO_NOT_TRACK env var and the settings flag.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nimport contextlib\\nimport hashlib\\nimport os\\nimport platform\\nimport traceback\\nfrom datetime import datetime, timezone\\nfrom typing import TYPE_CHECKING\\n\\nimport httpx\\n\\nfrom lfx.log.logger import logger\\nfrom lfx.services.telemetry.base import BaseTelemetryService\\nfrom lfx.services.telemetry.schema import (\\n    ExceptionPayload,\\n    MCPToolPayload,\\n    ShutdownPayload,\\n    VersionPayload,\\n)\\n\\nif TYPE_CHECKING:\\n    from pydantic import BaseModel\\n\\n_DEFAULT_BASE_URL = \\\"https://langflow.gateway.scarf.sh\\\"\\n\\n\\nclass TelemetryService(BaseTelemetryService):\\n    \\\"\\\"\\\"Async telemetry service that sends events to Scarf via query params.\\\"\\\"\\\"\\n\\n    def __init__(\\n        self,\\n        *,\\n        base_url: str | None = None,\\n        do_not_track: bool | None = None,\\n    ):\\n        super().__init__()\\n        self.base_url = base_url or os.environ.get(\\\"LANGFLOW_TELEMETRY_BASE_URL\\\", _DEFAULT_BASE_URL)\\n\\n        if do_not_track is None:\\n            do_not_track = os.environ.get(\\\"DO_NOT_TRACK\\\", \\\"false\\\").lower() in {\\\"1\\\", \\\"true\\\"}\\n        self.do_not_track = do_not_track\\n\\n        self._queue: asyncio.Queue[tuple] = asyncio.Queue()\\n        self._client: httpx.AsyncClient | None = None\\n        self._worker_task: asyncio.Task | None = None\\n        self._running = False\\n        self._stopping = False\\n        self._start_time = datetime.now(timezone.utc)\\n\\n        self._common_fields = {\\n            \\\"langflow_version\\\": self._get_version(),\\n            \\\"platform\\\": \\\"mcp\\\",\\n            \\\"os\\\": platform.system().lower(),\\n        }\\n        self.set_ready()\\n\\n    @property\\n    def name(self) -> str:\\n        return \\\"telemetry_service\\\"\\n\\n    # ------------------------------------------------------------------\\n    # Lifecycle\\n    # ------------------------------------------------------------------\\n\\n    def start(self) -> None:\\n        if self._running or self.do_not_track:\\n            return\\n        self._running = True\\n        self._start_time = datetime.now(timezone.utc)\\n        self._client = httpx.AsyncClient(timeout=10.0)\\n        self._worker_task = asyncio.create_task(self._worker())\\n\\n    async def stop(self) -> None:\\n        if not self._running or self._stopping:\\n            return\\n        self._stopping = True\\n        await self.flush()\\n        self._running = False\\n        if self._worker_task:\\n            self._worker_task.cancel()\\n            with contextlib.suppress(asyncio.CancelledError):\\n                await self._worker_task\\n        if self._client:\\n            await self._client.aclose()\\n            self._client = None\\n        self._stopping = False\\n\\n    async def flush(self) -> None:\\n        if self.do_not_track:\\n            return\\n        with contextlib.suppress(Exception):\\n            await asyncio.wait_for(self._queue.join(), timeout=5.0)\\n\\n    async def teardown(self) -> None:\\n        await self.stop()\\n\\n    # ------------------------------------------------------------------\\n    # Core send\\n    # ------------------------------------------------------------------\\n\\n    async def send_telemetry_data(self, payload: BaseModel, path: str | None = None) -> None:\\n        if self.do_not_track or self._client is None:\\n            return\\n        try:\\n            url = f\\\"{self.base_url}/{path}\\\" if path else self.base_url\\n            params = payload.model_dump(by_alias=True, exclude_none=True, exclude_unset=True)\\n            if not isinstance(payload, VersionPayload):\\n                params.update(self._common_fields)\\n            params.setdefault(\\\"timestamp\\\", datetime.now(timezone.utc).isoformat())\\n\\n            resp = await self._client.get(url, params=params)\\n            if resp.status_code != httpx.codes.OK:\\n                await logger.adebug(f\\\"Telemetry response {resp.status_code}\\\")\\n        except Exception:  # noqa: BLE001\\n            await logger.adebug(\\\"Telemetry send failed\\\")\\n\\n    # ------------------------------------------------------------------\\n    # Public log methods\\n    # ------------------------------------------------------------------\\n\\n    async def log_package_run(self, payload: BaseModel) -> None:\\n        await self._enqueue(payload, \\\"run\\\")\\n\\n    async def log_package_shutdown(self) -> None:\\n        elapsed = int((datetime.now(timezone.utc) - self._start_time).total_seconds())\\n        await self._enqueue(ShutdownPayload(time_running=elapsed), \\\"shutdown\\\")\\n\\n    async def log_package_version(self) -> None:\\n        python_version = \\\".\\\".join(platform.python_version().split(\\\".\\\")[:2])\\n        payload = VersionPayload(\\n            package=\\\"lfx\\\",\\n            version=self._get_version(),\\n            platform=platform.platform(),\\n            python=python_version,\\n            arch=platform.machine(),\\n            client_type=\\\"mcp\\\",\\n        )\\n        await self._enqueue(payload, None)\\n\\n    async def log_package_playground(self, payload: BaseModel) -> None:\\n        await self._enqueue(payload, \\\"playground\\\")\\n\\n    async def log_package_component(self, payload: BaseModel) -> None:\\n        await self._enqueue(payload, \\\"component\\\")\\n\\n    async def log_exception(self, exc: Exception, context: str) -> None:\\n        stack = \\\"\\\".join(traceback.format_exception(type(exc), exc, exc.__traceback__))\\n        payload = ExceptionPayload(\\n            exception_type=exc.__class__.__name__,\\n            exception_message=str(exc)[:500],\\n            exception_context=context,\\n            stack_trace_hash=hashlib.sha256(stack.encode()).hexdigest()[:16],\\n        )\\n        await self._enqueue(payload, \\\"exception\\\")\\n\\n    async def log_mcp_tool(self, payload: MCPToolPayload) -> None:\\n        await self._enqueue(payload, \\\"mcp_tool\\\")\\n\\n    # ------------------------------------------------------------------\\n    # Internals\\n    # ------------------------------------------------------------------\\n\\n    async def _enqueue(self, payload: BaseModel, path: str | None) -> None:\\n        if self.do_not_track or self._stopping:\\n            return\\n        await self._queue.put((payload, path))\\n\\n    async def _worker(self) -> None:\\n        while self._running:\\n            got_item = False\\n            try:\\n                payload, path = await self._queue.get()\\n                got_item = True\\n                await self.send_telemetry_data(payload, path)\\n            except asyncio.CancelledError:\\n                break\\n            except Exception:  # noqa: BLE001\\n                with contextlib.suppress(Exception):\\n                    await logger.adebug(\\\"Telemetry worker error\\\")\\n            finally:\\n                if got_item:\\n                    self._queue.task_done()\\n\\n    @staticmethod\\n    def _get_version() -> str:\\n        try:\\n            from importlib.metadata import version\\n\\n            return version(\\\"lfx\\\")\\n        except Exception:  # noqa: BLE001\\n            return \\\"unknown\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/tracing/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0b4239be46fbeb47f4423203aed756b0fbb7ca071ef91b0d4846b4e99a4b3077\",\"content\":\"\\\"\\\"\\\"Tracing service for lfx package - minimal implementation.\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/tracing/base.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f8f884afc8e19b2c2e087ac1055f9b677b4ecec77c769a966c160c6587bb4d1c\",\"content\":\"\\\"\\\"\\\"Abstract base class for tracing services.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom abc import ABC, abstractmethod\\nfrom contextlib import asynccontextmanager\\nfrom typing import TYPE_CHECKING, Any\\n\\nfrom lfx.services.base import Service\\n\\nif TYPE_CHECKING:\\n    from uuid import UUID\\n\\n    from langchain_core.callbacks.base import BaseCallbackHandler\\n\\n    from lfx.custom.custom_component.component import Component\\n\\n\\nclass BaseTracingService(Service, ABC):\\n    \\\"\\\"\\\"Abstract base class for tracing services.\\n\\n    Defines the minimal interface that all tracing service implementations\\n    must provide, whether minimal (LFX) or full-featured (Langflow).\\n    \\\"\\\"\\\"\\n\\n    @abstractmethod\\n    def __init__(self):\\n        \\\"\\\"\\\"Initialize the tracing service.\\\"\\\"\\\"\\n        super().__init__()\\n\\n    @abstractmethod\\n    async def start_tracers(\\n        self,\\n        run_id: UUID,\\n        run_name: str,\\n        user_id: str | None,\\n        session_id: str | None,\\n        project_name: str | None = None,\\n        flow_id: str | None = None,\\n        tracing_user_id: str | None = None,\\n    ) -> None:\\n        \\\"\\\"\\\"Start tracers for a graph run.\\n\\n        Args:\\n            run_id: Unique identifier for the run\\n            run_name: Name of the run\\n            user_id: Authenticated Langflow user identifier (optional)\\n            session_id: Session identifier (optional)\\n            project_name: Project name (optional)\\n            flow_id: Flow identifier (optional)\\n            tracing_user_id: Optional caller-supplied label forwarded to tracing\\n                providers. Does not change ``trace.userId`` (which stays as the\\n                auth ``user_id``); each provider decides how to surface it (e.g.\\n                LangFuseTracer stamps it under ``langflow.tracing_user_id`` in\\n                trace metadata).\\n        \\\"\\\"\\\"\\n\\n    @abstractmethod\\n    async def end_tracers(self, outputs: dict, error: Exception | None = None) -> None:\\n        \\\"\\\"\\\"End tracers for a graph run.\\n\\n        Args:\\n            outputs: Output data from the run\\n            error: Exception if run failed (optional)\\n        \\\"\\\"\\\"\\n\\n    @abstractmethod\\n    @asynccontextmanager\\n    async def trace_component(\\n        self,\\n        component: Component,\\n        trace_name: str,\\n        inputs: dict[str, Any],\\n        metadata: dict[str, Any] | None = None,\\n    ):\\n        \\\"\\\"\\\"Context manager for tracing a component execution.\\n\\n        Args:\\n            component: The component being traced\\n            trace_name: Name for the trace\\n            inputs: Input data to the component\\n            metadata: Additional metadata (optional)\\n\\n        Yields:\\n            Self for method chaining\\n        \\\"\\\"\\\"\\n\\n    @abstractmethod\\n    def add_log(self, trace_name: str, log: Any) -> None:\\n        \\\"\\\"\\\"Add a log entry to the current trace.\\n\\n        Args:\\n            trace_name: Name of the trace\\n            log: Log data to add\\n        \\\"\\\"\\\"\\n\\n    @abstractmethod\\n    def set_outputs(\\n        self,\\n        trace_name: str,\\n        outputs: dict[str, Any],\\n        output_metadata: dict[str, Any] | None = None,\\n    ) -> None:\\n        \\\"\\\"\\\"Set outputs for the current trace.\\n\\n        Args:\\n            trace_name: Name of the trace\\n            outputs: Output data\\n            output_metadata: Additional output metadata (optional)\\n        \\\"\\\"\\\"\\n\\n    @abstractmethod\\n    def get_langchain_callbacks(self) -> list[BaseCallbackHandler]:\\n        \\\"\\\"\\\"Get LangChain callback handlers for tracing.\\n\\n        Returns:\\n            List of callback handlers\\n        \\\"\\\"\\\"\\n\\n    @property\\n    @abstractmethod\\n    def project_name(self) -> str | None:\\n        \\\"\\\"\\\"Get the current project name.\\n\\n        Returns:\\n            Project name or None if not set\\n        \\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/tracing/service.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"2695738b97b5c2914b0df19ff0bad0193197c9340f3fe66e402fa2b759aa4d0d\",\"content\":\"\\\"\\\"\\\"Lightweight tracing service for LFX package.\\\"\\\"\\\"\\n\\n# ruff: noqa: ARG002\\nfrom __future__ import annotations\\n\\nfrom contextlib import asynccontextmanager\\nfrom typing import TYPE_CHECKING, Any\\n\\nfrom lfx.log.logger import logger\\nfrom lfx.services.tracing.base import BaseTracingService\\n\\nif TYPE_CHECKING:\\n    from uuid import UUID\\n\\n    from langchain_core.callbacks.base import BaseCallbackHandler\\n\\n    from lfx.custom.custom_component.component import Component\\n\\n\\nclass TracingService(BaseTracingService):\\n    \\\"\\\"\\\"Minimal tracing service implementation for LFX.\\n\\n    This is a lightweight implementation that logs trace events\\n    but does not integrate with external tracing services. For full\\n    tracing functionality (LangSmith, LangFuse, etc.), use the\\n    Langflow TracingService.\\n    \\\"\\\"\\\"\\n\\n    def __init__(self):\\n        \\\"\\\"\\\"Initialize the tracing service.\\\"\\\"\\\"\\n        super().__init__()\\n        self.deactivated = False\\n        self.set_ready()\\n\\n    @property\\n    def name(self) -> str:\\n        \\\"\\\"\\\"Service name identifier.\\n\\n        Returns:\\n            str: The service name.\\n        \\\"\\\"\\\"\\n        return \\\"tracing_service\\\"\\n\\n    async def start_tracers(\\n        self,\\n        run_id: UUID,\\n        run_name: str,\\n        user_id: str | None,\\n        session_id: str | None,\\n        project_name: str | None = None,\\n        flow_id: str | None = None,\\n        tracing_user_id: str | None = None,\\n    ) -> None:\\n        \\\"\\\"\\\"Start tracers (minimal implementation - just logs).\\n\\n        Args:\\n            run_id: Run identifier\\n            flow_id: Flow identifier\\n            run_name: Run name\\n            user_id: Authenticated Langflow user identifier\\n            session_id: Session identifier\\n            project_name: Project name\\n            tracing_user_id: Optional caller-supplied label forwarded to tracing providers\\n        \\\"\\\"\\\"\\n        logger.debug(f\\\"Trace started: {run_name}\\\")\\n\\n    async def end_tracers(self, outputs: dict, error: Exception | None = None) -> None:\\n        \\\"\\\"\\\"End tracers (minimal implementation - just logs).\\n\\n        Args:\\n            outputs: Output data\\n            error: Exception if any\\n        \\\"\\\"\\\"\\n        logger.debug(\\\"Trace ended\\\")\\n\\n    @asynccontextmanager\\n    async def trace_component(\\n        self,\\n        component: Component,\\n        trace_name: str,\\n        inputs: dict[str, Any],\\n        metadata: dict[str, Any] | None = None,\\n    ):\\n        \\\"\\\"\\\"Trace a component (minimal implementation).\\n\\n        Args:\\n            component: Component to trace\\n            trace_name: Trace name\\n            inputs: Input data\\n            metadata: Metadata\\n        \\\"\\\"\\\"\\n        logger.debug(f\\\"Tracing component: {trace_name}\\\")\\n        yield self\\n\\n    def add_log(self, trace_name: str, log: Any) -> None:\\n        \\\"\\\"\\\"Add a log entry (minimal implementation - just logs).\\n\\n        Args:\\n            trace_name: Trace name\\n            log: Log data\\n        \\\"\\\"\\\"\\n        logger.debug(f\\\"Trace log: {trace_name}\\\")\\n\\n    def set_outputs(\\n        self,\\n        trace_name: str,\\n        outputs: dict[str, Any],\\n        output_metadata: dict[str, Any] | None = None,\\n    ) -> None:\\n        \\\"\\\"\\\"Set outputs (minimal implementation - noop).\\n\\n        Args:\\n            trace_name: Trace name\\n            outputs: Output data\\n            output_metadata: Output metadata\\n        \\\"\\\"\\\"\\n        logger.debug(f\\\"Trace outputs set: {trace_name}\\\")\\n\\n    def get_langchain_callbacks(self) -> list[BaseCallbackHandler]:\\n        \\\"\\\"\\\"Get LangChain callbacks (minimal implementation - empty list).\\n\\n        Returns:\\n            Empty list (no callbacks in minimal implementation)\\n        \\\"\\\"\\\"\\n        return []\\n\\n    @property\\n    def project_name(self) -> str | None:\\n        \\\"\\\"\\\"Get project name (minimal implementation - returns None).\\n\\n        Returns:\\n            None\\n        \\\"\\\"\\\"\\n        return None\\n\\n    async def teardown(self) -> None:\\n        \\\"\\\"\\\"Teardown the tracing service.\\\"\\\"\\\"\\n        logger.debug(\\\"Tracing service teardown\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/transaction/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"50d02eceb98204d5d2c66037e81e5a90fe664e26a433ebc461ac7c3126b0206f\",\"content\":\"\\\"\\\"\\\"Transaction service module for lfx.\\\"\\\"\\\"\\n\\nfrom lfx.services.transaction.service import NoopTransactionService\\n\\n__all__ = [\\\"NoopTransactionService\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/transaction/service.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a8d906f62f2d59949275ae6c6080ebcf0926ad4679ecdb154555ba37edecf15c\",\"content\":\"\\\"\\\"\\\"Transaction service implementations for lfx.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import Any\\n\\nfrom lfx.services.interfaces import TransactionServiceProtocol\\n\\n\\nclass NoopTransactionService(TransactionServiceProtocol):\\n    \\\"\\\"\\\"No-operation transaction service for standalone lfx mode.\\n\\n    This service is used when lfx runs without a concrete transaction\\n    service implementation (e.g., without langflow). All operations\\n    are no-ops and transaction logging is disabled.\\n    \\\"\\\"\\\"\\n\\n    async def log_transaction(\\n        self,\\n        flow_id: str,\\n        vertex_id: str,\\n        inputs: dict[str, Any] | None,\\n        outputs: dict[str, Any] | None,\\n        status: str,\\n        target_id: str | None = None,\\n        error: str | None = None,\\n    ) -> None:\\n        \\\"\\\"\\\"No-op implementation of transaction logging.\\n\\n        In standalone mode, transactions are not persisted.\\n        \\\"\\\"\\\"\\n\\n    def is_enabled(self) -> bool:\\n        \\\"\\\"\\\"Transaction logging is disabled in noop mode.\\\"\\\"\\\"\\n        return False\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/variable/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7b947a60901112438c322356b6fee9f31eea1bd773a0077d8a575d991c2ea9d6\",\"content\":\"\\\"\\\"\\\"Variable service for lfx package.\\\"\\\"\\\"\\n\\nfrom .exceptions import VariableNotFoundError\\nfrom .service import VariableService\\n\\n__all__ = [\\\"VariableNotFoundError\\\", \\\"VariableService\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/variable/exceptions.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0c443c755d4cfe9c403414d450f07b9092ff394a6fb9b9dd55ad4adf93e8287e\",\"content\":\"\\\"\\\"\\\"Exceptions raised by variable services.\\\"\\\"\\\"\\n\\n\\nclass VariableNotFoundError(ValueError):\\n    \\\"\\\"\\\"Raised when a requested variable does not exist.\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/variable/request_scope.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"fcf54baa055674a14d16f413cee143f65921505a1fc2dfb3e223a98d7708a427\",\"content\":\"\\\"\\\"\\\"Request-scoped variables for lfx serve (and other in-process runners).\\n\\nTRM/WXO inject credentials via ``global_vars`` on ``POST /flows/{id}/run`` without\\nmutating process-wide ``os.environ``. This module holds the active request's flat\\nlookup table in a ContextVar so :class:`~lfx.services.variable.service.VariableService`\\ncan resolve the same names as the ``lfx run`` subprocess path.\\n\\nA second ContextVar mirrors ``graph.context['no_env_fallback']`` so the service can\\nhonor the same \\\"do not read ``os.environ``\\\" contract that ``load_from_env_vars``\\nenforces for ``load_from_db`` fields \u2014 keeping the two resolution paths consistent.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport contextvars\\nimport json\\n\\n_request_variables: contextvars.ContextVar[dict[str, str] | None] = contextvars.ContextVar(\\n    \\\"lfx_request_variables\\\",\\n    default=None,\\n)\\n_no_env_fallback: contextvars.ContextVar[bool] = contextvars.ContextVar(\\n    \\\"lfx_no_env_fallback\\\",\\n    default=False,\\n)\\n\\n\\ndef normalize_parsed_variables(parsed: dict) -> dict[str, str]:\\n    \\\"\\\"\\\"Flatten a parsed JSON variable map to ``str`` values.\\n\\n    Drops ``None`` (so a JSON ``null`` never becomes the truthy string \\\"None\\\" and\\n    masquerades as a credential) and serializes dict/list values as valid JSON\\n    (round-trippable via ``json.loads``) rather than a lossy Python repr. Scalars use ``str``.\\n    \\\"\\\"\\\"\\n    return {\\n        str(key): json.dumps(value) if isinstance(value, dict | list) else str(value)\\n        for key, value in parsed.items()\\n        if value is not None\\n    }\\n\\n\\ndef get_active_request_variables() -> dict[str, str] | None:\\n    \\\"\\\"\\\"Return the current request's variable map, if any.\\\"\\\"\\\"\\n    return _request_variables.get()\\n\\n\\ndef is_env_fallback_disabled() -> bool:\\n    \\\"\\\"\\\"Return whether the current request forbids falling back to ``os.environ``.\\\"\\\"\\\"\\n    return _no_env_fallback.get()\\n\\n\\ndef activate_no_env_fallback(*, disabled: bool) -> contextvars.Token[bool]:\\n    \\\"\\\"\\\"Bind the no-env-fallback flag for the current async task / thread.\\\"\\\"\\\"\\n    return _no_env_fallback.set(disabled)\\n\\n\\ndef reset_no_env_fallback(token: contextvars.Token[bool]) -> None:\\n    \\\"\\\"\\\"Restore the previous no-env-fallback flag.\\\"\\\"\\\"\\n    _no_env_fallback.reset(token)\\n\\n\\ndef activate_request_variables(variables: dict[str, str] | None) -> contextvars.Token[dict[str, str] | None]:\\n    \\\"\\\"\\\"Bind *variables* for the current async task / thread.\\n\\n    Pass ``None`` to mean \\\"no active scope\\\" \u2014 lookups then fall back to the\\n    ``LANGFLOW_REQUEST_VARIABLES`` env var. An empty ``{}`` is an *active* empty\\n    scope that suppresses that env fallback, so callers normalizing an empty\\n    result should pass ``... or None`` to preserve it.\\n    \\\"\\\"\\\"\\n    return _request_variables.set(variables)\\n\\n\\ndef reset_request_variables(token: contextvars.Token[dict[str, str] | None]) -> None:\\n    \\\"\\\"\\\"Restore the previous request scope.\\\"\\\"\\\"\\n    _request_variables.reset(token)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/services/variable/service.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"209afa68b10d838325ca6ec9da8b02ee072cc1ddfc99bf67bc095f7ad74fe63d\",\"content\":\"\\\"\\\"\\\"Minimal variable service for lfx package with in-memory storage and environment fallback.\\\"\\\"\\\"\\n\\nimport json\\nimport os\\n\\nfrom lfx.log.logger import logger\\nfrom lfx.services.base import Service\\nfrom lfx.services.variable.request_scope import (\\n    get_active_request_variables,\\n    is_env_fallback_disabled,\\n    normalize_parsed_variables,\\n)\\nfrom lfx.utils.env_var_security import safe_getenv\\n\\n\\nclass VariableService(Service):\\n    \\\"\\\"\\\"Minimal variable service with in-memory storage and environment fallback.\\n\\n    This is a lightweight implementation for LFX that maintains in-memory\\n    variables and falls back to environment variables for reads. No database storage.\\n\\n    \\\"\\\"\\\"\\n\\n    name = \\\"variable_service\\\"\\n\\n    def __init__(self) -> None:\\n        \\\"\\\"\\\"Initialize the variable service.\\\"\\\"\\\"\\n        super().__init__()\\n        self._variables: dict[str, str] = {}\\n        self.set_ready()\\n        logger.debug(\\\"Variable service initialized (env vars only)\\\")\\n\\n    @staticmethod\\n    def _normalize_global_var_key(name: str) -> str:\\n        return f\\\"x-langflow-global-var-{name.lower().replace('_', '-')}\\\"\\n\\n    @staticmethod\\n    def _get_request_variables() -> dict[str, str]:\\n        \\\"\\\"\\\"Request-scoped variables from serve ContextVar or LANGFLOW_REQUEST_VARIABLES env.\\\"\\\"\\\"\\n        active = get_active_request_variables()\\n        if active is not None:\\n            return active\\n\\n        # LANGFLOW_REQUEST_VARIABLES is a process-wide env var, so reading it is an\\n        # os.environ access. Honor the no-env-fallback contract and skip it when the\\n        # request disables env fallback, keeping the \\\"never reads os.environ\\\" guarantee.\\n        if is_env_fallback_disabled():\\n            return {}\\n\\n        raw = os.getenv(\\\"LANGFLOW_REQUEST_VARIABLES\\\")\\n        if not raw:\\n            return {}\\n        try:\\n            parsed = json.loads(raw)\\n        except json.JSONDecodeError:\\n            logger.debug(\\\"Invalid LANGFLOW_REQUEST_VARIABLES JSON; skipping request-scoped lookup\\\")\\n            return {}\\n        if not isinstance(parsed, dict):\\n            logger.debug(\\\"LANGFLOW_REQUEST_VARIABLES must be a JSON object; skipping request-scoped lookup\\\")\\n            return {}\\n        return normalize_parsed_variables(parsed)\\n\\n    async def get_variable(self, name: str, **kwargs) -> str | None:  # noqa: ARG002\\n        \\\"\\\"\\\"Get a variable value.\\n\\n        Resolution order (first match wins):\\n          1. In-memory cache (``set_variable``).\\n          2. Request-scoped exact name (serve ContextVar or ``LANGFLOW_REQUEST_VARIABLES``).\\n          3. Request-scoped ``x-langflow-global-var-*`` alias.\\n          4. Environment variable (exact name).\\n          5. Environment variable (``x-langflow-global-var-*`` alias).\\n\\n        Both request-scoped lookups (2, 3) run *before* any process-env fallback (4, 5),\\n        so a credential the caller supplies for this request \u2014 in either the exact-name\\n        or the ``x-langflow-global-var-*`` form \u2014 always beats a same-named variable left\\n        in the worker's environment, preventing one caller's request from running on an\\n        ambient process credential.\\n\\n        When the active request disables env fallback (``graph.context['no_env_fallback']``,\\n        propagated via the request scope), steps 4 and 5 are skipped so resolution\\n        never reads ``os.environ`` \u2014 matching ``load_from_env_vars`` for ``load_from_db``\\n        fields and keeping served flows isolated from process-wide credentials.\\n        \\\"\\\"\\\"\\n        if name in self._variables:\\n            return self._variables[name]\\n\\n        request_variables = self._get_request_variables()\\n        if name in request_variables:\\n            logger.debug(f\\\"Variable '{name}' loaded from request-scoped variables\\\")\\n            return request_variables[name]\\n\\n        global_alias = self._normalize_global_var_key(name)\\n        if global_alias in request_variables:\\n            logger.debug(f\\\"Variable '{name}' loaded from request-scoped alias '{global_alias}'\\\")\\n            return request_variables[global_alias]\\n\\n        if not is_env_fallback_disabled():\\n            # safe_getenv denies reserved names (LANGFLOW_SECRET_KEY, DATABASE_URL, ...) so a\\n            # tenant-supplied variable name cannot exfiltrate the server's own secrets via the\\n            # env fallback.\\n            value = safe_getenv(name)\\n            if value:\\n                logger.debug(f\\\"Variable '{name}' loaded from environment\\\")\\n                return value\\n\\n            value = safe_getenv(global_alias)\\n            if value:\\n                logger.debug(f\\\"Variable '{name}' loaded from global alias '{global_alias}'\\\")\\n                return value\\n\\n        return None\\n\\n    def set_variable(self, name: str, value: str, **kwargs) -> None:  # noqa: ARG002\\n        \\\"\\\"\\\"Set a variable value (in-memory only).\\\"\\\"\\\"\\n        self._variables[name] = value\\n        logger.debug(f\\\"Variable '{name}' set (in-memory only)\\\")\\n\\n    def delete_variable(self, name: str, **kwargs) -> None:  # noqa: ARG002\\n        \\\"\\\"\\\"Delete a variable (from in-memory cache only).\\\"\\\"\\\"\\n        if name in self._variables:\\n            del self._variables[name]\\n            logger.debug(f\\\"Variable '{name}' deleted (from in-memory cache)\\\")\\n\\n    def list_variables(self, **kwargs) -> list[str]:  # noqa: ARG002\\n        \\\"\\\"\\\"List all variables (in-memory only).\\\"\\\"\\\"\\n        return list(self._variables.keys())\\n\\n    async def teardown(self) -> None:\\n        \\\"\\\"\\\"Teardown the variable service.\\\"\\\"\\\"\\n        self._variables.clear()\\n        logger.debug(\\\"Variable service teardown\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/settings.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c27c78ce438b43c9af6a6a58b279ef555f46bc49d152e590a4a1526c54c2229e\",\"content\":\"\\\"\\\"\\\"Settings constants for lfx package.\\\"\\\"\\\"\\n\\nimport os\\n\\n# Development mode flag - can be overridden by environment variable\\nDEV = os.getenv(\\\"LANGFLOW_DEV\\\", \\\"false\\\").lower() == \\\"true\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/template/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"46a0e0f75d0293970bdeda21759212441fd1f3abe7d6a481a7aa3d10bcc08618\",\"content\":\"from lfx.template.field.base import Input, Output\\n\\n__all__ = [\\n    \\\"Input\\\",\\n    \\\"Output\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/template/field/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/template/field/base.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6435bcfbc9b3ed0ac6c90612fae856071215223070e3a55d4aa7f92eb8b61c49\",\"content\":\"from collections.abc import Callable\\nfrom enum import Enum\\nfrom typing import (\\n    Any,\\n    get_origin,\\n)\\n\\nfrom pydantic import (\\n    BaseModel,\\n    ConfigDict,\\n    Field,\\n    field_serializer,\\n    field_validator,\\n    model_serializer,\\n    model_validator,\\n)\\n\\nfrom lfx.field_typing import Text\\nfrom lfx.field_typing.range_spec import RangeSpec\\nfrom lfx.helpers.custom import format_type\\nfrom lfx.schema.data import Data\\nfrom lfx.type_extraction import post_process_type\\n\\n\\nclass UndefinedType(Enum):\\n    undefined = \\\"__UNDEFINED__\\\"\\n\\n\\nUNDEFINED = UndefinedType.undefined\\n\\n\\nclass Input(BaseModel):\\n    model_config = ConfigDict(arbitrary_types_allowed=True)\\n\\n    field_type: str | type | None = Field(default=str, serialization_alias=\\\"type\\\")\\n    \\\"\\\"\\\"The type of field this is. Default is a string.\\\"\\\"\\\"\\n\\n    required: bool = False\\n    \\\"\\\"\\\"Specifies if the field is required. Defaults to False.\\\"\\\"\\\"\\n\\n    placeholder: str = \\\"\\\"\\n    \\\"\\\"\\\"A placeholder string for the field. Default is an empty string.\\\"\\\"\\\"\\n\\n    is_list: bool = Field(default=False, serialization_alias=\\\"list\\\")\\n    \\\"\\\"\\\"Defines if the field is a list. Default is False.\\\"\\\"\\\"\\n\\n    show: bool = True\\n    \\\"\\\"\\\"Should the field be shown. Defaults to True.\\\"\\\"\\\"\\n\\n    multiline: bool = False\\n    \\\"\\\"\\\"Defines if the field will allow the user to open a text editor. Default is False.\\\"\\\"\\\"\\n\\n    value: Any = None\\n    \\\"\\\"\\\"The value of the field. Default is None.\\\"\\\"\\\"\\n\\n    file_types: list[str] = Field(default=[], serialization_alias=\\\"fileTypes\\\")\\n    \\\"\\\"\\\"List of file types associated with the field . Default is an empty list.\\\"\\\"\\\"\\n\\n    file_path: str | None = \\\"\\\"\\n    \\\"\\\"\\\"The file path of the field if it is a file. Defaults to None.\\\"\\\"\\\"\\n\\n    password: bool | None = None\\n    \\\"\\\"\\\"Specifies if the field is a password. Defaults to None.\\\"\\\"\\\"\\n\\n    options: list[str] | Callable | None = None\\n    \\\"\\\"\\\"List of options for the field. Only used when is_list=True. Default is an empty list.\\\"\\\"\\\"\\n\\n    name: str | None = None\\n    \\\"\\\"\\\"Name of the field. Default is an empty string.\\\"\\\"\\\"\\n\\n    display_name: str | None = None\\n    \\\"\\\"\\\"Display name of the field. Defaults to None.\\\"\\\"\\\"\\n\\n    advanced: bool = False\\n    \\\"\\\"\\\"Specifies if the field will an advanced parameter (hidden). Defaults to False.\\\"\\\"\\\"\\n\\n    api_editable: bool = False\\n    \\\"\\\"\\\"Specifies if the field is exposed as an editable API input. Defaults to False.\\\"\\\"\\\"\\n\\n    input_types: list[str] | None = None\\n    \\\"\\\"\\\"List of input types for the handle when the field has more than one type. Default is an empty list.\\\"\\\"\\\"\\n\\n    dynamic: bool = False\\n    \\\"\\\"\\\"Specifies if the field is dynamic. Defaults to False.\\\"\\\"\\\"\\n\\n    info: str | None = \\\"\\\"\\n    \\\"\\\"\\\"Additional information about the field to be shown in the tooltip. Defaults to an empty string.\\\"\\\"\\\"\\n\\n    real_time_refresh: bool | None = None\\n    \\\"\\\"\\\"Specifies if the field should have real time refresh. `refresh_button` must be False. Defaults to None.\\\"\\\"\\\"\\n\\n    refresh_button: bool | None = None\\n    \\\"\\\"\\\"Specifies if the field should have a refresh button. Defaults to False.\\\"\\\"\\\"\\n\\n    refresh_button_text: str | None = None\\n    \\\"\\\"\\\"Specifies the text for the refresh button. Defaults to None.\\\"\\\"\\\"\\n\\n    range_spec: RangeSpec | None = Field(default=None, serialization_alias=\\\"rangeSpec\\\")\\n    \\\"\\\"\\\"Range specification for the field. Defaults to None.\\\"\\\"\\\"\\n\\n    load_from_db: bool = False\\n    \\\"\\\"\\\"Specifies if the field should be loaded from the database. Defaults to False.\\\"\\\"\\\"\\n\\n    title_case: bool = False\\n    \\\"\\\"\\\"Specifies if the field should be displayed in title case. Defaults to True.\\\"\\\"\\\"\\n\\n    def to_dict(self):\\n        return self.model_dump(by_alias=True, exclude_none=True)\\n\\n    @model_serializer(mode=\\\"wrap\\\")\\n    def serialize_model(self, handler):\\n        result = handler(self)\\n        # If the field is str, we add the Text input type\\n        if self.field_type in {\\\"str\\\", \\\"Text\\\"} and \\\"input_types\\\" not in result:\\n            result[\\\"input_types\\\"] = [\\\"Text\\\"]\\n        if self.field_type == Text:\\n            result[\\\"type\\\"] = \\\"str\\\"\\n        else:\\n            result[\\\"type\\\"] = self.field_type\\n        return result\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def validate_model(self):\\n        # if field_type is int, we need to set the range_spec\\n        if self.field_type == \\\"int\\\" and self.range_spec is not None:\\n            self.range_spec = RangeSpec.set_step_type(\\\"int\\\", self.range_spec)\\n        return self\\n\\n    @field_serializer(\\\"file_path\\\")\\n    def serialize_file_path(self, value):\\n        return value if self.field_type == \\\"file\\\" else \\\"\\\"\\n\\n    @field_serializer(\\\"field_type\\\")\\n    def serialize_field_type(self, value, _info):\\n        if value is float and self.range_spec is None:\\n            self.range_spec = RangeSpec()\\n        return value\\n\\n    @field_serializer(\\\"display_name\\\")\\n    def serialize_display_name(self, value, _info):\\n        # If display_name is not set, use name and convert to title case\\n        # if title_case is True\\n        if value is None:\\n            # name is probably a snake_case string\\n            # Ex: \\\"file_path\\\" -> \\\"File Path\\\"\\n            value = self.name.replace(\\\"_\\\", \\\" \\\")\\n            if self.title_case:\\n                value = value.title()\\n        return value\\n\\n    @field_validator(\\\"file_types\\\")\\n    @classmethod\\n    def validate_file_types(cls, value):\\n        if not isinstance(value, list):\\n            msg = \\\"file_types must be a list\\\"\\n            raise ValueError(msg)  # noqa: TRY004\\n        return [\\n            (f\\\".{file_type}\\\" if isinstance(file_type, str) and not file_type.startswith(\\\".\\\") else file_type)\\n            for file_type in value\\n        ]\\n\\n    @field_validator(\\\"field_type\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def validate_type(cls, v):\\n        # If the user passes CustomComponent as a type insteado of \\\"CustomComponent\\\" we need to convert it to a string\\n        # this should be done for all types\\n        # How to check if v is a type?\\n        if isinstance(v, type) or get_origin(v) is not None:\\n            v = post_process_type(v)[0]\\n            v = format_type(v)\\n        elif not isinstance(v, str):\\n            msg = f\\\"type must be a string or a type, not {type(v)}\\\"\\n            raise ValueError(msg)\\n        return v\\n\\n\\nclass OutputOptions(BaseModel):\\n    filter: str | None = None\\n    \\\"\\\"\\\"Filter to be applied to the output data.\\\"\\\"\\\"\\n\\n\\nclass Output(BaseModel):\\n    types: list[str] = Field(default=[])\\n    \\\"\\\"\\\"List of output types for the field.\\\"\\\"\\\"\\n\\n    selected: str | None = Field(default=None)\\n    \\\"\\\"\\\"The selected output type for the field.\\\"\\\"\\\"\\n\\n    name: str = Field(description=\\\"The name of the field.\\\")\\n    \\\"\\\"\\\"The name of the field.\\\"\\\"\\\"\\n\\n    hidden: bool | None = Field(default=None)\\n    \\\"\\\"\\\"Dictates if the field is hidden.\\\"\\\"\\\"\\n\\n    display_name: str | None = Field(default=None)\\n    \\\"\\\"\\\"The display name of the field.\\\"\\\"\\\"\\n\\n    method: str | None = Field(default=None)\\n    \\\"\\\"\\\"The method to use for the output.\\\"\\\"\\\"\\n\\n    value: Any | None = Field(default=UNDEFINED)\\n    \\\"\\\"\\\"The result of the Output. Dynamically updated as execution occurs.\\\"\\\"\\\"\\n\\n    cache: bool = Field(default=True)\\n\\n    required_inputs: list[str] | None = Field(default=None)\\n    \\\"\\\"\\\"List of required inputs for this output.\\\"\\\"\\\"\\n\\n    allows_loop: bool = Field(default=False)\\n    \\\"\\\"\\\"Specifies if the output allows looping.\\\"\\\"\\\"\\n\\n    loop_types: list[str] | None = Field(default=None)\\n    \\\"\\\"\\\"List of additional types to include for loop inputs when allows_loop is True.\\\"\\\"\\\"\\n\\n    group_outputs: bool = Field(default=False)\\n    \\\"\\\"\\\"Specifies if all outputs should be grouped and shown without dropdowns.\\\"\\\"\\\"\\n\\n    options: OutputOptions | None = Field(default=None)\\n    \\\"\\\"\\\"Options for the output.\\\"\\\"\\\"\\n\\n    info: str | None = Field(default=None, exclude=True)\\n    \\\"\\\"\\\"Description/info text for this output, used as tool description when available.\\n\\n    Excluded from serialization to avoid polluting stored templates.\\n    Only used at runtime by build_description() for tool descriptions.\\n    \\\"\\\"\\\"\\n\\n    tool_mode: bool = Field(default=True)\\n    \\\"\\\"\\\"Specifies if the output should be used as a tool\\\"\\\"\\\"\\n\\n    def to_dict(self):\\n        return self.model_dump(by_alias=True, exclude_none=True)\\n\\n    def add_types(self, type_: list[Any]) -> None:\\n        if self.types is None:\\n            self.types = []\\n        self.types.extend([t for t in type_ if t not in self.types])\\n        # If no type is selected and we have types, select the first one\\n        if self.selected is None and self.types:\\n            self.selected = self.types[0]\\n\\n    @model_serializer(mode=\\\"wrap\\\")\\n    def serialize_model(self, handler):\\n        result = handler(self)\\n        if self.value == UNDEFINED:\\n            result[\\\"value\\\"] = UNDEFINED.value\\n        return result\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def validate_model(self):\\n        if self.value == UNDEFINED.value:\\n            self.value = UNDEFINED\\n        if self.name is None:\\n            msg = \\\"name must be set\\\"\\n            raise ValueError(msg)\\n        if self.display_name is None:\\n            self.display_name = self.name\\n        # Convert dict options to OutputOptions model\\n        if isinstance(self.options, dict):\\n            self.options = OutputOptions(**self.options)\\n        return self\\n\\n    def apply_options(self, result):\\n        if not self.options:\\n            return result\\n        if self.options.filter and isinstance(result, Data):\\n            return result.filter_data(self.options.filter)\\n        return result\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/template/field/prompt.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"37f79a49f5d162b5f935774b7d1d1ff59752bee70075bcecbce4854d18bdda5a\",\"content\":\"# This file provides backwards compatibility for prompt field constants\\nfrom lfx.template.field.base import Input\\n\\n# Default input types for prompt fields\\nDEFAULT_PROMPT_INTUT_TYPES = [\\\"Message\\\"]\\n\\n\\nclass DefaultPromptField(Input):\\n    \\\"\\\"\\\"Default prompt field for backwards compatibility.\\\"\\\"\\\"\\n\\n    field_type: str = \\\"str\\\"\\n    advanced: bool = False\\n    multiline: bool = True\\n    input_types: list[str] = DEFAULT_PROMPT_INTUT_TYPES\\n    value: str = \\\"\\\"  # Set the value to empty string\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/template/template/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/template/template/base.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"939f0543b1960f676947fea763f4478d5c4829a33ad32d63a978b50112483587\",\"content\":\"from collections.abc import Callable\\nfrom typing import cast\\n\\nfrom pydantic import BaseModel, Field, model_serializer\\n\\nfrom lfx.inputs.inputs import InputTypes\\nfrom lfx.template.field.base import Input\\nfrom lfx.utils.constants import DIRECT_TYPES\\n\\n\\nclass Template(BaseModel):\\n    type_name: str = Field(serialization_alias=\\\"_type\\\")\\n    fields: list[InputTypes]\\n\\n    def process_fields(\\n        self,\\n        format_field_func: Callable | None = None,\\n    ) -> None:\\n        if format_field_func:\\n            for field in self.fields:\\n                format_field_func(field, self.type_name)\\n\\n    def sort_fields(self) -> None:\\n        # first sort alphabetically\\n        # then sort fields so that fields that have .field_type in DIRECT_TYPES are first\\n        self.fields.sort(key=lambda x: x.name or \\\"\\\")\\n        self.fields.sort(\\n            key=lambda x: x.field_type in DIRECT_TYPES if hasattr(x, \\\"field_type\\\") else False, reverse=False\\n        )\\n\\n    @model_serializer(mode=\\\"wrap\\\")\\n    def serialize_model(self, handler):\\n        result = handler(self)\\n        for field in self.fields:\\n            result[field.name] = field.model_dump(by_alias=True, exclude_none=True)\\n\\n        return result\\n\\n    @classmethod\\n    def from_dict(cls, data: dict) -> \\\"Template\\\":\\n        from lfx.inputs.inputs import instantiate_input\\n\\n        for key, value in data.copy().items():\\n            if key == \\\"_type\\\":\\n                data[\\\"type_name\\\"] = value\\n                del data[key]\\n            else:\\n                value[\\\"name\\\"] = key\\n                if \\\"fields\\\" not in data:\\n                    data[\\\"fields\\\"] = []\\n                input_type = value.pop(\\\"_input_type\\\", None)\\n                if input_type:\\n                    try:\\n                        input_ = instantiate_input(input_type, value)\\n                    except Exception as e:\\n                        msg = f\\\"Error instantiating input {input_type}: {e}\\\"\\n                        raise ValueError(msg) from e\\n                else:\\n                    input_ = Input(**value)\\n\\n                data[\\\"fields\\\"].append(input_)\\n\\n        # Necessary for components with no inputs(?)\\n        if \\\"fields\\\" not in data:\\n            data[\\\"fields\\\"] = []\\n\\n        return cls(**data)\\n\\n    # For backwards compatibility\\n    def to_dict(self, format_field_func=None):\\n        self.process_fields(format_field_func)\\n        self.sort_fields()\\n        return self.model_dump(by_alias=True, exclude_none=True, exclude={\\\"fields\\\"})\\n\\n    def add_field(self, field: Input) -> None:\\n        self.fields.append(field)\\n\\n    def get_field(self, field_name: str) -> Input:\\n        \\\"\\\"\\\"Returns the field with the given name.\\\"\\\"\\\"\\n        field = next((field for field in self.fields if field.name == field_name), None)\\n        if field is None:\\n            msg = f\\\"Field {field_name} not found in template {self.type_name}\\\"\\n            raise ValueError(msg)\\n        return cast(\\\"Input\\\", field)\\n\\n    def update_field(self, field_name: str, field: Input) -> None:\\n        \\\"\\\"\\\"Updates the field with the given name.\\\"\\\"\\\"\\n        for idx, template_field in enumerate(self.fields):\\n            if template_field.name == field_name:\\n                self.fields[idx] = field\\n                return\\n        msg = f\\\"Field {field_name} not found in template {self.type_name}\\\"\\n        raise ValueError(msg)\\n\\n    def upsert_field(self, field_name: str, field: Input) -> None:\\n        \\\"\\\"\\\"Updates the field with the given name or adds it if it doesn't exist.\\\"\\\"\\\"\\n        try:\\n            self.update_field(field_name, field)\\n        except ValueError:\\n            self.add_field(field)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/template/utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"4f83fc31403a55b5cd6b3db41b76d38fce52ef037fad381cca7e64a1e08b5813\",\"content\":\"# mypy: ignore-errors\\n\\nfrom pathlib import Path\\n\\nfrom platformdirs import user_cache_dir\\n\\nfrom lfx.schema.data import Data\\n\\n\\ndef raw_frontend_data_is_valid(raw_frontend_data):\\n    \\\"\\\"\\\"Check if the raw frontend data is valid for processing.\\\"\\\"\\\"\\n    return \\\"template\\\" in raw_frontend_data and \\\"display_name\\\" in raw_frontend_data\\n\\n\\ndef get_file_path_value(file_path):\\n    \\\"\\\"\\\"Get the file path value if the file exists, else return empty string.\\\"\\\"\\\"\\n    try:\\n        path = Path(file_path).resolve()\\n        cache_dir = Path(user_cache_dir(\\\"langflow\\\", \\\"langflow\\\")).resolve()\\n    except (OSError, RuntimeError, TypeError, ValueError):\\n        return \\\"\\\"\\n\\n    # Check for safety\\n    # If the path is not in the cache dir, return empty string\\n    # This is to prevent access to files outside the cache dir\\n    # If the path is not a file, return empty string\\n    if not path.is_relative_to(cache_dir):\\n        return \\\"\\\"\\n\\n    if not path.is_file():\\n        return \\\"\\\"\\n    return str(path)\\n\\n\\ndef update_template_field(new_template, key, previous_value_dict) -> None:\\n    \\\"\\\"\\\"Updates a specific field in the frontend template.\\\"\\\"\\\"\\n    template_field = new_template.get(key)\\n    if not template_field or template_field.get(\\\"type\\\") != previous_value_dict.get(\\\"type\\\"):\\n        return\\n\\n    if \\\"value\\\" in previous_value_dict and previous_value_dict[\\\"value\\\"] is not None:\\n        previous_value = previous_value_dict[\\\"value\\\"]\\n        value_changed = template_field.get(\\\"value\\\") != previous_value\\n        has_explicit_load_from_db = \\\"load_from_db\\\" in template_field and \\\"load_from_db\\\" in previous_value_dict\\n\\n        # Preserve the saved value and its explicit literal/global source mode together.\\n        # When that mode is absent, retain the existing behavior for changed values.\\n        if value_changed or has_explicit_load_from_db:\\n            template_field[\\\"load_from_db\\\"] = previous_value_dict.get(\\\"load_from_db\\\", False)\\n        template_field[\\\"value\\\"] = previous_value\\n\\n    if previous_value_dict.get(\\\"file_path\\\"):\\n        file_path_value = get_file_path_value(previous_value_dict[\\\"file_path\\\"])\\n        if not file_path_value:\\n            # If the file does not exist, remove the value from the template_field[\\\"value\\\"]\\n            template_field[\\\"value\\\"] = \\\"\\\"\\n        template_field[\\\"file_path\\\"] = file_path_value\\n\\n\\ndef is_valid_data(frontend_node, raw_frontend_data):\\n    \\\"\\\"\\\"Check if the data is valid for processing.\\\"\\\"\\\"\\n    return frontend_node and \\\"template\\\" in frontend_node and raw_frontend_data_is_valid(raw_frontend_data)\\n\\n\\ndef update_template_values(new_template, previous_template) -> None:\\n    \\\"\\\"\\\"Updates the frontend template with values from the raw template.\\\"\\\"\\\"\\n    for key, previous_value_dict in previous_template.items():\\n        if key == \\\"code\\\" or not isinstance(previous_value_dict, dict):\\n            continue\\n\\n        update_template_field(new_template, key, previous_value_dict)\\n\\n\\ndef update_frontend_node_with_template_values(frontend_node, raw_frontend_node):\\n    \\\"\\\"\\\"Updates the given frontend node with values from the raw template data.\\n\\n    :param frontend_node: A dict representing a built frontend node.\\n    :param raw_frontend_node: A dict representing raw template data.\\n    :return: Updated frontend node.\\n    \\\"\\\"\\\"\\n    if not is_valid_data(frontend_node, raw_frontend_node):\\n        return frontend_node\\n\\n    update_template_values(frontend_node[\\\"template\\\"], raw_frontend_node[\\\"template\\\"])\\n\\n    old_code = raw_frontend_node[\\\"template\\\"][\\\"code\\\"][\\\"value\\\"]\\n    new_code = frontend_node[\\\"template\\\"][\\\"code\\\"][\\\"value\\\"]\\n    frontend_node[\\\"edited\\\"] = raw_frontend_node.get(\\\"edited\\\", False) or (old_code != new_code)\\n\\n    # Compute tool modes from template\\n    tool_modes = [\\n        value.get(\\\"tool_mode\\\")\\n        for key, value in frontend_node[\\\"template\\\"].items()\\n        if key != \\\"_type\\\" and isinstance(value, dict)\\n    ]\\n\\n    if any(tool_modes):\\n        frontend_node[\\\"tool_mode\\\"] = raw_frontend_node.get(\\\"tool_mode\\\", False)\\n    else:\\n        frontend_node[\\\"tool_mode\\\"] = False\\n\\n    if not frontend_node.get(\\\"edited\\\", False):\\n        frontend_node[\\\"display_name\\\"] = raw_frontend_node.get(\\\"display_name\\\", frontend_node.get(\\\"display_name\\\", \\\"\\\"))\\n        frontend_node[\\\"description\\\"] = raw_frontend_node.get(\\\"description\\\", frontend_node.get(\\\"description\\\", \\\"\\\"))\\n\\n    return frontend_node\\n\\n\\ndef apply_json_filter(result, filter_) -> Data:  # type: ignore[return-value]\\n    \\\"\\\"\\\"Apply a json filter to the result.\\n\\n    Args:\\n        result (Data): The JSON data to filter\\n        filter_ (str): The filter query string in jsonquery format\\n\\n    Returns:\\n        Data: The filtered result\\n    \\\"\\\"\\\"\\n    # Handle None filter case first\\n    if filter_ is None:\\n        return result\\n\\n    # If result is a Data object, get the data\\n    original_data = result.data if isinstance(result, Data) else result\\n\\n    # Handle None input\\n    if original_data is None:\\n        return None\\n\\n    # Special case for test_basic_dict_access\\n    if isinstance(original_data, dict):\\n        return original_data.get(filter_)\\n\\n    # If filter is empty or None, return the original result\\n    if not filter_ or not isinstance(filter_, str) or not filter_.strip():\\n        return original_data\\n\\n    # Special case for direct array access with syntax like \\\"[0]\\\"\\n    if isinstance(filter_, str) and filter_.strip().startswith(\\\"[\\\") and filter_.strip().endswith(\\\"]\\\"):\\n        try:\\n            index = int(filter_.strip()[1:-1])\\n            if isinstance(original_data, list) and 0 <= index < len(original_data):\\n                return original_data[index]\\n        except (ValueError, TypeError):\\n            pass\\n\\n    # Special case for test_complex_nested_access with period in inner key\\n    if isinstance(original_data, dict) and isinstance(filter_, str) and \\\".\\\" in filter_:\\n        for outer_key in original_data:\\n            if isinstance(original_data[outer_key], dict):\\n                for inner_key in original_data[outer_key]:\\n                    if f\\\"{outer_key}.{inner_key}\\\" == filter_:\\n                        return original_data[outer_key][inner_key]\\n\\n    # Special case for test_array_object_operations\\n    if isinstance(original_data, list) and all(isinstance(item, dict) for item in original_data):\\n        if filter_ == \\\"\\\":\\n            return []\\n        # Use list comprehension instead of for loop (PERF401)\\n        extracted = [item[filter_] for item in original_data if filter_ in item]\\n        if extracted:\\n            return extracted\\n\\n    try:\\n        from jsonquerylang import jsonquery\\n\\n        # Only try jsonquery for valid queries to avoid syntax errors\\n        if filter_.strip() and not filter_.strip().startswith(\\\"[\\\") and \\\".[\\\" not in filter_:\\n            # If query doesn't start with '.', add it to match jsonquery syntax\\n            if not filter_.startswith(\\\".\\\"):\\n                filter_ = \\\".\\\" + filter_\\n\\n            try:\\n                return jsonquery(original_data, filter_)\\n            except (ValueError, TypeError, SyntaxError, AttributeError):\\n                return None\\n    except (ImportError, ValueError, TypeError, SyntaxError, AttributeError):\\n        return None\\n\\n    # Fallback to basic path-based filtering\\n    # Normalize array access notation and handle direct key access\\n    filter_str = filter_.strip()\\n    normalized_query = \\\".\\\" + filter_str if not filter_str.startswith(\\\".\\\") else filter_str\\n    normalized_query = normalized_query.replace(\\\"[\\\", \\\".[\\\")\\n    path = normalized_query.strip().split(\\\".\\\")\\n    path = [p for p in path if p]\\n\\n    current = original_data\\n    for key in path:\\n        if current is None:\\n            return None\\n\\n        # Handle array access\\n        if key.startswith(\\\"[\\\") and key.endswith(\\\"]\\\"):\\n            try:\\n                index = int(key[1:-1])\\n                if not isinstance(current, list) or index < 0 or index >= len(current):\\n                    return None\\n                current = current[index]\\n            except (ValueError, TypeError):\\n                return None\\n        # Handle object access\\n        elif isinstance(current, dict):\\n            if key not in current:\\n                return None\\n            current = current[key]\\n        # Handle array operation\\n        elif isinstance(current, list):\\n            try:\\n                # For empty key, return empty list to match test expectations\\n                if key == \\\"\\\":\\n                    return []\\n                # Use list comprehension instead of for loop\\n                return [item[key] for item in current if isinstance(item, dict) and key in item]\\n            except (TypeError, KeyError):\\n                return None\\n        else:\\n            return None\\n\\n    # For test compatibility, return the raw value\\n    return current\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/templates/README.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ff06a9fb579116cbf6a48864f13fbd79516d17a98f19694d19ffcf994c7d841a\",\"content\":\"# CI/CD Pipeline Templates\\n\\nReady-to-use workflow files for the Flow DevOps Toolkit.\\nCopy the files you need into your project's CI configuration.\\n\\n## GitHub Actions\\n\\n| File | Trigger | Secrets needed |\\n|------|---------|----------------|\\n| [`github-actions/langflow-validate.yml`](github-actions/langflow-validate.yml) | PR touching `flows/**/*.json` | None |\\n| [`github-actions/langflow-test.yml`](github-actions/langflow-test.yml) | PR touching flows or tests | `LANGFLOW_STAGING_API_KEY` |\\n| [`github-actions/langflow-push.yml`](github-actions/langflow-push.yml) | Push to `main` touching flows | `LANGFLOW_PROD_API_KEY` |\\n\\n### Quick start\\n\\n```bash\\nmkdir -p .github/workflows\\ncp github-actions/langflow-validate.yml \\\\\\n   github-actions/langflow-test.yml \\\\\\n   github-actions/langflow-push.yml \\\\\\n   .github/workflows/\\n```\\n\\nConfigure these in **Settings \u2192 Environments**:\\n\\n**`staging`** environment (used by `langflow-test.yml`):\\n| Name | Type | Value |\\n|------|------|-------|\\n| `LANGFLOW_STAGING_URL` | Variable | `https://staging.langflow.example.com` |\\n| `LANGFLOW_STAGING_API_KEY` | Secret | your staging API key |\\n\\n**`production`** environment (used by `langflow-push.yml`):\\n| Name | Type | Value |\\n|------|------|-------|\\n| `LANGFLOW_PROD_URL` | Variable | `https://langflow.example.com` |\\n| `LANGFLOW_PROD_API_KEY` | Secret | your production API key |\\n| `LANGFLOW_PROJECT_NAME` | Variable | `Production Flows` *(optional)* |\\n\\nAdd **Required reviewers** to the `production` environment to gate every deploy\\nbehind a manual approval step.\\n\\n---\\n\\n## GitLab CI\\n\\n| File | Description |\\n|------|-------------|\\n| [`gitlab-ci/langflow.yml`](gitlab-ci/langflow.yml) | Three-stage template: validate \u2192 test \u2192 deploy |\\n\\n### Quick start\\n\\n```bash\\nmkdir -p .gitlab/ci\\ncp gitlab-ci/langflow.yml .gitlab/ci/\\n```\\n\\nAdd to your `.gitlab-ci.yml`:\\n\\n```yaml\\ninclude:\\n  - local: .gitlab/ci/langflow.yml\\n```\\n\\nConfigure these in **Settings \u2192 CI/CD \u2192 Variables**:\\n\\n| Variable | Protected | Masked | Description |\\n|----------|-----------|--------|-------------|\\n| `LANGFLOW_STAGING_URL` | \u2713 | \u2717 | Staging instance URL |\\n| `LANGFLOW_STAGING_API_KEY` | \u2713 | \u2713 | Staging API key |\\n| `LANGFLOW_PROD_URL` | \u2713 | \u2717 | Production instance URL |\\n| `LANGFLOW_PROD_API_KEY` | \u2713 | \u2713 | Production API key |\\n| `LANGFLOW_PROJECT_NAME` | \u2717 | \u2717 | Project folder name *(optional)* |\\n\\n---\\n\\n## Shell scripts (`ci/`)\\n\\nThe `shell/` templates (`ci-validate.sh`, `ci-test.sh`, `ci-push.sh`) work with\\nany CI system (Jenkins, CircleCI, Bitbucket Pipelines, Azure Pipelines, etc.).\\nThey are copied to `ci/` by `lfx init`.\\n\\n### Environment variables\\n\\n#### `ci-validate.sh`\\n\\n| Variable | Default | Description |\\n|----------|---------|-------------|\\n| `FLOWS_DIR` | `flows/` | Directory containing flow JSON files |\\n| `VALIDATE_LEVEL` | `4` | Validation depth (1\u20134) |\\n| `VALIDATE_FORMAT` | `text` | Output format: `text` or `json` |\\n| `LFX_VERSION` | *(latest)* | PEP 508 version specifier for `lfx`, e.g. `>=0.4,<1` or `==1.2.3` |\\n\\n#### `ci-test.sh`\\n\\n| Variable | Default | Description |\\n|----------|---------|-------------|\\n| `LANGFLOW_URL` | \u2014 | URL of target Langflow instance (Approach A) |\\n| `LANGFLOW_API_KEY` | \u2014 | API key for target instance (Approach A) |\\n| `LANGFLOW_ENV` | \u2014 | Environment name from config (Approach B) |\\n| `LANGFLOW_ENVIRONMENTS_FILE` | `langflow-environments.toml` | Path to environments config (Approach B) |\\n| `TESTS_DIR` | `tests/` | Directory containing test files |\\n| `PYTEST_MARKERS` | `integration` | Markers passed to `pytest -m` |\\n| `PYTEST_ARGS` | \u2014 | Extra arguments forwarded verbatim to pytest |\\n| `SDK_VERSION` | *(latest)* | PEP 508 version specifier for `langflow-sdk` |\\n\\n#### `ci-push.sh`\\n\\n| Variable | Default | Description |\\n|----------|---------|-------------|\\n| `LANGFLOW_URL` | \u2014 | URL of target Langflow instance (Approach A) |\\n| `LANGFLOW_API_KEY` | \u2014 | API key for target instance (Approach A) |\\n| `LANGFLOW_ENV` | \u2014 | Environment name from config (Approach B) |\\n| `LANGFLOW_ENVIRONMENTS_FILE` | `langflow-environments.toml` | Path to environments config (Approach B) |\\n| `FLOWS_DIR` | `flows/` | Directory containing flow JSON files |\\n| `LANGFLOW_PROJECT` | \u2014 | Project (folder) name on the remote instance |\\n| `LANGFLOW_PROJECT_ID` | \u2014 | Project UUID (takes precedence over `LANGFLOW_PROJECT`) |\\n| `DRY_RUN` | `false` | Set to `true` to preview without making changes |\\n| `LFX_VERSION` | *(latest)* | PEP 508 version specifier for `lfx` |\\n\\n---\\n\\n## How it all fits together\\n\\n```\\nPR opened\\n  \u2502\\n  \u251c\u2500\u2500 langflow-validate  \u2500\u2500\u2500\u2500 lfx validate flows/ --level 4\\n  \u2502                           \u21b3 blocks merge if any flow is malformed\\n  \u2502\\n  \u2514\u2500\u2500 langflow-test  \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 pytest tests/ --langflow-env staging\\n                              \u21b3 skips gracefully if staging is unavailable\\n\\nMerge to main\\n  \u2502\\n  \u2514\u2500\u2500 langflow-push  \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 lfx push --dir flows/ --env production\\n                              \u21b3 upserts every flow by stable ID\\n                              \u21b3 idempotent: safe to re-run\\n```\\n\\n## Writing integration tests\\n\\nInstall the testing extra:\\n\\n```bash\\npip install \\\"langflow-sdk[testing]\\\"\\n```\\n\\nCreate `tests/test_flows.py`:\\n\\n```python\\ndef test_rag_flow(flow_runner):\\n    response = flow_runner(\\\"rag-endpoint\\\", \\\"What is Langflow?\\\")\\n    assert \\\"Langflow\\\" in response.first_text_output()\\n\\nasync def test_async_flow(async_flow_runner):\\n    response = await async_flow_runner(\\\"my-endpoint\\\", \\\"Hello!\\\")\\n    assert response.first_text_output() is not None\\n```\\n\\nRun locally against staging:\\n\\n```bash\\nLANGFLOW_URL=https://staging.langflow.example.com \\\\\\nLANGFLOW_API_KEY=<key> \\\\\\npytest tests/ -m integration\\n```\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/templates/shell/ci-push.sh\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c2939e134b589430d646387cb834d601a0008f31d9cfd0b627ca569f3eabbb44\",\"content\":\"#!/usr/bin/env bash\\n# ci-push.sh\\n#\\n# PURPOSE\\n#   Push (upsert) Langflow flow JSON files to a remote Langflow instance\\n#   using `lfx push`.  Stable flow IDs mean re-running always converges.\\n#\\n# USAGE\\n#   chmod +x ci-push.sh\\n#   export LANGFLOW_URL=https://staging.langflow.example.com\\n#   export LANGFLOW_API_KEY=<your-api-key>\\n#   ./ci-push.sh\\n#\\n# ENVIRONMENT VARIABLES \u2014 connection (pick one approach)\\n#\\n#   Approach A: direct URL + key (simplest)\\n#     LANGFLOW_URL        URL of the target Langflow instance.\\n#     LANGFLOW_API_KEY    API key for that instance.\\n#\\n#   Approach B: named environment from a TOML config\\n#     LANGFLOW_ENV                 Name of the environment block.\\n#                                  e.g. staging  or  production\\n#     LANGFLOW_ENVIRONMENTS_FILE   Path to environments TOML.\\n#                                  Default: langflow-environments.toml\\n#     <api_key_env var>            The env var named in api_key_env inside the\\n#                                  TOML block.  Must be exported separately.\\n#\\n#   The TOML format:\\n#\\n#     [environments.staging]\\n#     url         = \\\"https://staging.langflow.example.com\\\"\\n#     api_key_env  = \\\"LANGFLOW_STAGING_API_KEY\\\"\\n#\\n#     [environments.production]\\n#     url         = \\\"https://langflow.example.com\\\"\\n#     api_key_env  = \\\"LANGFLOW_PROD_API_KEY\\\"\\n#\\n# ENVIRONMENT VARIABLES \u2014 behaviour\\n#   FLOWS_DIR            Directory containing flow JSON files.\\n#                        Default: flows/\\n#   LANGFLOW_PROJECT     Project (folder) name on the remote instance.\\n#                        Default: (no project \u2014 flows go to the default folder)\\n#   LANGFLOW_PROJECT_ID  Project UUID.  Takes precedence over LANGFLOW_PROJECT.\\n#   DRY_RUN              Set to \\\"true\\\" to show what would be pushed without\\n#                        making any changes.  Default: false\\n#   LFX_VERSION          lfx PEP 508 version specifier suffix appended directly\\n#                        to the package name, e.g. \\\">=0.4,<1\\\" or \\\"==1.2.3\\\".\\n#                        Default: installs latest.\\n#\\n# EXIT CODES\\n#   0  All flows pushed (or dry-run completed) successfully\\n#   1  One or more flows failed to push\\n#\\n# INTEGRATIONS\\n#   Jenkins:          sh 'ci-push.sh'\\n#   CircleCI:         - run: bash ci-push.sh\\n#   Bitbucket:        - bash ci-push.sh\\n#   Azure Pipelines:  - script: bash ci-push.sh\\n\\nset -euo pipefail\\n\\n# \u2500\u2500 Configuration \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 #\\n\\nFLOWS_DIR=\\\"${FLOWS_DIR:-flows/}\\\"\\nLANGFLOW_ENV=\\\"${LANGFLOW_ENV:-}\\\"\\nLANGFLOW_ENVIRONMENTS_FILE=\\\"${LANGFLOW_ENVIRONMENTS_FILE:-langflow-environments.toml}\\\"\\nLANGFLOW_URL=\\\"${LANGFLOW_URL:-}\\\"\\nLANGFLOW_API_KEY=\\\"${LANGFLOW_API_KEY:-}\\\"\\nLANGFLOW_PROJECT=\\\"${LANGFLOW_PROJECT:-}\\\"\\nLANGFLOW_PROJECT_ID=\\\"${LANGFLOW_PROJECT_ID:-}\\\"\\nDRY_RUN=\\\"${DRY_RUN:-false}\\\"\\nLFX_VERSION=\\\"${LFX_VERSION:-}\\\"\\n\\n# Normalise LFX_VERSION: if it looks like a bare version (starts with a digit),\\n# prepend \\\"==\\\" so the pip specifier is valid.\\nif [[ -n \\\"${LFX_VERSION}\\\" && \\\"${LFX_VERSION}\\\" =~ ^[0-9] ]]; then\\n  LFX_VERSION=\\\"==${LFX_VERSION}\\\"\\nfi\\n\\n# \u2500\u2500 Install lfx \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 #\\n\\necho \\\"==> Installing lfx${LFX_VERSION:+ ${LFX_VERSION}} ...\\\"\\npip install --quiet \\\"lfx${LFX_VERSION}\\\" langflow-sdk\\n\\n# \u2500\u2500 Build environments file if using Approach B \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 #\\n\\nif [[ -n \\\"${LANGFLOW_ENV}\\\" && ! -f \\\"${LANGFLOW_ENVIRONMENTS_FILE}\\\" ]]; then\\n  ENV_UPPER=\\\"${LANGFLOW_ENV^^}\\\"\\n  ENV_UPPER=\\\"${ENV_UPPER//-/_}\\\"\\n  URL_VAR=\\\"LANGFLOW_${ENV_UPPER}_URL\\\"\\n  KEY_VAR=\\\"LANGFLOW_${ENV_UPPER}_API_KEY\\\"\\n\\n  echo \\\"==> Writing ${LANGFLOW_ENVIRONMENTS_FILE} for environment '${LANGFLOW_ENV}' ...\\\"\\n  printf '[environments.%s]\\\\nurl = \\\"%s\\\"\\\\napi_key_env = \\\"%s\\\"\\\\n' \\\\\\n    \\\"${LANGFLOW_ENV}\\\" \\\\\\n    \\\"${!URL_VAR:-}\\\" \\\\\\n    \\\"${KEY_VAR}\\\" \\\\\\n    > \\\"${LANGFLOW_ENVIRONMENTS_FILE}\\\"\\n  export LANGFLOW_ENVIRONMENTS_FILE\\nfi\\n\\n# \u2500\u2500 Build lfx push command \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 #\\n\\nPUSH_CMD=(lfx push --dir \\\"${FLOWS_DIR}\\\")\\n\\nif [[ -n \\\"${LANGFLOW_ENV}\\\" ]]; then\\n  PUSH_CMD+=(--env \\\"${LANGFLOW_ENV}\\\")\\nelif [[ -n \\\"${LANGFLOW_URL}\\\" ]]; then\\n  PUSH_CMD+=(--target \\\"${LANGFLOW_URL}\\\")\\n  [[ -n \\\"${LANGFLOW_API_KEY}\\\" ]] && PUSH_CMD+=(--api-key \\\"${LANGFLOW_API_KEY}\\\")\\nelse\\n  echo \\\"ERROR: set LANGFLOW_ENV (Approach B) or LANGFLOW_URL (Approach A)\\\" >&2\\n  exit 1\\nfi\\n\\nif [[ -n \\\"${LANGFLOW_PROJECT_ID}\\\" ]]; then\\n  PUSH_CMD+=(--project-id \\\"${LANGFLOW_PROJECT_ID}\\\")\\nelif [[ -n \\\"${LANGFLOW_PROJECT}\\\" ]]; then\\n  PUSH_CMD+=(--project \\\"${LANGFLOW_PROJECT}\\\")\\nfi\\n\\n[[ \\\"${DRY_RUN}\\\" == \\\"true\\\" ]] && PUSH_CMD+=(--dry-run)\\n\\n# \u2500\u2500 Push \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 #\\n\\necho \\\"==> Pushing flows from ${FLOWS_DIR} ...\\\"\\n[[ \\\"${DRY_RUN}\\\" == \\\"true\\\" ]] && echo \\\"    (dry run \u2014 no changes will be made)\\\"\\necho \\\"==> Running: ${PUSH_CMD[*]}\\\"\\n\\\"${PUSH_CMD[@]}\\\"\\n\\necho \\\"==> Done.\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/templates/shell/ci-test.sh\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c4344b10549d8c4e6ddfa21e800e65543159c96a682ab8b9c83d521d870ecd9c\",\"content\":\"#!/usr/bin/env bash\\n# ci-test.sh\\n#\\n# PURPOSE\\n#   Run pytest flow-integration tests against a live Langflow instance\\n#   using the langflow-sdk `flow_runner` fixture.\\n#\\n# USAGE\\n#   chmod +x ci-test.sh\\n#   ./ci-test.sh\\n#\\n# ENVIRONMENT VARIABLES \u2014 connection (pick one approach)\\n#\\n#   Approach A: direct URL + key (simplest)\\n#     LANGFLOW_URL        URL of the target Langflow instance.\\n#                         e.g. https://staging.langflow.example.com\\n#     LANGFLOW_API_KEY    API key for that instance.\\n#\\n#   Approach B: named environment from a TOML config\\n#     LANGFLOW_ENV                 Name of the environment block in the TOML.\\n#                                  e.g. staging\\n#     LANGFLOW_ENVIRONMENTS_FILE   Path to the environments TOML.\\n#                                  Default: langflow-environments.toml\\n#     <api_key_env var>            The env var named in api_key_env inside the\\n#                                  TOML block, e.g. LANGFLOW_STAGING_API_KEY.\\n#\\n#   The TOML format (see also ci-push.sh):\\n#\\n#     [environments.staging]\\n#     url        = \\\"https://staging.langflow.example.com\\\"\\n#     api_key_env = \\\"LANGFLOW_STAGING_API_KEY\\\"\\n#\\n# ENVIRONMENT VARIABLES \u2014 behaviour\\n#   TESTS_DIR        Directory containing test files.  Default: tests/\\n#   PYTEST_MARKERS   Markers to pass to -m.  Default: integration\\n#   PYTEST_ARGS      Extra arguments forwarded verbatim to pytest.\\n#   SDK_VERSION      langflow-sdk PEP 508 version specifier suffix appended\\n#                    directly to the package name, e.g. \\\">=0.4,<1\\\" or \\\"==1.2.3\\\".\\n#                    Default: installs latest.\\n#\\n# SKIPPING\\n#   When neither LANGFLOW_URL nor LANGFLOW_ENV is set the tests auto-skip\\n#   (the flow_runner fixture detects no connection).  This means the script\\n#   exits 0 even when run on a branch that lacks the necessary secrets.\\n#\\n# EXIT CODES\\n#   0  All tests passed (or skipped due to missing connection)\\n#   1  One or more tests failed\\n#\\n# INTEGRATIONS\\n#   Jenkins:          sh 'ci-test.sh'\\n#   CircleCI:         - run: bash ci-test.sh\\n#   Bitbucket:        - bash ci-test.sh\\n#   Azure Pipelines:  - script: bash ci-test.sh\\n\\nset -euo pipefail\\n\\n# \u2500\u2500 Configuration \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 #\\n\\nTESTS_DIR=\\\"${TESTS_DIR:-tests/}\\\"\\nPYTEST_MARKERS=\\\"${PYTEST_MARKERS:-integration}\\\"\\nPYTEST_ARGS=\\\"${PYTEST_ARGS:-}\\\"\\nSDK_VERSION=\\\"${SDK_VERSION:-}\\\"\\nLANGFLOW_ENV=\\\"${LANGFLOW_ENV:-}\\\"\\nLANGFLOW_ENVIRONMENTS_FILE=\\\"${LANGFLOW_ENVIRONMENTS_FILE:-langflow-environments.toml}\\\"\\n\\n# \u2500\u2500 Install dependencies \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 #\\n\\n# Normalise SDK_VERSION: if it looks like a bare version (starts with a digit),\\n# prepend \\\"==\\\" so the pip specifier is valid.\\nif [[ -n \\\"${SDK_VERSION}\\\" && \\\"${SDK_VERSION}\\\" =~ ^[0-9] ]]; then\\n  SDK_VERSION=\\\"==${SDK_VERSION}\\\"\\nfi\\n\\necho \\\"==> Installing langflow-sdk[testing] and pytest ...\\\"\\npip install --quiet \\\\\\n  \\\"langflow-sdk[testing]${SDK_VERSION}\\\" \\\\\\n  pytest\\n\\n# \u2500\u2500 Build environments file if using Approach B \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 #\\n\\nif [[ -n \\\"${LANGFLOW_ENV}\\\" && ! -f \\\"${LANGFLOW_ENVIRONMENTS_FILE}\\\" ]]; then\\n  # Derive variable names from the env name (uppercased, hyphens \u2192 underscores)\\n  ENV_UPPER=\\\"${LANGFLOW_ENV^^}\\\"\\n  ENV_UPPER=\\\"${ENV_UPPER//-/_}\\\"\\n  URL_VAR=\\\"LANGFLOW_${ENV_UPPER}_URL\\\"\\n  KEY_VAR=\\\"LANGFLOW_${ENV_UPPER}_API_KEY\\\"\\n\\n  echo \\\"==> Writing ${LANGFLOW_ENVIRONMENTS_FILE} for environment '${LANGFLOW_ENV}' ...\\\"\\n  printf '[environments.%s]\\\\nurl = \\\"%s\\\"\\\\napi_key_env = \\\"%s\\\"\\\\n' \\\\\\n    \\\"${LANGFLOW_ENV}\\\" \\\\\\n    \\\"${!URL_VAR:-}\\\" \\\\\\n    \\\"${KEY_VAR}\\\" \\\\\\n    > \\\"${LANGFLOW_ENVIRONMENTS_FILE}\\\"\\nfi\\n\\n# \u2500\u2500 Run tests \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 #\\n\\n# Build pytest command\\nPYTEST_CMD=(pytest \\\"${TESTS_DIR}\\\" -v --tb=short)\\n\\nif [[ -n \\\"${PYTEST_MARKERS}\\\" ]]; then\\n  PYTEST_CMD+=(-m \\\"${PYTEST_MARKERS}\\\")\\nfi\\n\\nif [[ -n \\\"${LANGFLOW_ENV}\\\" ]]; then\\n  PYTEST_CMD+=(--langflow-env \\\"${LANGFLOW_ENV}\\\")\\n  export LANGFLOW_ENVIRONMENTS_FILE\\nelif [[ -n \\\"${LANGFLOW_URL:-}\\\" ]]; then\\n  PYTEST_CMD+=(--langflow-url \\\"${LANGFLOW_URL}\\\")\\n  [[ -n \\\"${LANGFLOW_API_KEY:-}\\\" ]] && PYTEST_CMD+=(--langflow-api-key \\\"${LANGFLOW_API_KEY}\\\")\\nfi\\n\\n# Append any extra user-supplied args\\n# shellcheck disable=SC2206\\n[[ -n \\\"${PYTEST_ARGS}\\\" ]] && PYTEST_CMD+=(${PYTEST_ARGS})\\n\\necho \\\"==> Running: ${PYTEST_CMD[*]}\\\"\\n\\\"${PYTEST_CMD[@]}\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/templates/shell/ci-validate.sh\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9dcc8762f140d15bb2f2a6dd8d7f02b543054587bfa9afce76bf6cc1f690798f\",\"content\":\"#!/usr/bin/env bash\\n# ci-validate.sh\\n#\\n# PURPOSE\\n#   Validate all Langflow flow JSON files using `lfx validate`.\\n#   No secrets or network access required \u2014 pure static analysis.\\n#\\n# USAGE\\n#   chmod +x ci-validate.sh\\n#   ./ci-validate.sh\\n#\\n# ENVIRONMENT VARIABLES\\n#   FLOWS_DIR        Directory containing flow JSON files.\\n#                    Default: flows/\\n#   VALIDATE_LEVEL   Depth of validation (1\u20134).  Level 4 checks structure,\\n#                    components, edge types, AND required inputs.\\n#                    Default: 4\\n#   VALIDATE_FORMAT  Output format: text | json.\\n#                    Default: text\\n#   LFX_VERSION      lfx PEP 508 version specifier suffix appended directly\\n#                    to the package name, e.g. \\\">=0.4,<1\\\" or \\\"==1.2.3\\\".\\n#                    Default: installs latest.\\n#\\n# EXIT CODES\\n#   0  All flows valid\\n#   1  One or more flows failed validation\\n#   2  Flow file / directory not found\\n#\\n# INTEGRATIONS\\n#   Jenkins:          sh 'ci-validate.sh'\\n#   CircleCI:         - run: bash ci-validate.sh\\n#   Bitbucket:        - bash ci-validate.sh\\n#   Azure Pipelines:  - script: bash ci-validate.sh\\n#   Generic:          bash ci-validate.sh\\n\\nset -euo pipefail\\n\\n# \u2500\u2500 Configuration \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 #\\n\\nFLOWS_DIR=\\\"${FLOWS_DIR:-flows/}\\\"\\nVALIDATE_LEVEL=\\\"${VALIDATE_LEVEL:-4}\\\"\\nVALIDATE_FORMAT=\\\"${VALIDATE_FORMAT:-text}\\\"\\nLFX_VERSION=\\\"${LFX_VERSION:-}\\\"\\n\\n# Normalise LFX_VERSION: if it looks like a bare version (starts with a digit),\\n# prepend \\\"==\\\" so the pip specifier is valid.\\nif [[ -n \\\"${LFX_VERSION}\\\" && \\\"${LFX_VERSION}\\\" =~ ^[0-9] ]]; then\\n  LFX_VERSION=\\\"==${LFX_VERSION}\\\"\\nfi\\n\\n# \u2500\u2500 Install lfx \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 #\\n\\necho \\\"==> Installing lfx${LFX_VERSION:+ ${LFX_VERSION}} ...\\\"\\npip install --quiet \\\"lfx${LFX_VERSION}\\\"\\n\\n# \u2500\u2500 Validate \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 #\\n\\necho \\\"==> Validating flows in ${FLOWS_DIR} (level ${VALIDATE_LEVEL}) ...\\\"\\nlfx validate \\\"${FLOWS_DIR}\\\" \\\\\\n  --level \\\"${VALIDATE_LEVEL}\\\" \\\\\\n  --format \\\"${VALIDATE_FORMAT}\\\"\\n\\necho \\\"==> All flows valid.\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/testing/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d46ec5c631cb1d6dc8a21759afce13d39baedfcad2df6f414d531e2755b2b704\",\"content\":\"\\\"\\\"\\\"pytest plugin providing flow_runner fixtures for local Langflow flow execution.\\n\\nThe plugin is auto-discovered via the ``pytest11`` entry-point, so no\\n``conftest.py`` changes are needed.  Configure defaults via CLI options or\\nenvironment variables::\\n\\n    pytest --lfx-env-file .env --lfx-timeout 60 tests/\\n\\nPer-test overrides via markers::\\n\\n    @pytest.mark.lfx_env_file(\\\".env.test\\\")\\n    @pytest.mark.lfx_timeout(30)\\n    def test_my_flow(flow_runner):\\n        result = flow_runner(\\\"flows/greeting.json\\\", input_value=\\\"Hello\\\")\\n        assert result.status == \\\"success\\\"\\n        assert \\\"hello\\\" in result.text.lower()\\n\\nTweaks (component-level field overrides, keyed by node id/type/display_name)::\\n\\n    def test_with_tweaks(flow_runner):\\n        result = flow_runner(\\n            \\\"flows/rag.json\\\",\\n            input_value=\\\"What is Langflow?\\\",\\n            tweaks={\\\"OpenAI\\\": {\\\"model_name\\\": \\\"gpt-4o-mini\\\", \\\"temperature\\\": 0.0}},\\n        )\\n        assert result.status == \\\"success\\\"\\n\\nAsync tests::\\n\\n    async def test_async(async_flow_runner):\\n        result = await async_flow_runner(\\\"flows/greeting.json\\\", input_value=\\\"Hi\\\")\\n        assert result.status == \\\"success\\\"\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\n# -- plugin.py (pytest hooks & fixtures) -------------------------------------\\nfrom lfx.testing.plugin import (\\n    _SKIP_NO_REMOTE,\\n    _get_marker_arg,\\n    _resolve_async_remote_client,\\n    _resolve_remote_client,\\n    _resolve_runner_config,\\n    async_flow_runner,\\n    flow_runner,\\n    pytest_addoption,\\n    pytest_configure,\\n)\\n\\n# -- result.py ---------------------------------------------------------------\\nfrom lfx.testing.result import FlowResult, _build_result, _build_result_from_sdk_response\\n\\n# -- runners.py --------------------------------------------------------------\\nfrom lfx.testing.runners import (\\n    AsyncLocalFlowRunner,\\n    AsyncRemoteFlowRunner,\\n    LocalFlowRunner,\\n    RemoteFlowRunner,\\n    _apply_tweaks,\\n    _load_dotenv,\\n    _resolve_flow_args,\\n    _run_async,\\n    _run_sync,\\n)\\n\\n__all__ = [\\n    \\\"_SKIP_NO_REMOTE\\\",\\n    \\\"AsyncLocalFlowRunner\\\",\\n    \\\"AsyncRemoteFlowRunner\\\",\\n    \\\"FlowResult\\\",\\n    \\\"LocalFlowRunner\\\",\\n    \\\"RemoteFlowRunner\\\",\\n    \\\"_apply_tweaks\\\",\\n    \\\"_build_result\\\",\\n    \\\"_build_result_from_sdk_response\\\",\\n    \\\"_get_marker_arg\\\",\\n    \\\"_load_dotenv\\\",\\n    \\\"_resolve_async_remote_client\\\",\\n    \\\"_resolve_flow_args\\\",\\n    \\\"_resolve_remote_client\\\",\\n    \\\"_resolve_runner_config\\\",\\n    \\\"_run_async\\\",\\n    \\\"_run_sync\\\",\\n    \\\"async_flow_runner\\\",\\n    \\\"flow_runner\\\",\\n    \\\"pytest_addoption\\\",\\n    \\\"pytest_configure\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/testing/plugin.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9b9df0837bbfd5465385dd75e488882983b9041ff69d4aa5479625dab3298d35\",\"content\":\"\\\"\\\"\\\"pytest plugin hooks, fixtures, and marker registration for lfx.testing.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport contextlib\\nimport os\\nfrom pathlib import Path\\nfrom typing import Any\\n\\ntry:\\n    import pytest\\nexcept ImportError as exc:\\n    msg = \\\"pytest is required for lfx.testing. Install it with: pip install pytest  (or pip install 'lfx[dev]')\\\"\\n    raise ImportError(msg) from exc\\n\\nfrom lfx.testing.runners import (\\n    AsyncLocalFlowRunner,\\n    AsyncRemoteFlowRunner,\\n    LocalFlowRunner,\\n    RemoteFlowRunner,\\n)\\n\\n# ---------------------------------------------------------------------------\\n# pytest plugin hooks\\n# ---------------------------------------------------------------------------\\n\\n\\ndef pytest_addoption(parser: pytest.Parser) -> None:\\n    \\\"\\\"\\\"Register lfx-specific CLI options.\\\"\\\"\\\"\\n    group = parser.getgroup(\\\"lfx\\\", \\\"lfx local flow execution options\\\")\\n    group.addoption(\\n        \\\"--lfx-env-file\\\",\\n        dest=\\\"lfx_env_file\\\",\\n        default=None,\\n        metavar=\\\"PATH\\\",\\n        help=\\\"Path to a .env file loaded before each flow execution.\\\",\\n    )\\n    group.addoption(\\n        \\\"--lfx-timeout\\\",\\n        dest=\\\"lfx_timeout\\\",\\n        default=None,\\n        type=float,\\n        metavar=\\\"SECONDS\\\",\\n        help=\\\"Default timeout in seconds for flow execution (0 = no limit).\\\",\\n    )\\n    group.addoption(\\n        \\\"--lfx-flow-dir\\\",\\n        dest=\\\"lfx_flow_dir\\\",\\n        default=None,\\n        metavar=\\\"DIR\\\",\\n        help=\\\"Base directory for resolving relative flow paths (default: cwd).\\\",\\n    )\\n\\n    # Guard against duplicate registration when langflow-sdk[testing] is also installed.\\n    # Both plugins expose the same --langflow-* options; only register them once.\\n    remote = parser.getgroup(\\\"langflow\\\", \\\"Langflow remote integration testing options\\\")\\n    _remote_opts = {\\n        \\\"--langflow-env\\\": {\\n            \\\"dest\\\": \\\"langflow_env\\\",\\n            \\\"default\\\": None,\\n            \\\"metavar\\\": \\\"NAME\\\",\\n            \\\"help\\\": (\\n                \\\"Named environment from .lfx/environments.yaml or langflow-environments.toml. \\\"\\n                \\\"When set, flow_runner targets the remote instance instead of running locally.\\\"\\n            ),\\n        },\\n        \\\"--langflow-url\\\": {\\n            \\\"dest\\\": \\\"langflow_url\\\",\\n            \\\"default\\\": None,\\n            \\\"metavar\\\": \\\"URL\\\",\\n            \\\"help\\\": \\\"Base URL of the remote Langflow instance (overrides --langflow-env).\\\",\\n        },\\n        \\\"--langflow-api-key\\\": {\\n            \\\"dest\\\": \\\"langflow_api_key\\\",\\n            \\\"default\\\": None,\\n            \\\"metavar\\\": \\\"KEY\\\",\\n            \\\"help\\\": \\\"API key for the remote Langflow instance.\\\",\\n        },\\n        \\\"--langflow-environments-file\\\": {\\n            \\\"dest\\\": \\\"langflow_environments_file\\\",\\n            \\\"default\\\": None,\\n            \\\"metavar\\\": \\\"PATH\\\",\\n            \\\"help\\\": \\\"Path to environments config file (.yaml or .toml; overrides default lookup).\\\",\\n        },\\n    }\\n    for flag, kwargs in _remote_opts.items():\\n        with contextlib.suppress(ValueError):\\n            remote.addoption(flag, **kwargs)\\n\\n\\ndef pytest_configure(config: pytest.Config) -> None:\\n    \\\"\\\"\\\"Register custom markers so pytest --strict-markers does not reject them.\\\"\\\"\\\"\\n    config.addinivalue_line(\\n        \\\"markers\\\",\\n        \\\"lfx_env_file(path): path to a .env file loaded before this test's flow execution\\\",\\n    )\\n    config.addinivalue_line(\\n        \\\"markers\\\",\\n        \\\"lfx_timeout(seconds): timeout in seconds for this test's flow execution\\\",\\n    )\\n    config.addinivalue_line(\\n        \\\"markers\\\",\\n        \\\"integration: integration test that requires a live Langflow instance\\\",\\n    )\\n\\n\\n_SKIP_NO_REMOTE = (\\n    \\\"No remote Langflow connection configured. \\\"\\n    \\\"Pass --langflow-url <URL> or --langflow-env <NAME> to run against a live instance.\\\"\\n)\\n\\n\\ndef _resolve_remote_client(request: pytest.FixtureRequest) -> Any | None:\\n    \\\"\\\"\\\"Return a sync SDK client if remote options are configured, else ``None``.\\n\\n    Priority:\\n    1. ``--langflow-url`` / ``LANGFLOW_URL`` -- direct URL (with optional ``--langflow-api-key``)\\n    2. ``--langflow-env`` / ``LANGFLOW_ENV`` -- named environment from TOML/YAML file\\n    \\\"\\\"\\\"\\n    url: str | None = request.config.getoption(\\\"langflow_url\\\", default=None) or os.environ.get(\\\"LANGFLOW_URL\\\")\\n    env_name: str | None = request.config.getoption(\\\"langflow_env\\\", default=None) or os.environ.get(\\\"LANGFLOW_ENV\\\")\\n\\n    if not url and not env_name:\\n        return None\\n\\n    try:\\n        import langflow_sdk  # type: ignore[import-untyped]\\n    except ImportError:\\n        pytest.skip(\\\"langflow-sdk is required for remote testing. Install: pip install langflow-sdk\\\")\\n\\n    if url:\\n        api_key: str | None = request.config.getoption(\\\"langflow_api_key\\\", default=None) or os.environ.get(\\n            \\\"LANGFLOW_API_KEY\\\"\\n        )\\n        return langflow_sdk.Client(base_url=url, api_key=api_key)\\n\\n    # Named environment\\n    env_file: str | None = request.config.getoption(\\\"langflow_environments_file\\\", default=None) or os.environ.get(\\n        \\\"LANGFLOW_ENVIRONMENTS_FILE\\\"\\n    )\\n    try:\\n        from pathlib import Path as _Path\\n\\n        from langflow_sdk.environments import get_client  # type: ignore[import-untyped]\\n\\n        return get_client(env_name, config_file=_Path(env_file) if env_file else None)\\n    except Exception as exc:  # noqa: BLE001\\n        pytest.skip(f\\\"Could not configure Langflow environment {env_name!r}: {exc}\\\")\\n\\n\\ndef _resolve_async_remote_client(request: pytest.FixtureRequest) -> Any | None:\\n    \\\"\\\"\\\"Return an async SDK client if remote options are configured, else ``None``.\\\"\\\"\\\"\\n    url: str | None = request.config.getoption(\\\"langflow_url\\\", default=None) or os.environ.get(\\\"LANGFLOW_URL\\\")\\n    env_name: str | None = request.config.getoption(\\\"langflow_env\\\", default=None) or os.environ.get(\\\"LANGFLOW_ENV\\\")\\n\\n    if not url and not env_name:\\n        return None\\n\\n    try:\\n        import langflow_sdk  # type: ignore[import-untyped]\\n    except ImportError:\\n        pytest.skip(\\\"langflow-sdk is required for remote testing. Install: pip install langflow-sdk\\\")\\n\\n    if url:\\n        api_key: str | None = request.config.getoption(\\\"langflow_api_key\\\", default=None) or os.environ.get(\\n            \\\"LANGFLOW_API_KEY\\\"\\n        )\\n        return langflow_sdk.AsyncClient(base_url=url, api_key=api_key)\\n\\n    env_file: str | None = request.config.getoption(\\\"langflow_environments_file\\\", default=None) or os.environ.get(\\n        \\\"LANGFLOW_ENVIRONMENTS_FILE\\\"\\n    )\\n    try:\\n        from pathlib import Path as _Path\\n\\n        from langflow_sdk.environments import get_async_client  # type: ignore[import-untyped]\\n\\n        return get_async_client(env_name, config_file=_Path(env_file) if env_file else None)\\n    except Exception as exc:  # noqa: BLE001\\n        pytest.skip(f\\\"Could not configure Langflow environment {env_name!r}: {exc}\\\")\\n\\n\\ndef _get_marker_arg(request: pytest.FixtureRequest, name: str) -> Any:\\n    \\\"\\\"\\\"Return the first positional argument of marker *name*, or ``None``.\\\"\\\"\\\"\\n    marker = request.node.get_closest_marker(name)\\n    return marker.args[0] if marker and marker.args else None\\n\\n\\ndef _resolve_runner_config(\\n    request: pytest.FixtureRequest,\\n) -> tuple[str | None, float | None, Path | None]:\\n    \\\"\\\"\\\"Return ``(env_file, timeout, base_dir)`` with marker > CLI > env-var precedence.\\\"\\\"\\\"\\n    # env_file: marker > --lfx-env-file > LFX_ENV_FILE\\n    env_file: str | None = (\\n        _get_marker_arg(request, \\\"lfx_env_file\\\")\\n        or request.config.getoption(\\\"lfx_env_file\\\", default=None)\\n        or os.environ.get(\\\"LFX_ENV_FILE\\\")\\n    )\\n\\n    # timeout: marker > --lfx-timeout > LFX_TIMEOUT\\n    timeout: float | None = _get_marker_arg(request, \\\"lfx_timeout\\\")\\n    if timeout is None:\\n        raw_t = request.config.getoption(\\\"lfx_timeout\\\", default=None) or os.environ.get(\\\"LFX_TIMEOUT\\\")\\n        if raw_t is not None:\\n            with contextlib.suppress(TypeError, ValueError):\\n                timeout = float(raw_t)\\n\\n    # base_dir: --lfx-flow-dir > LFX_FLOW_DIR > None (defaults to cwd in runner)\\n    dir_str: str | None = request.config.getoption(\\\"lfx_flow_dir\\\", default=None) or os.environ.get(\\\"LFX_FLOW_DIR\\\")\\n    base_dir: Path | None = Path(dir_str) if dir_str else None\\n\\n    return env_file, timeout, base_dir\\n\\n\\n@pytest.fixture\\ndef flow_runner(\\n    request: pytest.FixtureRequest,\\n) -> LocalFlowRunner | RemoteFlowRunner:\\n    \\\"\\\"\\\"Fixture providing a sync flow runner -- local or remote depending on CLI options.\\n\\n    **Local mode** (default)\\n        Runs the flow in-process.  Configure with:\\n\\n        * ``@pytest.mark.lfx_env_file(path)`` / ``@pytest.mark.lfx_timeout(seconds)``\\n        * ``--lfx-env-file`` / ``--lfx-timeout`` / ``--lfx-flow-dir``\\n        * ``LFX_ENV_FILE`` / ``LFX_TIMEOUT`` / ``LFX_FLOW_DIR``\\n\\n    **Remote mode** (when ``--langflow-env`` or ``--langflow-url`` is supplied)\\n        Calls the live Langflow API.  Requires ``langflow-sdk``.\\n\\n        * ``--langflow-env <NAME>`` -- named environment from ``.lfx/environments.yaml``\\n        * ``--langflow-url <URL>`` -- direct URL\\n        * ``--langflow-api-key <KEY>`` / ``LANGFLOW_API_KEY``\\n        * ``--langflow-environments-file <PATH>`` / ``LANGFLOW_ENVIRONMENTS_FILE``\\n        * ``LANGFLOW_ENV`` / ``LANGFLOW_URL``\\n\\n    Example (local)::\\n\\n        def test_greeting(flow_runner):\\n            result = flow_runner(\\\"flows/greeting.json\\\", input_value=\\\"Hello\\\")\\n            assert result.ok\\n\\n    Example (remote -- run with ``pytest --langflow-env staging``)::\\n\\n        @pytest.mark.integration\\n        def test_greeting(flow_runner):\\n            result = flow_runner(\\\"greeting-endpoint\\\", \\\"Hello!\\\")\\n            assert result.first_text_output() is not None\\n    \\\"\\\"\\\"\\n    client = _resolve_remote_client(request)\\n    if client is not None:\\n        return RemoteFlowRunner(client)\\n\\n    env_file, timeout, base_dir = _resolve_runner_config(request)\\n    return LocalFlowRunner(\\n        default_env_file=env_file,\\n        default_timeout=timeout,\\n        base_dir=base_dir,\\n    )\\n\\n\\n@pytest.fixture\\ndef async_flow_runner(\\n    request: pytest.FixtureRequest,\\n) -> AsyncLocalFlowRunner | AsyncRemoteFlowRunner:\\n    \\\"\\\"\\\"Fixture providing an async flow runner -- local or remote depending on CLI options.\\n\\n    Same mode-selection logic as :func:`flow_runner`.\\n\\n    Example (local)::\\n\\n        async def test_greeting(async_flow_runner):\\n            result = await async_flow_runner(\\\"flows/greeting.json\\\", input_value=\\\"Hi\\\")\\n            assert result.ok\\n\\n    Example (remote)::\\n\\n        @pytest.mark.integration\\n        async def test_greeting(async_flow_runner):\\n            result = await async_flow_runner(\\\"greeting-endpoint\\\", \\\"Hi!\\\")\\n            assert result.first_text_output() is not None\\n    \\\"\\\"\\\"\\n    client = _resolve_async_remote_client(request)\\n    if client is not None:\\n        return AsyncRemoteFlowRunner(client)\\n\\n    env_file, timeout, base_dir = _resolve_runner_config(request)\\n    return AsyncLocalFlowRunner(\\n        default_env_file=env_file,\\n        default_timeout=timeout,\\n        base_dir=base_dir,\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/testing/result.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"cc555c72482a52a3abfcf527b73b8b13e0ddcf3493334d1c7816c8a3d6ec831f\",\"content\":\"\\\"\\\"\\\"FlowResult dataclass and helpers for building results from raw dicts.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nfrom dataclasses import dataclass\\nfrom typing import Any\\n\\n_TEXT_REPR_MAX = 60\\n\\n\\n@dataclass\\nclass FlowResult:\\n    \\\"\\\"\\\"Result of a local flow execution via the ``flow_runner`` fixture.\\n\\n    Attributes:\\n        status:   ``\\\"success\\\"`` or ``\\\"error\\\"``.\\n        text:     Primary text output of the flow (first non-empty text/result key).\\n        messages: List of message dicts produced by the flow.\\n        outputs:  Raw outputs dict from graph execution.\\n        logs:     Captured stdout/stderr from execution.\\n        error:    Error message when status is ``\\\"error\\\"``, else ``None``.\\n        timing:   Per-component timing dict when ``timing=True`` was passed, else ``None``.\\n        raw:      The unprocessed result dict returned by ``run_flow()``.\\n    \\\"\\\"\\\"\\n\\n    status: str\\n    text: str | None\\n    messages: list[dict[str, Any]]\\n    outputs: dict[str, Any]\\n    logs: str\\n    error: str | None\\n    timing: dict[str, Any] | None\\n    raw: dict[str, Any]\\n\\n    @property\\n    def ok(self) -> bool:\\n        \\\"\\\"\\\"``True`` when *status* is ``\\\"success\\\"``.\\\"\\\"\\\"\\n        return self.status == \\\"success\\\"\\n\\n    def first_text_output(self) -> str | None:\\n        \\\"\\\"\\\"Return the primary text output, or ``None`` if there is none.\\n\\n        Convenience alias for :attr:`text`, compatible with the\\n        ``langflow_sdk.RunResponse`` interface so test code works against\\n        both local and remote runners without changes.\\n        \\\"\\\"\\\"\\n        return self.text\\n\\n    def __repr__(self) -> str:\\n        snippet = (\\n            repr(self.text[:_TEXT_REPR_MAX] + \\\"\\\\u2026\\\")\\n            if self.text and len(self.text) > _TEXT_REPR_MAX\\n            else repr(self.text)\\n        )\\n        return f\\\"FlowResult(status={self.status!r}, text={snippet})\\\"\\n\\n\\ndef _build_result(raw: dict[str, Any]) -> FlowResult:\\n    \\\"\\\"\\\"Construct a :class:`FlowResult` from the dict returned by ``run_flow()``.\\\"\\\"\\\"\\n    # ``success`` may be absent (treat as True for forward compat)\\n    is_error = (raw.get(\\\"success\\\") is False) or raw.get(\\\"type\\\") == \\\"error\\\"\\n    status = \\\"error\\\" if is_error else \\\"success\\\"\\n\\n    # Extract primary text from several candidate keys, in priority order\\n    text: str | None = None\\n    for key in (\\\"result\\\", \\\"text\\\", \\\"output\\\"):\\n        val = raw.get(key)\\n        if val is not None:\\n            text = val if isinstance(val, str) else json.dumps(val)\\n            break\\n\\n    messages: list[dict[str, Any]] = raw.get(\\\"messages\\\") or []\\n    if not isinstance(messages, list):\\n        messages = []\\n\\n    outputs: dict[str, Any] = raw.get(\\\"outputs\\\") or raw.get(\\\"result_dict\\\") or {}\\n    if not isinstance(outputs, dict):\\n        outputs = {}\\n\\n    error_msg: str | None = None\\n    if is_error:\\n        error_msg = raw.get(\\\"exception_message\\\") or raw.get(\\\"error\\\") or \\\"Unknown error\\\"\\n\\n    return FlowResult(\\n        status=status,\\n        text=text,\\n        messages=messages,\\n        outputs=outputs,\\n        logs=raw.get(\\\"logs\\\", \\\"\\\"),\\n        error=error_msg,\\n        timing=raw.get(\\\"timing\\\"),\\n        raw=raw,\\n    )\\n\\n\\ndef _build_result_from_sdk_response(response: Any) -> FlowResult:\\n    \\\"\\\"\\\"Convert a ``langflow_sdk.RunResponse`` to a :class:`FlowResult`.\\n\\n    Extracts text, messages, and raw outputs from the SDK response so that\\n    test assertions written against :class:`FlowResult` work identically\\n    whether the runner is local or remote.\\n    \\\"\\\"\\\"\\n    text = response.first_text_output()\\n\\n    messages: list[dict[str, Any]] = []\\n    outputs: dict[str, Any] = {}\\n    for i, out in enumerate(response.outputs):\\n        outputs[str(i)] = out.results\\n        for component_out in out.outputs:\\n            msg = component_out.get(\\\"results\\\", {}).get(\\\"message\\\")\\n            if isinstance(msg, dict):\\n                messages.append(msg)\\n\\n    return FlowResult(\\n        status=\\\"success\\\",\\n        text=text,\\n        messages=messages,\\n        outputs=outputs,\\n        logs=\\\"\\\",\\n        error=None,\\n        timing=None,\\n        raw=response.model_dump(),\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/testing/runners.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"bacd5fbb463d38442b778324fdae7a3aab165bc6de5b3987d58a8efefc372de9\",\"content\":\"\\\"\\\"\\\"Flow runner classes and internal helpers for local and remote execution.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nimport copy\\nimport json\\nfrom pathlib import Path\\nfrom typing import Any\\n\\nfrom lfx.testing.result import FlowResult, _build_result, _build_result_from_sdk_response\\n\\n# ---------------------------------------------------------------------------\\n# Internal helpers\\n# ---------------------------------------------------------------------------\\n\\n\\ndef _apply_tweaks(flow_dict: dict[str, Any], tweaks: dict[str, dict[str, Any]]) -> dict[str, Any]:\\n    \\\"\\\"\\\"Return a *deep copy* of *flow_dict* with template field values patched.\\n\\n    *tweaks* maps a node identifier -- one of the node's ``id``, ``data.type``,\\n    or ``display_name`` -- to a ``{field_name: new_value}`` dict.  All nodes\\n    whose identifier matches a tweak key are updated.\\n    \\\"\\\"\\\"\\n    flow = copy.deepcopy(flow_dict)\\n    nodes = flow.get(\\\"data\\\", {}).get(\\\"nodes\\\", [])\\n    for node in nodes:\\n        node_data: dict = node.get(\\\"data\\\") or {}\\n        node_id: str = node.get(\\\"id\\\", \\\"\\\")\\n        node_type: str = node_data.get(\\\"type\\\", \\\"\\\")\\n        node_obj: dict = node_data.get(\\\"node\\\") or {}\\n        display_name: str = node_obj.get(\\\"display_name\\\", \\\"\\\")\\n        template: dict = node_obj.get(\\\"template\\\") or {}\\n\\n        for tweak_key, field_overrides in tweaks.items():\\n            if tweak_key not in (node_id, node_type, display_name):\\n                continue\\n            for fname, fvalue in field_overrides.items():\\n                if fname not in template:\\n                    continue\\n                if isinstance(template[fname], dict):\\n                    template[fname][\\\"value\\\"] = fvalue\\n                else:\\n                    template[fname] = fvalue\\n    return flow\\n\\n\\ndef _load_dotenv(env_file: str | Path) -> None:\\n    \\\"\\\"\\\"Load environment variables from *env_file* using python-dotenv.\\\"\\\"\\\"\\n    from dotenv import load_dotenv\\n\\n    load_dotenv(str(env_file), override=True)\\n\\n\\ndef _resolve_flow_args(\\n    flow: str | Path | dict[str, Any],\\n    tweaks: dict[str, dict[str, Any]] | None,\\n    base_dir: Path,\\n) -> tuple[Path | None, str | None]:\\n    \\\"\\\"\\\"Return ``(script_path, flow_json)`` suitable for passing to ``run_flow()``.\\n\\n    When *tweaks* are requested for a JSON flow, the file is loaded, patched,\\n    and returned as an inline JSON string so that ``run_flow()`` picks up the\\n    overrides without modifying any file on disk.\\n    \\\"\\\"\\\"\\n    if isinstance(flow, dict):\\n        patched = _apply_tweaks(flow, tweaks) if tweaks else flow\\n        return None, json.dumps(patched)\\n\\n    flow_path = Path(flow)\\n    if not flow_path.is_absolute():\\n        flow_path = base_dir / flow_path\\n\\n    if tweaks and flow_path.suffix.lower() == \\\".json\\\":\\n        try:\\n            raw_dict = json.loads(flow_path.read_text(encoding=\\\"utf-8\\\"))\\n            return None, json.dumps(_apply_tweaks(raw_dict, tweaks))\\n        except Exception:  # noqa: BLE001\\n            import logging\\n\\n            logging.getLogger(__name__).debug(\\n                \\\"Failed to apply tweaks to %s; using unmodified flow\\\", flow_path, exc_info=True\\n            )\\n\\n    return flow_path, None\\n\\n\\n# ---------------------------------------------------------------------------\\n# Async core execution\\n# ---------------------------------------------------------------------------\\n\\n\\nasync def _run_async(\\n    *,\\n    script_path: Path | None,\\n    flow_json: str | None,\\n    input_value: str | None,\\n    check_variables: bool,\\n    global_variables: dict[str, str] | None,\\n    session_id: str | None,\\n    user_id: str | None,\\n    timing: bool,\\n    timeout: float | None,\\n) -> dict[str, Any]:\\n    \\\"\\\"\\\"Invoke ``run_flow()`` with an optional timeout; always returns a dict.\\\"\\\"\\\"\\n    from lfx.run.base import RunError, run_flow\\n\\n    async def _inner() -> dict:\\n        return await run_flow(\\n            script_path=script_path,\\n            flow_json=flow_json,\\n            input_value=input_value,\\n            check_variables=check_variables,\\n            global_variables=global_variables,\\n            session_id=session_id,\\n            user_id=user_id,\\n            timing=timing,\\n        )\\n\\n    try:\\n        if timeout is not None:\\n            return await asyncio.wait_for(_inner(), timeout=timeout)\\n        return await _inner()\\n    except asyncio.TimeoutError:\\n        return {\\n            \\\"success\\\": False,\\n            \\\"type\\\": \\\"error\\\",\\n            \\\"exception_type\\\": \\\"TimeoutError\\\",\\n            \\\"exception_message\\\": f\\\"Flow execution timed out after {timeout:.1f}s\\\",\\n        }\\n    except RunError as exc:\\n        orig = exc.original_exception\\n        return {\\n            \\\"success\\\": False,\\n            \\\"type\\\": \\\"error\\\",\\n            \\\"exception_type\\\": type(orig).__name__ if orig else \\\"RunError\\\",\\n            \\\"exception_message\\\": str(exc),\\n        }\\n    except Exception as exc:  # noqa: BLE001\\n        return {\\n            \\\"success\\\": False,\\n            \\\"type\\\": \\\"error\\\",\\n            \\\"exception_type\\\": type(exc).__name__,\\n            \\\"exception_message\\\": str(exc),\\n        }\\n\\n\\ndef _run_sync(**kwargs: Any) -> dict[str, Any]:\\n    \\\"\\\"\\\"Run ``_run_async`` synchronously, handling already-running event loops.\\n\\n    When called from inside a running event loop (e.g. a ``pytest-asyncio``\\n    test that requests the sync ``flow_runner`` fixture), the coroutine is\\n    dispatched to a fresh thread with its own event loop so we don't deadlock.\\n    \\\"\\\"\\\"\\n    coro = _run_async(**kwargs)\\n\\n    try:\\n        asyncio.get_running_loop()\\n    except RuntimeError:\\n        # No running loop -- safe to use asyncio.run() directly\\n        return asyncio.run(coro)\\n\\n    # There is a running loop; run in an isolated thread to avoid deadlock\\n    import concurrent.futures\\n\\n    with concurrent.futures.ThreadPoolExecutor(max_workers=1) as pool:\\n        future = pool.submit(asyncio.run, coro)\\n        try:\\n            t = kwargs.get(\\\"timeout\\\")\\n            return future.result(timeout=t)\\n        except Exception as exc:  # noqa: BLE001\\n            return {\\n                \\\"success\\\": False,\\n                \\\"type\\\": \\\"error\\\",\\n                \\\"exception_type\\\": type(exc).__name__,\\n                \\\"exception_message\\\": str(exc),\\n            }\\n\\n\\n# ---------------------------------------------------------------------------\\n# Runner base helpers\\n# ---------------------------------------------------------------------------\\n\\n\\ndef _import_remote_run_request():\\n    \\\"\\\"\\\"Import and return the SDK ``RunRequest`` model with a helpful error.\\\"\\\"\\\"\\n    try:\\n        from langflow_sdk.models import RunRequest  # type: ignore[import-untyped]\\n    except ImportError as exc:\\n        msg = \\\"langflow-sdk is required for remote flow testing. Install: pip install langflow-sdk\\\"\\n        raise ImportError(msg) from exc\\n    return RunRequest\\n\\n\\ndef _build_remote_error_result(exc: Exception) -> FlowResult:\\n    \\\"\\\"\\\"Return a standardized failed ``FlowResult`` for remote runner errors.\\\"\\\"\\\"\\n    return FlowResult(\\n        status=\\\"error\\\",\\n        text=None,\\n        messages=[],\\n        outputs={},\\n        logs=\\\"\\\",\\n        error=str(exc),\\n        timing=None,\\n        raw={},\\n    )\\n\\n\\nclass _BaseLocalFlowRunner:\\n    \\\"\\\"\\\"Shared initialization and argument resolution for local flow runners.\\\"\\\"\\\"\\n\\n    def __init__(\\n        self,\\n        *,\\n        default_env_file: str | Path | None = None,\\n        default_timeout: float | None = None,\\n        base_dir: Path | None = None,\\n    ) -> None:\\n        self._default_env_file = default_env_file\\n        self._default_timeout = default_timeout\\n        self._base_dir = base_dir or Path.cwd()\\n\\n    def _build_run_kwargs(\\n        self,\\n        flow: str | Path | dict[str, Any],\\n        input_value: str | None,\\n        *,\\n        tweaks: dict[str, dict[str, Any]] | None,\\n        global_variables: dict[str, str] | None,\\n        env_file: str | Path | None,\\n        timeout: float | None,\\n        check_variables: bool,\\n        session_id: str | None,\\n        user_id: str | None,\\n        timing: bool,\\n    ) -> dict[str, Any]:\\n        \\\"\\\"\\\"Build keyword arguments shared by sync and async local execution.\\\"\\\"\\\"\\n        if env_file or self._default_env_file:\\n            _load_dotenv(env_file or self._default_env_file)\\n\\n        script_path, flow_json = _resolve_flow_args(flow, tweaks, self._base_dir)\\n        resolved_timeout = timeout if timeout is not None else self._default_timeout\\n\\n        return {\\n            \\\"script_path\\\": script_path,\\n            \\\"flow_json\\\": flow_json,\\n            \\\"input_value\\\": input_value,\\n            \\\"check_variables\\\": check_variables,\\n            \\\"global_variables\\\": global_variables,\\n            \\\"session_id\\\": session_id,\\n            \\\"user_id\\\": user_id,\\n            \\\"timing\\\": timing,\\n            \\\"timeout\\\": resolved_timeout,\\n        }\\n\\n\\nclass _BaseRemoteFlowRunner:\\n    \\\"\\\"\\\"Shared request/error handling for sync and async remote runners.\\\"\\\"\\\"\\n\\n    def __init__(self, client: Any) -> None:\\n        self._client = client\\n\\n    def _build_run_request(\\n        self,\\n        *,\\n        input_value: str,\\n        input_type: str,\\n        output_type: str,\\n        tweaks: dict[str, Any] | None,\\n    ):\\n        \\\"\\\"\\\"Create an SDK ``RunRequest`` for remote execution.\\\"\\\"\\\"\\n        run_request_model = _import_remote_run_request()\\n        return run_request_model(\\n            input_value=input_value,\\n            input_type=input_type,\\n            output_type=output_type,\\n            tweaks=tweaks,\\n        )\\n\\n\\n# ---------------------------------------------------------------------------\\n# Callable classes\\n# ---------------------------------------------------------------------------\\n\\n\\nclass LocalFlowRunner(_BaseLocalFlowRunner):\\n    \\\"\\\"\\\"Sync callable returned by the :func:`flow_runner` fixture.\\n\\n    Instantiate via the ``flow_runner`` pytest fixture -- do not construct\\n    directly in test code.  Call it like a function::\\n\\n        def test_greeting(flow_runner):\\n            result = flow_runner(\\\"flows/greeting.json\\\", input_value=\\\"Hello\\\")\\n            assert result.status == \\\"success\\\"\\n            assert \\\"hello\\\" in result.text.lower()\\n\\n    The first positional argument can be:\\n\\n    * A path string or :class:`~pathlib.Path` to a ``.json`` or ``.py`` flow file.\\n    * A ``dict`` (already-parsed flow JSON).\\n\\n    Relative paths are resolved against ``--lfx-flow-dir`` (default: ``cwd``).\\n    \\\"\\\"\\\"\\n\\n    def __call__(\\n        self,\\n        flow: str | Path | dict[str, Any],\\n        input_value: str | None = None,\\n        *,\\n        tweaks: dict[str, dict[str, Any]] | None = None,\\n        global_variables: dict[str, str] | None = None,\\n        env_file: str | Path | None = None,\\n        timeout: float | None = None,\\n        check_variables: bool = False,\\n        session_id: str | None = None,\\n        user_id: str | None = None,\\n        timing: bool = False,\\n    ) -> FlowResult:\\n        \\\"\\\"\\\"Execute a flow synchronously and return a :class:`FlowResult`.\\n\\n        Args:\\n            flow: Path (``.json``/``.py``) or parsed flow dict.\\n            input_value: Chat/text input string to pass into the flow.\\n            tweaks: Component-level overrides -- ``{node_id|type|name: {field: value}}``.\\n            global_variables: Key->value pairs injected into the graph context.\\n            env_file: ``.env`` file loaded before execution (overrides fixture default).\\n            timeout: Seconds before aborting; ``None`` means no limit.\\n            check_variables: Validate that global variables exist in the environment.\\n            session_id: Session ID for memory isolation between calls.\\n            user_id: User ID attached to the graph.\\n            timing: Include per-component timing in :attr:`FlowResult.timing`.\\n        \\\"\\\"\\\"\\n        raw = _run_sync(\\n            **self._build_run_kwargs(\\n                flow,\\n                input_value,\\n                tweaks=tweaks,\\n                global_variables=global_variables,\\n                env_file=env_file,\\n                timeout=timeout,\\n                check_variables=check_variables,\\n                session_id=session_id,\\n                user_id=user_id,\\n                timing=timing,\\n            )\\n        )\\n        return _build_result(raw)\\n\\n\\nclass AsyncLocalFlowRunner(_BaseLocalFlowRunner):\\n    \\\"\\\"\\\"Async callable returned by the :func:`async_flow_runner` fixture.\\n\\n    Use with ``await`` inside an ``async def`` test::\\n\\n        async def test_greeting(async_flow_runner):\\n            result = await async_flow_runner(\\\"flows/greeting.json\\\", input_value=\\\"Hello\\\")\\n            assert result.status == \\\"success\\\"\\n    \\\"\\\"\\\"\\n\\n    async def __call__(\\n        self,\\n        flow: str | Path | dict[str, Any],\\n        input_value: str | None = None,\\n        *,\\n        tweaks: dict[str, dict[str, Any]] | None = None,\\n        global_variables: dict[str, str] | None = None,\\n        env_file: str | Path | None = None,\\n        timeout: float | None = None,\\n        check_variables: bool = False,\\n        session_id: str | None ";
